215	/**
216	 * @brief 写入小端 uint16。
217	 */
218	static void put_le16(uint8_t *p, uint16_t v)
219	{
220	  p[0] = (uint8_t)(v & 0xff);
221	  p[1] = (uint8_t)(v >> 8);
222	}
223	
224	/**
225	 * @brief 写入小端 uint32。
226	 */
227	static void put_le32(uint8_t *p, uint32_t v)
228	{
229	  p[0] = (uint8_t)(v & 0xff);
230	  p[1] = (uint8_t)((v >> 8) & 0xff);
231	  p[2] = (uint8_t)((v >> 16) & 0xff);
232	  p[3] = (uint8_t)((v >> 24) & 0xff);
233	}
234	
235	/**
236	 * @brief 读出小端 uint32。
237	 */
238	static uint32_t get_le32(const uint8_t *p)
239	{
240	  return (uint32_t)p[0] | ((uint32_t)p[1] << 8) |
241	         ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
242	}
243	
244	/**
245	 * @brief 读出小端 uint16。
246	 */
247	static uint16_t get_le16(const uint8_t *p)
248	{
249	  return (uint16_t)((uint16_t)p[0] | ((uint16_t)p[1] << 8));
250	}
