252	/**
253	 * @brief 打包 Device Status（16 字节）加上 Classic BD_ADDR 尾。
254	 *
255	 * 显式打包而不 memcpy 结构体：这是协议边界，App 按字节解码。
256	 */
257	static void status_pack(const struct companion_status *st, uint8_t *out)
258	{
259	  put_le16(out + 0, st->flags);
260	  out[2] = st->battery_pct;
261	  out[3] = st->last_ctrl_op;
262	  put_le32(out + 4, st->storage_free_kb);
263	  put_le32(out + 8, st->uptime_sec);
264	  put_le32(out + 12, st->gnss_rx_count);
265	  memcpy(out + COMPANION_STATUS_LEN, g_classic_addr.addr,
266	         COMPANION_STATUS_ADDR_LEN);
267	}
