269	/** @brief 固定长度字段写入字符串并 NUL 填充。 */
270	static void put_strpad(uint8_t *dst, size_t dst_len, const char *s)
271	{
272	  size_t n;
273	
274	  memset(dst, 0, dst_len);
275	  if (s == NULL || dst_len == 0)
276	    {
277	      return;
278	    }
279	
280	  n = strlen(s);
281	  if (n > dst_len)
282	    {
283	      n = dst_len;
284	    }
285	
286	  memcpy(dst, s, n);
287	}
