348	 */
349	static uint16_t status_ccc_changed(gatts_handle_t srv_handle,
350	                                   bt_address_t *addr, uint16_t attr_handle,
351	                                   const uint8_t *value, uint16_t length,
352	                                   uint16_t offset)
353	{
354	  bool enabled;
355	
356	  (void)srv_handle;
357	  (void)attr_handle;
358	  (void)offset;
359	
360	  if (!companion_is_phone(addr))
361	    {
362	      return length;
363	    }
364	
365	  if (length < 1)
366	    {
367	      return 0;
368	    }
369	
370	  enabled = (value[0] & GATT_CCC_NOTIFY) != 0;
371	
372	  pthread_mutex_lock(&g_ctx.lock);
373	  g_ctx.ccc_enabled = enabled;
374	
375	  /** 订阅后立刻发一份快照，避免 App 等到心跳。 */
376	
377	  if (enabled)
378	    {
379	      g_ctx.notify_req = true;
380	    }
381	
382	  pthread_mutex_unlock(&g_ctx.lock);
383	
384	  LOGD("status subscribe -> %d", (int)enabled);
385	  return length;
386	}
