416	/**
417	 * @brief 手机 TIME_SYNC：写 CLOCK_REALTIME（CONFIG_RTC 时同步硬件 RTC）并可选改时区。
418	 *
419	 * 不在 Control 锁内执行：settimeofday / persist 可能阻塞。
420	 */
421	static void companion_apply_time_sync(const uint8_t *value, uint16_t length)
422	{
423	  uint32_t utc;
424	  int16_t tz_min = 0;
425	  bool have_tz = false;
426	  struct timespec now;
427	  struct timeval tv;
428	  long long delta;
429	
430	  if (value == NULL || length < COMPANION_CTRL_TIME_SYNC_MIN_LEN)
431	    {
432	      return;
433	    }
434	
435	  utc = (uint32_t)value[1]
436	        | ((uint32_t)value[2] << 8)
437	        | ((uint32_t)value[3] << 16)
438	        | ((uint32_t)value[4] << 24);
439	  if (utc < COMPANION_TIME_MIN_UNIX || utc > COMPANION_TIME_MAX_UNIX)
440	    {
441	      LOGI("TIME_SYNC reject utc=%lu", (unsigned long)utc);
442	      return;
443	    }
444	
445	  if (length >= COMPANION_CTRL_TIME_SYNC_LEN)
446	    {
447	      tz_min = (int16_t)((uint16_t)value[5] | ((uint16_t)value[6] << 8));
448	      if (tz_min >= MYVENDOR_DEVCTL_TZ_MIN && tz_min <= MYVENDOR_DEVCTL_TZ_MAX)
449	        {
450	          have_tz = true;
451	        }
452	    }
453	
454	  if (clock_gettime(CLOCK_REALTIME, &now) != 0)
455	    {
456	      now.tv_sec = 0;
457	    }
458	
459	  delta = (long long)now.tv_sec - (long long)utc;
460	  if (delta < 0)
461	    {
462	      delta = -delta;
463	    }
464	
465	  if (now.tv_sec < (time_t)COMPANION_TIME_MIN_UNIX || delta >= 2)
466	    {
467	      tv.tv_sec = (time_t)utc;
468	      tv.tv_usec = 0;
469	      if (settimeofday(&tv, NULL) != 0)
470	        {
471	          syslog(LOG_WARNING, "ble_companion: TIME_SYNC settimeofday errno=%d\n",
472	                 errno);
473	        }
474	      else
475	        {
476	          LOGI("RTC sync utc=%lu tz=%d",
477	               (unsigned long)utc, have_tz ? (int)tz_min : (int)myvendor_devctl_tz_min_get());
478	        }
479	    }
480	
481	  if (have_tz && tz_min != myvendor_devctl_tz_min_get())
482	    {
483	      (void)myvendor_devctl_tz_min_set(tz_min);
484	    }
485	}
