487	/**
488	 * @brief 处理 0xFF13 Control 写（ping、对时、录音、FS 中止、停导航）。
489	 */
490	static uint16_t control_on_write(gatts_handle_t srv_handle,
491	                                 bt_address_t *addr, uint16_t attr_handle,
492	                                 const uint8_t *value, uint16_t length,
493	                                 uint16_t offset)
494	{
495	  uint8_t op;
496	  uint8_t time_buf[COMPANION_CTRL_TIME_SYNC_LEN];
497	  uint16_t time_len = 0;
498	
499	  (void)srv_handle;
500	  (void)attr_handle;
501	  (void)offset;
502	
503	  if (!companion_is_phone(addr))
504	    {
505	      return length;
506	    }
507	
508	  if (length < 1)
509	    {
510	      return 0;
511	    }
512	
513	  op = value[0];
514	
515	  pthread_mutex_lock(&g_ctx.lock);
516	
517	  g_ctx.status.last_ctrl_op = op;
518	
519	  switch (op)
520	    {
521	      case COMPANION_CTRL_NOP:
522	      case COMPANION_CTRL_PING:
523	        break;
524	
525	      case COMPANION_CTRL_TIME_SYNC:
526	        if (length >= COMPANION_CTRL_TIME_SYNC_MIN_LEN)
527	          {
528	            time_len = length > COMPANION_CTRL_TIME_SYNC_LEN
529	                         ? COMPANION_CTRL_TIME_SYNC_LEN
530	                         : length;
531	            memcpy(time_buf, value, time_len);
532	          }
533	        break;
534	
535	      case COMPANION_CTRL_START_RECORD:
536	      case COMPANION_CTRL_STOP_RECORD:
537	        /* 骑行会话由 MCU 判定并写入 0xFF12，不在此翻标志。 */
538	        break;
539	
540	      case COMPANION_CTRL_FS_ABORT:
541	        companion_fs_abort();
542	        break;
543	
544	      case COMPANION_CTRL_SYNC_PREP:
545	        break;
546	
547	      case COMPANION_CTRL_NAV_STOP:
548	        break;
549	
550	      default:
551	        if (companion_bridge_test_ctrl_get())
552	          {
553	            LOGI("unknown control opcode 0x%02x", op);
554	          }
555	        break;
556	    }
557	
558	  /** 每次 Control 写都用带 last_ctrl_op 的状态 notify 应答，作为 App 往返证明。 */
559	
560	  g_ctx.notify_req = true;
561	  pthread_mutex_unlock(&g_ctx.lock);
562	
563	  if (time_len != 0)
564	    {
565	      companion_apply_time_sync(time_buf, time_len);
566	    }
567	
568	  if (companion_bridge_test_ctrl_get())
569	    {
570	      LOGI("ctrl %s (0x%02x) len=%u", ctrl_op_name(op), op, length);
571	    }
572	
573	  return length;
574	}
