593	    }
594	
595	  if (length < COMPANION_GNSS_FIX_LEN)
596	    {
597	      LOGD("gnss write too short: %u", length);
598	      return length;
599	    }
600	
601	  gnss_fix_unpack(value, &fix);
602	  companion_bridge_gnss_set(&fix, mono_ms());
603	
604	  pthread_mutex_lock(&g_ctx.lock);
605	  g_ctx.last_fix     = fix;
606	  g_ctx.fix_valid    = fix.fix_quality != COMPANION_FIX_NONE;
607	  g_ctx.last_gnss_ms = mono_ms();
608	  count = ++g_ctx.status.gnss_rx_count;
609	
610	  if (g_ctx.fix_valid)
611	    {
612	      status_set_flags(COMPANION_STATUS_GPS_PHONE, 0);
613	    }
614	
615	  pthread_mutex_unlock(&g_ctx.lock);
616	
617	  LOGD("gnss #%lu lat=%ld lon=%ld q=%u sats=%u",
618	       (unsigned long)count, (long)fix.lat_e7, (long)fix.lon_e7,
619	       fix.fix_quality, fix.satellites);
620	  (void)count;  /* only read by LOGD, which is compiled out by default */
621	
622	  return length;
623	}
