828	/**
829	 * @brief @p addr 是否是手机 Companion 对端（不是 HR/CSC/CPS 槽位）。
830	 * @param addr GATTS 回调里的对端。
831	 * @return 传感器地址返回 false，让 FS/MTU/状态留在手机链路上。
832	 *
833	 * zblue att_mtu_updated 是全局的：HR 连接会把 ATT 23 报到 GATTS。
834	 * 把该 MTU 套到 Companion 曾让 FS 载荷变成 17 字节，文件传输会坏。
835	 */
836	static bool companion_is_phone(const bt_address_t *addr)
837	{
838	  bool yes = false;
839	
840	  if (addr == NULL || ble_sensor_owns_addr(addr))
841	    {
842	      return false;
843	    }
844	
845	  pthread_mutex_lock(&g_ctx.lock);
846	  if (g_ctx.connected)
847	    {
848	      yes = (memcmp(g_ctx.peer.addr, addr->addr, BT_ADDR_LENGTH) == 0);
849	    }
850	  else
851	    {
852	      /** 连接回调尚未置位时，非传感器对端仍视为手机（首包 MTU/CCC）。
853	       *  FS MTU 另需 g_fs.connected 且地址等于 peer。
854	       */
855	      yes = true;
856	    }
857	
858	  pthread_mutex_unlock(&g_ctx.lock);
859	  return yes;
860	}
