896	/**
897	 * @brief zblue 连接：仅 Peripheral（手机）收紧 7.5 ms / PHY / DLE。
898	 *
899	 * 传感器（central）保持 BT_LE_CONN_PARAM_DEFAULT。7.5 ms / 1 s + PHY+DLE
900	 * 会和 Android 的 45 ms 更新打架（HCI 0x16），发现前就断链。
901	 */
902	static void le_connected(struct bt_conn *conn, uint8_t err)
903	{
904	  struct bt_conn_info info;
905	
906	  if (err != 0 || bt_conn_get_info(conn, &info) != 0 ||
907	      info.type != BT_CONN_TYPE_LE)
908	    {
909	      return;
910	    }
911	
912	  if (info.role == BT_CONN_ROLE_PERIPHERAL)
913	    {
914	      int ret;
915	
916	      ret = bt_conn_le_param_update(conn, BT_LE_CONN_PARAM(6, 6, 0, 400));
917	      LOGD("le interval 7.5 ms ret=%d", ret);
918	
919	#if defined(CONFIG_BT_USER_PHY_UPDATE)
920	      ret = bt_conn_le_phy_update(conn, BT_CONN_LE_PHY_PARAM_2M);
921	      LOGD("le phy 2M ret=%d", ret);
922	#endif
923	
924	#if defined(CONFIG_BT_USER_DATA_LEN_UPDATE)
925	      ret = bt_conn_le_data_len_update(conn, BT_LE_DATA_LEN_PARAM_MAX);
926	      LOGD("le dle max ret=%d", ret);
927	#endif
928	    }
929	}
930	
931	/**
932	 * @brief HCI 断链：central 角色备份通知传感器健康监控。
933	 *
934	 * GATTS 仍走 @ref gatts_disconnect_callback。此处只补传感器，避免
935	 * 手机断链被处理两次。
936	 */
937	static void le_disconnected(struct bt_conn *conn, uint8_t reason)
938	{
939	  struct bt_conn_info info;
940	  bt_address_t addr;
941	
942	  if (bt_conn_get_info(conn, &info) != 0 || info.type != BT_CONN_TYPE_LE)
943	    {
944	      return;
945	    }
946	
947	  memset(&addr, 0, sizeof(addr));
948	  if (info.le.dst != NULL)
949	    {
950	      memcpy(addr.addr, info.le.dst->a.val, BT_ADDR_LENGTH);
951	    }
952	  else if (info.le.remote != NULL)
953	    {
954	      memcpy(addr.addr, info.le.remote->a.val, BT_ADDR_LENGTH);
955	    }
956	
957	  LOGD("le disc role=%s reason=0x%02x",
958	       info.role == BT_CONN_ROLE_CENTRAL ? "central" : "peripheral",
959	       (unsigned)reason);
960	
961	  if (info.role == BT_CONN_ROLE_PERIPHERAL)
962	    {
963	      g_phone_disc_reason = reason;
964	    }
965	
966	  if (info.role == BT_CONN_ROLE_CENTRAL)
967	    {
968	      ble_sensor_on_hci_disconnected(&addr, reason);
969	    }
970	}
