1117	/**
1118	 * @brief 等待 /dev/ttyHCI0（HCPU zblue + LCPU H4）。
1119	 */
1120	static int wait_hci_device(int timeout_secs)
1121	{
1122	  int i;
1123	
1124	  for (i = 0; i < timeout_secs * 10; i++)
1125	    {
1126	      if (!g_running)
1127	        {
1128	          return -EINTR;
1129	        }
1130	
1131	      if (access(HCI_DEV_PATH, F_OK) == 0)
1132	        {
1133	          return 0;
1134	        }
1135	
1136	      if ((i % 10) == 0)
1137	        {
1138	          companion_bridge_heartbeat();
1139	        }
1140	
1141	      usleep(100 * 1000);
1142	    }
1143	
1144	  LOGE("%s missing — enable CONFIG_UART_BTH4 and rebuild", HCI_DEV_PATH);
1145	  return -ENOENT;
1146	}
