1148	/**
1149	 * @brief 适配器已有可用 LE 地址。
1150	 */
1151	static bool adapter_is_usable(void)
1152	{
1153	  bt_adapter_state_t st = bt_adapter_get_state(g_ins);
1154	
1155	  /** 双模板落到 STATE_ON。纯 BLE（无 BREDR）停在 BLE_ON，到不了 Classic ON。 */
1156	
1157	  return st == BT_ADAPTER_STATE_ON || st == BT_ADAPTER_STATE_BLE_ON;
1158	}
