1160	/**
1161	 * @brief 等到适配器变为 ON。
1162	 */
1163	static int wait_adapter_ready(int timeout_secs)
1164	{
1165	  int i;
1166	
1167	  for (i = 0; i < timeout_secs * 10; i++)
1168	    {
1169	      if (!g_running)
1170	        {
1171	          return -EINTR;
1172	        }
1173	
1174	      if (adapter_is_usable())
1175	        {
1176	          return 0;
1177	        }
1178	
1179	      if ((i % 10) == 0)
1180	        {
1181	          companion_bridge_heartbeat();
1182	        }
1183	
1184	      usleep(100 * 1000);
1185	    }
1186	
1187	  LOGE("adapter not ready, state=%d (expect ON or BLE_ON)",
1188	       (int)bt_adapter_get_state(g_ins));
1189	  return -ETIMEDOUT;
1190	}
