1192	/**
1193	 * @brief 构建 ADV + 扫描响应（Helm One-XXXX + 0xFF10 UUID）。
1194	 *
1195	 * 广播服务 UUID，让 App 按 0xFF10 过滤而不是按名字（用户可改名）。
1196	 * 名字放扫描响应：两者塞不进一个 31 字节 legacy PDU。
1197	 * 名字与 USB/MTP 共用 myvendor_identity_name()（产品名 + MAC 后两字节）。
1198	 */
1199	static void build_adv_payload(const bt_address_t *le_addr)
1200	{
1201	  const char *id = myvendor_identity_name();
1202	  size_t name_len;
1203	
1204	  (void)le_addr;
1205	  snprintf(g_dev_name, sizeof(g_dev_name), "%s", id);
1206	
1207	  g_adv_data[0] = 0x02;             /**< Flags AD 长度 */
1208	  g_adv_data[1] = 0x01;             /**< AD 类型：Flags */
1209	  g_adv_data[2] = 0x06;             /**< LE General + 不支持 BR/EDR */
1210	  g_adv_data[3] = 0x03;             /**< UUID16 列表 AD 长度 */
1211	  g_adv_data[4] = 0x03;             /**< AD 类型：完整 16 位 UUID 列表 */
1212	  put_le16(&g_adv_data[5], COMPANION_SERVICE_UUID16);
1213	
1214	  name_len = strlen(g_dev_name);
1215	  if (name_len > sizeof(g_scan_rsp) - 2)
1216	    {
1217	      name_len = sizeof(g_scan_rsp) - 2;
1218	    }
1219	
1220	  g_scan_rsp[0] = (uint8_t)(name_len + 1);
1221	  g_scan_rsp[1] = 0x09;             /**< AD 类型：完整本地名 */
1222	  memcpy(&g_scan_rsp[2], g_dev_name, name_len);
1223	  g_scan_rsp_len = (uint8_t)(name_len + 2);
1224	}
