1226	/**
1227	 * @brief 框架广播已启动（或失败）。status=0 才算真正在播。
1228	 */
1229	static void on_advertising_start(bt_advertiser_t *adv, uint8_t adv_id,
1230	                                 uint8_t status)
1231	{
1232	  LOGD("advertising started id=%u status=%u name=%s",
1233	       adv_id, status, g_dev_name);
1234	  if (status == BT_ADV_STATUS_SUCCESS)
1235	    {
1236	      g_adv_active = true;
1237	      return;
1238	    }
1239	
1240	  g_adv_active = false;
1241	  if (g_adv == adv)
1242	    {
1243	      g_adv = NULL;
1244	    }
1245	
1246	  ble_supervisor_report(BLE_SUPERVISOR_FAULT_ADV, mono_ms());
1247	  pthread_mutex_lock(&g_ctx.lock);
1248	  if (!g_ctx.connected && !g_hold_le_adv && !g_policy_adv_off)
1249	    {
1250	      g_ctx.adv_restart = true;
1251	    }
1252	
1253	  pthread_mutex_unlock(&g_ctx.lock);
1254	}
