1292	/**
1293	 * @brief 启动 LE 广播（观察者占用或已有句柄时除外）。
1294	 *
1295	 * 走 `bt_le_start_advertising`。SF32 的 Ext Adv 由板卡 SAL override
1296	 * 换成 legacy HCI；成功时回调 `advertising started id=… status=0`。
1297	 */
1298	static int companion_start_advertising(void)
1299	{
1300	  ble_adv_params_t params;
1301	
1302	  if (g_hold_le_adv || g_policy_adv_off)
1303	    {
1304	      return 0;
1305	    }
1306	
1307	  if (g_adv != NULL)
1308	    {
1309	      return 0;
1310	    }
1311	
1312	  if (g_ins == NULL)
1313	    {
1314	      return -1;
1315	    }
1316	
1317	  memset(&params, 0, sizeof(params));
1318	  params.adv_type        = BT_LE_LEGACY_ADV_IND;
1319	  params.peer_addr_type  = BT_LE_ADDR_TYPE_PUBLIC;
1320	  params.own_addr_type   = BT_LE_ADDR_TYPE_PUBLIC;
1321	  params.interval        = ADV_INTERVAL_UNITS;
1322	  params.tx_power        = 0;
1323	  params.channel_map     = BT_LE_ADV_CHANNEL_DEFAULT;
1324	  params.filter_policy   = BT_LE_ADV_FILTER_WHITE_LIST_FOR_NONE;
1325	
1326	  companion_bridge_phase_set("hci_adv");
1327	  g_adv = bt_le_start_advertising(g_ins, &params,
1328	                                  g_adv_data, sizeof(g_adv_data),
1329	                                  g_scan_rsp, g_scan_rsp_len,
1330	                                  (advertiser_callback_t *)&g_adv_cbs);
1331	  if (g_adv == NULL)
1332	    {
1333	#ifdef CONFIG_MYVENDOR_BLE_LOG
1334	      static uint32_t last_adv_fail_ms;
1335	      uint32_t now = mono_ms();
1336	
1337	      if (last_adv_fail_ms == 0 ||
1338	          myvendor_mono_elapsed_ms(now, last_adv_fail_ms) >= 2000u)
1339	        {
1340	          last_adv_fail_ms = now;
1341	          BLE_LOG("start_adv failed skip=%d hold=%d radio_off=%d",
1342	                  sf32lb52_bt_hci_skip_sync() ? 1 : 0,
1343	                  g_hold_le_adv ? 1 : 0,
1344	                  g_policy_adv_off ? 1 : 0);
1345	        }
1346	#endif
1347	      /* 双角色时间片里 start 失败是常态，由 12 s ADV stall 再升级。 */
1348	      return -1;
1349	    }
1350	
1351	  pthread_mutex_lock(&g_ctx.lock);
1352	  g_ctx.adv_restart = false;
1353	  pthread_mutex_unlock(&g_ctx.lock);
1354	  LOGD("advertising requested name=%s", g_dev_name);
1355	  return 0;
1356	}
