1394	/**
1395	 * @brief 同类故障达阈值、或 HCI RX 持续 -ENOMEM 后，disable/enable adapter。
1396	 *
1397	 * 普通 ADV/SCAN 故障在手机已连接时跳过，保留 pending 待断开后重试。
1398	 * HCI 卡住时连接状态机也是僵尸，必须照样 cycle。
1399	 */
1400	static int companion_adapter_cycle(uint32_t now_ms)
1401	{
1402	  bt_status_t ret;
1403	  bool sensor_on;
1404	  bool radio_on;
1405	
1406	  pthread_mutex_lock(&g_ctx.lock);
1407	  g_ctx.connected   = false;
1408	  g_ctx.ccc_enabled = false;
1409	  g_ctx.mtu         = 0;
1410	  pthread_mutex_unlock(&g_ctx.lock);
1411	  sf32lb52_bt_hci_rx_stall_clear();
1412	
1413	  ble_supervisor_cycle_begin(now_ms);
1414	
1415	  sensor_on = ble_sensor_is_started() || companion_bridge_policy_sensor();
1416	  radio_on  = !g_policy_adv_off;
1417	  BLE_LOG("adapter cycle begin skip=%d sensor=%d radio=%d",
1418	          sf32lb52_bt_hci_skip_sync() ? 1 : 0,
1419	          sensor_on ? 1 : 0, radio_on ? 1 : 0);
1420	
1421	  companion_bridge_phase_set("sensor_stop");
1422	  ble_sensor_stop();
1423	  companion_bridge_phase_set("hci_adv_stop");
1424	  companion_stop_advertising();
1425	
1426	  companion_bridge_phase_set("adapter_disable");
1427	  ret = bt_adapter_disable(g_ins);
1428	  if (ret != BT_STATUS_SUCCESS && ret != BT_STATUS_DONE)
1429	    {
1430	      LOGE("adapter disable failed: %d", (int)ret);
1431	      ble_supervisor_report(BLE_SUPERVISOR_FAULT_ADAPTER, now_ms);
1432	      ble_supervisor_cycle_complete(false, now_ms);
1433	      return -1;
1434	    }
1435	
1436	  {
1437	    uint32_t left = ADAPTER_CYCLE_OFF_MS;
1438	
1439	    while (left > 0 && g_running)
1440	      {
1441	        uint32_t slice = left > 200u ? 200u : left;
1442	
1443	        companion_bridge_heartbeat();
1444	        usleep(slice * 1000u);
1445	        left -= slice;
1446	      }
1447	
1448	    if (!g_running)
1449	      {
1450	        ble_supervisor_cycle_complete(false, now_ms);
1451	        return -EINTR;
1452	      }
1453	  }
1454	
1455	  LOGI("adapter off done, enable after %u ms",
1456	       (unsigned)ADAPTER_CYCLE_OFF_MS);
1457	
1458	  ret = bt_adapter_enable(g_ins);
1459	  if (ret != BT_STATUS_SUCCESS && ret != BT_STATUS_DONE)
1460	    {
1461	      LOGE("adapter enable failed: %d", (int)ret);
1462	      ble_supervisor_report(BLE_SUPERVISOR_FAULT_ADAPTER, now_ms);
1463	      ble_supervisor_cycle_complete(false, now_ms);
1464	      return -1;
1465	    }
1466	
1467	  if (wait_adapter_ready(ADAPTER_CYCLE_WAIT_SECS) != 0)
1468	    {
1469	      ble_supervisor_report(BLE_SUPERVISOR_FAULT_ADAPTER, now_ms);
1470	      ble_supervisor_cycle_complete(false, now_ms);
1471	      return -1;
1472	    }
1473	
1474	  (void)bt_conn_cb_register(&g_le_conn_cb);
1475	
1476	  if (radio_on && !companion_phone_connected())
1477	    {
1478	      pthread_mutex_lock(&g_ctx.lock);
1479	      g_ctx.adv_restart = true;
1480	      pthread_mutex_unlock(&g_ctx.lock);
1481	    }
1482	
1483	  if (sensor_on)
1484	    {
1485	      companion_apply_sensor_policy(true);
1486	    }
1487	
1488	  ble_supervisor_cycle_complete(true, now_ms);
1489	  LOGI("adapter cycle done sensor=%d radio=%d",
1490	       (int)sensor_on, (int)radio_on);
1491	  return 0;
1492	}
1493	
1494	/**
1495	 * @brief 监控广播停滞、HCI RX 卡住与 adapter cycle 请求。
1496	 */
1497	static void companion_supervisor_pump(uint32_t now_ms)
1498	{
1499	  enum ble_supervisor_fault reason;
1500	  bool expected;
1501	  bool active;
1502	  bool skip_while_connected;
1503	
1504	  ble_supervisor_tick(now_ms);
1505	
1506	  if (sf32lb52_bt_hci_rx_stalled(HCI_RX_STALL_MS) ||
1507	      companion_bridge_diag_cycle_take())
1508	    {
1509	#ifdef CONFIG_MYVENDOR_BLE_LOG
1510	      static uint32_t last_rxstall_log_ms;
1511	
1512	      if (sf32lb52_bt_hci_rx_stalled(HCI_RX_STALL_MS) &&
1513	          (last_rxstall_log_ms == 0 ||
1514	           myvendor_mono_elapsed_ms(now_ms, last_rxstall_log_ms) >= 2000u))
1515	        {
1516	          last_rxstall_log_ms = now_ms;
1517	          BLE_LOG("supervisor rxstall skip=%d phone=%d hold=%d adv=%d",
1518	                  sf32lb52_bt_hci_skip_sync() ? 1 : 0,
1519	                  companion_phone_connected() ? 1 : 0,
1520	                  g_hold_le_adv ? 1 : 0,
1521	                  g_adv_active ? 1 : 0);
1522	        }
1523	#endif
1524	      ble_supervisor_request_cycle(BLE_SUPERVISOR_FAULT_ADAPTER, now_ms);
1525	    }
1526	
1527	  expected = !companion_phone_connected() && !g_hold_le_adv && !g_policy_adv_off;
1528	  active   = g_adv_active;
1529	  ble_supervisor_watch_advertising(expected, active, now_ms);
1530	
1531	  if (!ble_supervisor_cycle_requested())
1532	    {
1533	      return;
1534	    }
1535	
1536	  skip_while_connected =
1537	    companion_phone_connected() &&
1538	    ble_supervisor_pending_reason() != BLE_SUPERVISOR_FAULT_ADAPTER;
1539	  if (skip_while_connected)
1540	    {
1541	      return;
1542	    }
1543	
1544	  if (ble_supervisor_take_adapter_cycle(&reason))
1545	    {
1546	      LOGI("adapter cycle requested reason=%s",
1547	           ble_supervisor_fault_name(reason));
1548	      (void)companion_adapter_cycle(now_ms);
1549	    }
1550	}
