1679	/**
1680	 * @brief 注册 GATTS。skip-HCI 重启后 adapter 可能已 ON 但 profile 未 startup
1681	 *（`BT_STATUS_NOT_READY` / 2）。先短等，再 disable/enable 一次把 GATTS 拉起来。
1682	 */
1683	static bt_status_t companion_register_gatts(void)
1684	{
1685	  bt_status_t ret = BT_STATUS_FAIL;
1686	  unsigned i;
1687	
1688	  for (i = 0; i < GATTS_READY_RETRY; i++)
1689	    {
1690	      companion_bridge_heartbeat();
1691	      ret = bt_gatts_register_service(g_ins, &g_gatts_handle,
1692	                                      (gatts_callbacks_t *)&g_gatts_cbs);
1693	      if (ret == BT_STATUS_SUCCESS && g_gatts_handle != NULL)
1694	        {
1695	          return ret;
1696	        }
1697	
1698	      if (ret != BT_STATUS_NOT_READY)
1699	        {
1700	          return ret;
1701	        }
1702	
1703	      usleep(GATTS_READY_SLICE_MS * 1000u);
1704	    }
1705	
1706	  LOGI("GATTS not ready (%d), recycle adapter", (int)ret);
1707	  ret = bt_adapter_disable(g_ins);
1708	  if (ret != BT_STATUS_SUCCESS && ret != BT_STATUS_DONE)
1709	    {
1710	      LOGE("GATTS recycle disable failed: %d", (int)ret);
1711	      return ret;
1712	    }
1713	
1714	  {
1715	    uint32_t left = GATTS_RECYCLE_OFF_MS;
1716	
1717	    while (left > 0 && g_running)
1718	      {
1719	        uint32_t slice = left > GATTS_READY_SLICE_MS ?
1720	                         GATTS_READY_SLICE_MS : left;
1721	
1722	        companion_bridge_heartbeat();
1723	        usleep(slice * 1000u);
1724	        left -= slice;
1725	      }
1726	  }
1727	
1728	  ret = bt_adapter_enable(g_ins);
1729	  if (ret != BT_STATUS_SUCCESS && ret != BT_STATUS_DONE)
1730	    {
1731	      LOGE("GATTS recycle enable failed: %d", (int)ret);
1732	      return ret;
1733	    }
1734	
1735	  if (wait_adapter_ready(ADAPTER_CYCLE_WAIT_SECS) != 0)
1736	    {
1737	      return BT_STATUS_NOT_READY;
1738	    }
1739	
1740	  companion_bridge_heartbeat();
1741	  return bt_gatts_register_service(g_ins, &g_gatts_handle,
1742	                                   (gatts_callbacks_t *)&g_gatts_cbs);
1743	}
