1745	/**
1746	 * @brief 打开 BT，注册 GATTS 0xFF10，开始广播，创建传感器槽位。
1747	 */
1748	static int companion_start(void)
1749	{
1750	  bt_status_t      ret;
1751	  bt_address_t     le_addr;
1752	  ble_addr_type_t  le_addr_type;
1753	  char             addr_str[BT_ADDR_STR_LENGTH];
1754	  char             classic_str[BT_ADDR_STR_LENGTH];
1755	
1756	  companion_bridge_teardown_skip_hci_set(false);
1757	  companion_bridge_heartbeat();
1758	  if (wait_hci_device(HCI_WAIT_SECS) != 0)
1759	    {
1760	      return -1;
1761	    }
1762	
1763	  companion_bridge_heartbeat();
1764	  ret = bt_adapter_enable(g_ins);
1765	  companion_bridge_heartbeat();
1766	  if (ret != BT_STATUS_SUCCESS && ret != BT_STATUS_DONE)
1767	    {
1768	      LOGE("bt_adapter_enable failed: %d", (int)ret);
1769	      return -1;
1770	    }
1771	
1772	  if (wait_adapter_ready(ADAPTER_WAIT_SECS) != 0)
1773	    {
1774	      return -1;
1775	    }
1776	
1777	  /** 不要调 bt_device_set_bondable_le(false)：那会写全局 zblue bondable。
1778	   *  本服务 GATT 不加密，手机不需要 LE 配对。
1779	   */
1780	
1781	  if (bt_adapter_get_le_address(g_ins, &le_addr, &le_addr_type) !=
1782	      BT_STATUS_SUCCESS)
1783	    {
1784	      LOGE("bt_adapter_get_le_address failed");
1785	      return -1;
1786	    }
1787	
1788	  bt_adapter_get_address(g_ins, &g_classic_addr);
1789	  status_pack(&g_ctx.status, g_status_buf);
1790	  bt_addr_ba2str(&le_addr, addr_str);
1791	  bt_addr_ba2str(&g_classic_addr, classic_str);
1792	  build_adv_payload(&le_addr);
1793	  LOGI("LE address %s (status trailer %s unused)", addr_str, classic_str);
1794	
1795	  (void)bt_conn_cb_register(&g_le_conn_cb);
1796	
1797	  /** enable 之后再 set_name() 会发 251 字节 HCI 写，打爆 HCPU 堆。保持编译期本地名。 */
1798	
1799	  ret = companion_register_gatts();
1800	  if (ret != BT_STATUS_SUCCESS || g_gatts_handle == NULL)
1801	    {
1802	      LOGE("bt_gatts_register_service failed: %d", (int)ret);
1803	      return -1;
1804	    }
1805	
1806	  ret = bt_gatts_add_attr_table(g_gatts_handle, &g_companion_service_db);
1807	  if (ret != BT_STATUS_SUCCESS)
1808	    {
1809	      LOGE("bt_gatts_add_attr_table failed: %d", (int)ret);
1810	      return -1;
1811	    }
1812	
1813	  companion_fs_bind(g_gatts_handle, COMP_FS_DATA_ID);
1814	
1815	  g_policy_adv_off = !companion_bridge_policy_radio();
1816	  if (!g_policy_adv_off)
1817	    {
1818	      if (companion_start_advertising() != 0)
1819	        {
1820	          LOGE("LE adv start failed");
1821	          return -1;
1822	        }
1823	    }
1824	  else
1825	    {
1826	      LOGI("phone radio off (ctl persist.bt.radio)");
1827	    }
1828	
1829	  if (companion_bridge_policy_sensor())
1830	    {
1831	      companion_apply_sensor_policy(true);
1832	    }
1833	  else
1834	    {
1835	      LOGI("sensor radio off (ctl persist.bt.sensor)");
1836	    }
1837	
1838	  LOGI("ready — service 0x%04X, proto 0x%04X, GATT FS (UI off; use test sensor/notif/ctrl)",
1839	       COMPANION_SERVICE_UUID16, COMPANION_PROTO_VERSION);
1840	  companion_bridge_alive_set(true);
1841	  return 0;
1842	}
