1844	/**
1845	 * @brief 拆除 GATTS、ADV、传感器客户端、BT 实例。
1846	 */
1847	static void companion_stop(void)
1848	{
1849	  bool skip_hci;
1850	
1851	  companion_bridge_alive_set(false);
1852	  companion_bridge_phone_set(false);
1853	  skip_hci = companion_bridge_teardown_skip_hci() ||
1854	             sf32lb52_bt_hci_skip_sync();
1855	
1856	  if (skip_hci)
1857	    {
1858	      BLE_LOG("stop skipped HCI skip_sync=%d teardown=%d",
1859	              sf32lb52_bt_hci_skip_sync() ? 1 : 0,
1860	              companion_bridge_teardown_skip_hci() ? 1 : 0);
1861	      LOGI("stop skipped HCI (recovering)");
1862	      ble_sensor_stop();
1863	      companion_fs_abort();
1864	      companion_fs_on_disconnect();
1865	      companion_downlink_reset();
1866	      g_adv = NULL;
1867	      g_adv_active = false;
1868	      g_gatts_handle = NULL;
1869	      g_adapter_cookie = NULL;
1870	      g_ins = NULL;
1871	      return;
1872	    }
1873	
1874	  ble_sensor_stop();
1875	  companion_fs_abort();
1876	  companion_fs_on_disconnect();
1877	  companion_downlink_reset();
1878	  companion_stop_advertising();
1879	
1880	  if (g_gatts_handle != NULL)
1881	    {
1882	      bt_gatts_remove_attr_table(g_gatts_handle, COMP_SERVICE_ID);
1883	      bt_gatts_unregister_service(g_gatts_handle);
1884	      g_gatts_handle = NULL;
1885	    }
1886	
1887	  if (g_ins != NULL)
1888	    {
1889	      bt_adapter_disable(g_ins);
1890	
1891	      if (g_adapter_cookie != NULL)
1892	        {
1893	          bt_adapter_unregister_callback(g_ins, g_adapter_cookie);
1894	          g_adapter_cookie = NULL;
1895	        }
1896	
1897	      bluetooth_delete_instance(g_ins);
1898	      g_ins = NULL;
1899	    }
1900	}
