1927	/**
1928	 * @brief 在 companion 线程上消费一条 NSH `test sensor` 命令。
1929	 *
1930	 * 扫描/连接/GATT 绝不在 NSH 任务里跑。连接按表格 idx → 地址。
1931	 */
1932	static void companion_apply_sensor_test(bt_instance_t *ins)
1933	{
1934	  uint8_t cmd;
1935	
1936	  if (!companion_bridge_test_sensor_take(&cmd))
1937	    {
1938	      return;
1939	    }
1940	
1941	  switch (cmd)
1942	    {
1943	      case COMPANION_TEST_SENSOR_SCAN:
1944	        if (ble_sensor_connect_busy())
1945	          {
1946	            LOGI("sensor scan skipped, connecting");
1947	            break;
1948	          }
1949	
1950	        ble_sensor_set_connect(false);
1951	        ble_sensor_set_adv_debug(false);
1952	        if (ble_sensor_start(ins) != 0)
1953	          {
1954	            LOGE("sensor scan start failed");
1955	            break;
1956	          }
1957	
1958	        ble_sensor_scan_arm(companion_bridge_test_sensor_scan_ms());
1959	        break;
1960	
1961	      case COMPANION_TEST_SENSOR_CONNECT:
1962	        if (ble_sensor_start(ins) != 0)
1963	          {
1964	            LOGE("sensor connect start failed");
1965	            break;
1966	          }
1967	
1968	        if (ble_sensor_connect_index(companion_bridge_test_sensor_connect_idx()) != 0)
1969	          {
1970	            break;
1971	          }
1972	
1973	        break;
1974	
1975	      case COMPANION_TEST_SENSOR_CONNECT_ADDR:
1976	        {
1977	          struct companion_sensor_bind bind;
1978	
1979	          companion_bridge_sensor_cmd_get_bind(&bind);
1980	          if (ble_sensor_start(ins) != 0)
1981	            {
1982	              LOGE("sensor addr connect start failed");
1983	              break;
1984	            }
1985	
1986	          if (ble_sensor_connect_addr(bind.addr, bind.addr_type, bind.kind,
1987	                                      bind.name, bind.drop_addr,
1988	                                      bind.drop_kind) != 0)
1989	            {
1990	              LOGE("sensor addr connect failed");
1991	            }
1992	        }
1993	        break;
1994	
1995	      case COMPANION_TEST_SENSOR_CLEAR_WANT:
1996	        {
1997	          struct companion_sensor_bind bind;
1998	
1999	          companion_bridge_sensor_cmd_get_bind(&bind);
2000	          (void)ble_sensor_clear_want(bind.addr, bind.kind);
2001	        }
2002	        break;
2003	
2004	      case COMPANION_TEST_SENSOR_SCAN_STOP:
2005	        ble_sensor_scan_stop();
2006	        break;
2007	
2008	      case COMPANION_TEST_SENSOR_DISCONNECT:
2009	        ble_sensor_disconnect_all();
2010	        break;
2011	
2012	      case COMPANION_TEST_SENSOR_DISCONNECT_KIND:
2013	        (void)ble_sensor_disconnect_kind(companion_bridge_test_sensor_kind());
2014	        break;
2015	
2016	      case COMPANION_TEST_SENSOR_STOP:
2017	        ble_sensor_stop();
2018	        companion_hold_le_adv(false);
2019	        LOGI("sensor scan stopped");
2020	        break;
2021	
2022	      case COMPANION_TEST_SENSOR_DUMP:
2023	        ble_sensor_dump();
2024	        break;
2025	
2026	      default:
2027	        break;
2028	    }
2029	}
