2031	/**
2032	 * @brief 主循环一拍：传感器泵、FS 泵、状态标志、心跳 notify。
2033	 *
2034	 * 文件 I/O 在 companion_fs_pump()；本任务优先级低于 CONFIG_BT_LONG_WQ_PRIO，
2035	 * 避免 SD 等待饿死协议栈。禁止 statfs()。
2036	 */
2037	static void companion_tick(uint32_t start_ms, uint32_t *last_notify_ms)
2038	{
2039	  uint8_t      buf[COMPANION_STATUS_WIRE_LEN];
2040	  bt_address_t peer;
2041	  uint32_t     now = mono_ms();
2042	  bool         send = false;
2043	  bool         usb_busy = xfer_usb_busy();
2044	  bool         fs_busy  = companion_fs_busy();
2045	  bool         drop_phone_gnss = false;
2046	  bool         ride_session = false;
2047	  bool         ride_moving = false;
2048	  uint8_t      ready;
2049	
2050	  ready = ble_sensor_ready_mask();
2051	  companion_bridge_ride_get(&ride_session, &ride_moving);
2052	
2053	  pthread_mutex_lock(&g_ctx.lock);
2054	
2055	  g_ctx.status.uptime_sec = myvendor_mono_elapsed_ms(now, start_ms) / 1000;
2056	
2057	  {
2058	    int bat = myvendor_sys_battery_percent_cached();
2059	    uint8_t bat_wire = (bat < 0 || bat > 100) ?
2060	                       COMPANION_BATTERY_UNKNOWN : (uint8_t)bat;
2061	
2062	    if (g_ctx.status.battery_pct != bat_wire)
2063	      {
2064	        g_ctx.status.battery_pct = bat_wire;
2065	        g_ctx.status_dirty = true;
2066	      }
2067	  }
2068	
2069	  status_set_flags(ride_session ? COMPANION_STATUS_RECORDING : 0,
2070	                   ride_session ? 0 : COMPANION_STATUS_RECORDING);
2071	  status_set_flags(ride_moving ? COMPANION_STATUS_MOVING : 0,
2072	                   ride_moving ? 0 : COMPANION_STATUS_MOVING);
2073	
2074	  if (fs_busy)
2075	    {
2076	      status_set_flags(COMPANION_STATUS_FS_BUSY, 0);
2077	    }
2078	  else
2079	    {
2080	      status_set_flags(0, COMPANION_STATUS_FS_BUSY);
2081	    }
2082	
2083	  if (usb_busy)
2084	    {
2085	      status_set_flags(COMPANION_STATUS_USB_MTP_BUSY, 0);
2086	    }
2087	  else
2088	    {
2089	      status_set_flags(0, COMPANION_STATUS_USB_MTP_BUSY);
2090	    }
2091	
2092	  /** App 不再推送后清掉 GPS_PHONE（过期的手机定位）。 */
2093	
2094	  if ((g_ctx.status.flags & COMPANION_STATUS_GPS_PHONE) != 0 &&
2095	      myvendor_mono_elapsed_ms(now, g_ctx.last_gnss_ms) >=
2096	      COMPANION_GNSS_STALE_SEC * 1000)
2097	    {
2098	      status_set_flags(0, COMPANION_STATUS_GPS_PHONE);
2099	      g_ctx.fix_valid = false;
2100	      drop_phone_gnss = true;
2101	    }
2102	
2103	  status_set_flags((ready & (1u << 0)) ? COMPANION_STATUS_SENSOR_HR : 0,
2104	                   (ready & (1u << 0)) ? 0 : COMPANION_STATUS_SENSOR_HR);
2105	  status_set_flags((ready & (1u << 1)) ? COMPANION_STATUS_SENSOR_CSC : 0,
2106	                   (ready & (1u << 1)) ? 0 : COMPANION_STATUS_SENSOR_CSC);
2107	  status_set_flags((ready & (1u << 2)) ? COMPANION_STATUS_SENSOR_CPS : 0,
2108	                   (ready & (1u << 2)) ? 0 : COMPANION_STATUS_SENSOR_CPS);
2109	
2110	  status_pack(&g_ctx.status, buf);
2111	
2112	  if (g_ctx.connected && g_ctx.ccc_enabled)
2113	    {
2114	      send = g_ctx.notify_req || g_ctx.status_dirty ||
2115	             (myvendor_mono_elapsed_ms(now, *last_notify_ms) >=
2116	              COMPANION_STATUS_HEARTBEAT_SEC * 1000);
2117	    }
2118	
2119	  peer = g_ctx.peer;
2120	  g_ctx.notify_req   = false;
2121	  g_ctx.status_dirty = false;
2122	  pthread_mutex_unlock(&g_ctx.lock);
2123	
2124	  if (drop_phone_gnss)
2125	    {
2126	      companion_bridge_gnss_clear();
2127	    }
2128	
2129	  /** 可读值与 notify 保持一致，避免 0xFF12 普通读和通知对不上。 */
2130	
2131	  if (g_gatts_handle != NULL)
2132	    {
2133	      bt_gatts_set_attr_value(g_gatts_handle, COMP_STATUS_ID, buf,
2134	                              sizeof(buf));
2135	    }
2136	
2137	  /** FS Data notify 突发已经很压控制器。中间插状态心跳会让 Android 把 0xFF16 收成最后一片。 */
2138	
2139	  if (send && !fs_busy)
2140	    {
2141	      bt_status_t ret;
2142	
2143	      companion_bridge_phase_set("notify");
2144	      ret = bt_gatts_notify(g_gatts_handle, &peer, COMP_STATUS_ID,
2145	                            buf, sizeof(buf));
2146	      if (ret == BT_STATUS_SUCCESS)
2147	        {
2148	          *last_notify_ms = now;
2149	          g_notify_err = BT_STATUS_SUCCESS;
2150	        }
2151	      else if (ret != g_notify_err)
2152	        {
2153	          /** 状态特征从不 notify 在 App 看来像死机。仅在错误变化时打印，避免断链刷屏。 */
2154	
2155	          LOGE("status notify failed: %d", (int)ret);
2156	          g_notify_err = ret;
2157	        }
2158	    }
2159	}
