2174	/**
2175	 * @brief ble_companion 入口：一条线程上跑手机 GATTS + 传感器 GATTC。
2176	 */
2177	int main(int argc, FAR char *argv[])
2178	{
2179	  uint32_t start_ms;
2180	  uint32_t last_notify_ms = 0;
2181	  uint32_t last_tick_ms = 0;
2182	
2183	  (void)argc;
2184	  (void)argv;
2185	
2186	  g_running = true;
2187	  companion_bridge_phase_set("boot");
2188	  companion_bridge_heartbeat();
2189	
2190	  signal(SIGINT, signal_handler);
2191	  signal(SIGTERM, signal_handler);
2192	
2193	  memset(&g_ctx, 0, sizeof(g_ctx));
2194	  pthread_mutex_init(&g_ctx.lock, NULL);
2195	  g_ctx.status.battery_pct     = COMPANION_BATTERY_UNKNOWN;
2196	  g_ctx.status.storage_free_kb = COMPANION_STORAGE_FREE_UNKNOWN;
2197	
2198	  put_le16(g_proto_ver_buf, COMPANION_PROTO_VERSION);
2199	  status_pack(&g_ctx.status, g_status_buf);
2200	  devinfo_pack(g_devinfo_buf);
2201	  LOGI("devinfo slot=%u sw=%s hw=%s fw=%s boot=%s",
2202	       (unsigned)g_devinfo_buf[0],
2203	       myvendor_sw_version(), myvendor_hw_version(),
2204	       myvendor_boot_fw_name()[0] != '\0' ? myvendor_boot_fw_name() : "-",
2205	       myvendor_boot_version()[0] != '\0' ? myvendor_boot_version() : "-");
2206	
2207	  g_ins = bluetooth_create_instance();
2208	  if (g_ins == NULL)
2209	    {
2210	      LOGE("bluetooth_create_instance failed");
2211	      companion_bridge_alive_set(false);
2212	      pthread_mutex_destroy(&g_ctx.lock);
2213	      return EXIT_FAILURE;
2214	    }
2215	
2216	  g_adapter_cookie = bt_adapter_register_callback(g_ins, &g_adapter_cbs);
2217	  if (g_adapter_cookie == NULL)
2218	    {
2219	      LOGE("bt_adapter_register_callback failed");
2220	      companion_stop_after_failed_start();
2221	      pthread_mutex_destroy(&g_ctx.lock);
2222	      return EXIT_FAILURE;
2223	    }
2224	
2225	  if (companion_start() != 0)
2226	    {
2227	      companion_stop_after_failed_start();
2228	      pthread_mutex_destroy(&g_ctx.lock);
2229	      return EXIT_FAILURE;
2230	    }
2231	
2232	  ble_supervisor_init(mono_ms());
2233	
2234	  start_ms = mono_ms();
2235	
2236	  while (g_running)
2237	    {
2238	      bool     fs_active;
2239	      bool     adv_wait;
2240	      bool     connected;
2241	      uint32_t now;
2242	#ifdef CONFIG_MYVENDOR_BLE_LOG
2243	      static uint32_t last_ble_log_ms;
2244	      bool adv_restart;
2245	#endif
2246	
2247	      companion_bridge_phase_set("loop");
2248	      companion_bridge_heartbeat();
2249	      companion_bridge_phase_set("devctl");
2250	      companion_apply_devctl();
2251	      now = mono_ms();
2252	      /* HCI 已卡住时后面 start_adv / sensor 会同步等 Command Complete，
2253	       * 必须先 cycle，否则监督逻辑永远跑不到。 */
2254	      companion_bridge_phase_set("supervisor");
2255	      companion_supervisor_pump(now);
2256	      companion_apply_sensor_test(g_ins);
2257	
2258	      pthread_mutex_lock(&g_ctx.lock);
2259	      connected = g_ctx.connected;
2260	#ifdef CONFIG_MYVENDOR_BLE_LOG
2261	      adv_restart = g_ctx.adv_restart;
2262	#endif
2263	      pthread_mutex_unlock(&g_ctx.lock);
2264	      companion_bridge_phase_set("sensor");
2265	      ble_sensor_set_phone_state(connected, g_hold_le_adv);
2266	      ble_sensor_pump(mono_ms());
2267	      if (ble_sensor_take_hold_request())
2268	        {
2269	          companion_hold_le_adv(true);
2270	        }
2271	      if (ble_sensor_take_hold_release())
2272	        {
2273	          companion_hold_le_adv(false);
2274	        }
2275	
2276	      /** 先消费 scanner 的 hold/release，再按新相位启 ADV；板级 SAL
2277	       * radio guard 再等待上一角色的 HCI stop 真正完成。
2278	       */
2279	
2280	      companion_bridge_phase_set("adv");
2281	      companion_ensure_advertising();
2282	      now = mono_ms();
2283	      companion_bridge_phase_set("supervisor");
2284	      companion_supervisor_pump(now);
2285	#ifdef CONFIG_MYVENDOR_BLE_LOG
2286	      if (last_ble_log_ms == 0 ||
2287	          myvendor_mono_elapsed_ms(now, last_ble_log_ms) >= 5000u)
2288	        {
2289	          last_ble_log_ms = now;
2290	          BLE_LOG("loop skip=%d rxstall=%d alive=%d phone=%d "
2291	                  "adv=%d hold=%d radio_off=%d sensor=%d restart=%d "
2292	                  "policy_r=%d policy_s=%d",
2293	                  sf32lb52_bt_hci_skip_sync() ? 1 : 0,
2294	                  sf32lb52_bt_hci_rx_stalled(HCI_RX_STALL_MS) ? 1 : 0,
2295	                  companion_bridge_alive_get() ? 1 : 0,
2296	                  connected ? 1 : 0,
2297	                  g_adv_active ? 1 : 0,
2298	                  g_hold_le_adv ? 1 : 0,
2299	                  g_policy_adv_off ? 1 : 0,
2300	                  ble_sensor_is_started() ? 1 : 0,
2301	                  adv_restart ? 1 : 0,
2302	                  companion_bridge_policy_radio() ? 1 : 0,
2303	                  companion_bridge_policy_sensor() ? 1 : 0);
2304	        }
2305	#endif
2306	      companion_bridge_phase_set("fs");
2307	      fs_active = companion_fs_pump();
2308	      if (!fs_active ||
2309	          myvendor_mono_elapsed_ms(now, last_tick_ms) >= TICK_MS)
2310	        {
2311	          companion_bridge_phase_set("tick");
2312	          companion_tick(start_ms, &last_notify_ms);
2313	          last_tick_ms = now;
2314	        }
2315	
2316	      pthread_mutex_lock(&g_ctx.lock);
2317	      adv_wait = g_ctx.adv_restart && !g_ctx.connected && !g_hold_le_adv;
2318	      connected = g_ctx.connected;
2319	      pthread_mutex_unlock(&g_ctx.lock);
2320	
2321	      /** GATT 写只置 pending；没有 kick 的话下一拍泵会睡满 500 ms，READ 大约 1 个 ATT 载荷/秒。 */
2322	
2323	      companion_bridge_phase_set("wait");
2324	      if (fs_active)
2325	        {
2326	          companion_fs_wait(1);
2327	        }
2328	      else if (adv_wait)
2329	        {
2330	          companion_fs_wait(2);
2331	        }
2332	      else if (connected || ble_sensor_is_started())
2333	        {
2334	          companion_fs_wait(20);
2335	        }
2336	      else
2337	        {
2338	          companion_fs_wait(TICK_MS);
2339	        }
2340	    }
2341	
2342	  LOGI("shutting down...");
2343	  companion_stop();
2344	  pthread_mutex_destroy(&g_ctx.lock);
2345	  LOGI("done");
2346	  return EXIT_SUCCESS;
2347	}
