1	/**
2	 * @file ble_supervisor.c
3	 * @brief BLE 角色故障计数、升级与 adapter cycle 限频。
4	 *
5	 * SPDX-License-Identifier: Apache-2.0
6	 */
7	
8	#include <stdbool.h>
9	#include <stdint.h>
10	#include <stdio.h>
11	#include <string.h>
12	#include <syslog.h>
13	
14	#include "ble_supervisor.h"
15	#include "myvendor_ble_log.h"
16	
17	#define LOGI(fmt, ...) syslog(LOG_INFO, "ble_supervisor: " fmt "\n", ##__VA_ARGS__)
18	#define LOGE(fmt, ...) syslog(LOG_ERR, "ble_supervisor: " fmt "\n", ##__VA_ARGS__)
19	
20	#define SUPERVISOR_FAULT_WINDOW_MS       60000u
21	#define SUPERVISOR_FAULT_THRESHOLD       3u
22	#define SUPERVISOR_FAULT_SPACING_MS      2000u
23	#define SUPERVISOR_ADV_STALL_MS          12000u
24	#define SUPERVISOR_ADV_GRACE_MS          45000u
25	#define SUPERVISOR_SUCCESS_COOLDOWN_MS   30000u
26	#define SUPERVISOR_FAILURE_COOLDOWN_MS   60000u
27	#define SUPERVISOR_RECOVERING_TIMEOUT_MS 15000u
28	
29	struct fault_window
30	{
31	  uint32_t first_ms;
32	  uint32_t last_ms;
33	  uint8_t  count;
34	};
35	
36	static struct fault_window g_windows[BLE_SUPERVISOR_FAULT_COUNT];
37	static uint16_t g_totals[BLE_SUPERVISOR_FAULT_COUNT];
38	static enum ble_supervisor_fault g_cycle_reason;
39	static uint32_t g_adv_missing_ms;
40	static uint32_t g_adv_grace_until_ms;
41	static uint32_t g_cooldown_until_ms;
42	static uint16_t g_adapter_cycles;
43	static uint16_t g_cycle_failures;
44	static uint32_t g_recovering_since_ms;
45	static bool g_cycle_pending;
46	static bool g_recovering;
47	static bool g_retry_cycle;
48	
49	static bool deadline_reached(uint32_t now_ms, uint32_t deadline_ms)
50	{
51	  return deadline_ms == 0 ||
52	         (int32_t)(now_ms - deadline_ms) >= 0;
53	}
54	
55	static uint16_t sat_inc16(uint16_t value)
56	{
57	  return value == UINT16_MAX ? value : (uint16_t)(value + 1u);
58	}
59	
60	const char *ble_supervisor_fault_name(enum ble_supervisor_fault fault)
61	{
62	  switch (fault)
63	    {
64	      case BLE_SUPERVISOR_FAULT_ADV:
65	        return "adv";
66	      case BLE_SUPERVISOR_FAULT_SCAN:
67	        return "scan";
68	      case BLE_SUPERVISOR_FAULT_GATTC:
69	        return "gattc";
70	      case BLE_SUPERVISOR_FAULT_ADAPTER:
71	        return "adapter";
72	      default:
73	        return "unknown";
74	    }
75	}
76	
77	static void supervisor_adv_grace(uint32_t now_ms)
78	{
79	  g_adv_grace_until_ms = now_ms + SUPERVISOR_ADV_GRACE_MS;
80	  g_adv_missing_ms = 0;
81	}
82	
83	void ble_supervisor_init(uint32_t now_ms)
84	{
85	  memset(g_windows, 0, sizeof(g_windows));
86	  memset(g_totals, 0, sizeof(g_totals));
87	  g_cycle_reason = BLE_SUPERVISOR_FAULT_ADAPTER;
88	  g_adv_missing_ms = 0;
89	  g_cooldown_until_ms = 0;
90	  g_adapter_cycles = 0;
91	  g_cycle_failures = 0;
92	  g_cycle_pending = false;
93	  g_recovering = false;
94	  g_recovering_since_ms = 0;
95	  g_retry_cycle = false;
96	  supervisor_adv_grace(now_ms);
97	}
98	
99	void ble_supervisor_report(enum ble_supervisor_fault fault, uint32_t now_ms)
100	{
101	  struct fault_window *window;
102	
103	  if (fault >= BLE_SUPERVISOR_FAULT_COUNT)
104	    {
105	      return;
106	    }
107	
108	  /* Boot / dual-role (phone ADV + HR central) start failures are normal. */
109	  if (fault == BLE_SUPERVISOR_FAULT_ADV &&
110	      !deadline_reached(now_ms, g_adv_grace_until_ms))
111	    {
112	      return;
113	    }
114	
115	  window = &g_windows[fault];
116	  if (window->count == 0 ||
117	      (uint32_t)(now_ms - window->first_ms) >
118	      SUPERVISOR_FAULT_WINDOW_MS)
119	    {
120	      window->first_ms = now_ms;
121	      window->last_ms = 0;
122	      window->count = 0;
123	    }
124	
125	  if (window->last_ms != 0 &&
126	      (uint32_t)(now_ms - window->last_ms) < SUPERVISOR_FAULT_SPACING_MS)
127	    {
128	      return;
129	    }
130	
131	  window->last_ms = now_ms;
132	  if (window->count < UINT8_MAX)
133	    {
134	      window->count++;
135	    }
136	
137	  g_totals[fault] = sat_inc16(g_totals[fault]);
138	
139	  if (window->count >= SUPERVISOR_FAULT_THRESHOLD &&
140	      !g_recovering && !g_cycle_pending &&
141	      deadline_reached(now_ms, g_cooldown_until_ms))
142	    {
143	      g_cycle_reason = fault;
144	      g_cycle_pending = true;
145	      LOGE("request adapter cycle reason=%s window=%u total=%u",
146	           ble_supervisor_fault_name(fault), (unsigned)window->count,
147	           (unsigned)g_totals[fault]);
148	    }
149	}
150	
151	void ble_supervisor_watch_advertising(bool expected, bool active,
152	                                      uint32_t now_ms)
153	{
154	  if (!expected || active || g_recovering ||
155	      !deadline_reached(now_ms, g_adv_grace_until_ms))
156	    {
157	      g_adv_missing_ms = 0;
158	      return;
159	    }
160	
161	  if (g_adv_missing_ms == 0)
162	    {
163	      g_adv_missing_ms = now_ms;
164	      return;
165	    }
166	
167	  if ((uint32_t)(now_ms - g_adv_missing_ms) >= SUPERVISOR_ADV_STALL_MS)
168	    {
169	      BLE_LOG("adv stall expected=%d active=%d missing=%u",
170	              expected ? 1 : 0, active ? 1 : 0,
171	              (unsigned)(now_ms - g_adv_missing_ms));
172	      g_adv_missing_ms = now_ms;
173	      ble_supervisor_report(BLE_SUPERVISOR_FAULT_ADV, now_ms);
174	    }
175	}
176	
177	void ble_supervisor_tick(uint32_t now_ms)
178	{
179	  if (g_recovering && g_recovering_since_ms != 0 &&
180	      (uint32_t)(now_ms - g_recovering_since_ms) >=
181	      SUPERVISOR_RECOVERING_TIMEOUT_MS)
182	    {
183	      LOGE("adapter cycle hung %u ms, releasing latch",
184	           (unsigned)(now_ms - g_recovering_since_ms));
185	      g_recovering = false;
186	      g_recovering_since_ms = 0;
187	      g_retry_cycle = true;
188	      g_cooldown_until_ms = 0;
189	    }
190	
191	  if (g_retry_cycle && !g_recovering && !g_cycle_pending &&
192	      deadline_reached(now_ms, g_cooldown_until_ms))
193	    {
194	      g_cycle_reason = BLE_SUPERVISOR_FAULT_ADAPTER;
195	      g_cycle_pending = true;
196	      g_retry_cycle = false;
197	      LOGE("retry adapter cycle after recovery failure");
198	    }
199	}
200	
201	void ble_supervisor_request_cycle(enum ble_supervisor_fault fault,
202	                                  uint32_t now_ms)
203	{
204	  if (fault >= BLE_SUPERVISOR_FAULT_COUNT || g_recovering)
205	    {
206	      return;
207	    }
208	
209	  /* HCI RX 卡住时 cooldown 只会让 -ENOMEM 再拖几十秒。 */
210	  if (fault != BLE_SUPERVISOR_FAULT_ADAPTER &&
211	      !deadline_reached(now_ms, g_cooldown_until_ms))
212	    {
213	      return;
214	    }
215	
216	  if (g_cycle_pending)
217	    {
218	      if (fault == BLE_SUPERVISOR_FAULT_ADAPTER)
219	        {
220	          g_cycle_reason = fault;
221	        }
222	
223	      return;
224	    }
225	
226	  g_cycle_reason = fault;
227	  g_cycle_pending = true;
228	  g_totals[fault] = sat_inc16(g_totals[fault]);
229	  LOGE("request adapter cycle reason=%s (immediate) total=%u",
230	       ble_supervisor_fault_name(fault), (unsigned)g_totals[fault]);
231	}
232	
233	bool ble_supervisor_cycle_requested(void)
234	{
235	  return g_cycle_pending && !g_recovering;
236	}
237	
238	enum ble_supervisor_fault ble_supervisor_pending_reason(void)
239	{
240	  return g_cycle_reason;
241	}
242	
243	bool ble_supervisor_take_adapter_cycle(enum ble_supervisor_fault *reason)
244	{
245	  if (!g_cycle_pending || g_recovering)
246	    {
247	      return false;
248	    }
249	
250	  if (reason != NULL)
251	    {
252	      *reason = g_cycle_reason;
253	    }
254	
255	  g_cycle_pending = false;
256	  return true;
257	}
258	
259	void ble_supervisor_cycle_begin(uint32_t now_ms)
260	{
261	  g_recovering = true;
262	  g_recovering_since_ms = (now_ms == 0) ? 1u : now_ms;
263	  g_cycle_pending = false;
264	  g_adapter_cycles = sat_inc16(g_adapter_cycles);
265	  LOGI("adapter cycle begin count=%u reason=%s",
266	       (unsigned)g_adapter_cycles,
267	       ble_supervisor_fault_name(g_cycle_reason));
268	}
269	
270	void ble_supervisor_cycle_complete(bool success, uint32_t now_ms)
271	{
272	  g_recovering = false;
273	  g_recovering_since_ms = 0;
274	  supervisor_adv_grace(now_ms);
275	
276	  if (success)
277	    {
278	      memset(g_windows, 0, sizeof(g_windows));
279	      g_cycle_failures = 0;
280	      g_retry_cycle = false;
281	      g_cooldown_until_ms = now_ms + SUPERVISOR_SUCCESS_COOLDOWN_MS;
282	      LOGI("adapter cycle recovered, cooldown=%u ms",
283	           (unsigned)SUPERVISOR_SUCCESS_COOLDOWN_MS);
284	      return;
285	    }
286	
287	  g_cycle_failures = sat_inc16(g_cycle_failures);
288	  g_retry_cycle = true;
289	  g_cooldown_until_ms = now_ms + SUPERVISOR_FAILURE_COOLDOWN_MS;
290	  LOGE("adapter cycle failed count=%u, retry in %u ms",
291	       (unsigned)g_cycle_failures,
292	       (unsigned)SUPERVISOR_FAILURE_COOLDOWN_MS);
293	  if (g_cycle_failures >= 2)
294	    {
295	      LOGE("fatal BLE recovery: repeated adapter cycle failure");
296	    }
297	}
298	
299	void ble_supervisor_get_stats(struct ble_supervisor_stats *stats)
300	{
301	  if (stats == NULL)
302	    {
303	      return;
304	    }
305	
306	  memset(stats, 0, sizeof(*stats));
307	  stats->adv_failures = g_totals[BLE_SUPERVISOR_FAULT_ADV];
308	  stats->scan_failures = g_totals[BLE_SUPERVISOR_FAULT_SCAN];
309	  stats->gattc_recreates = g_totals[BLE_SUPERVISOR_FAULT_GATTC];
310	  stats->adapter_failures = g_totals[BLE_SUPERVISOR_FAULT_ADAPTER];
311	  stats->adapter_cycles = g_adapter_cycles;
312	  stats->adapter_cycle_failures = g_cycle_failures;
313	  stats->recovering = g_recovering;
314	  stats->cycle_pending = g_cycle_pending;
315	}
