1	/**
2	 * @file companion_downlink.c
3	 * @brief 重组 0xFF17 / 0xFF19 分片。
4	 *
5	 * 重组后的 payload 为 TLV。TAG_ICON 只带文件名；缺文件时发 FS_NEED。
6	 * NSH `test notif on` / `test ctrl on` 打印到达的数据。
7	 *
8	 * SPDX-License-Identifier: Apache-2.0
9	 */
10	
11	#include <nuttx/config.h>
12	
13	#include <stdbool.h>
14	#include <stddef.h>
15	#include <stdio.h>
16	#include <string.h>
17	
18	#include "companion_bridge.h"
19	#include "companion_downlink.h"
20	#include "companion_fs.h"
21	#include "companion_proto.h"
22	#include "transfer_backend.h"
23	#include "board_malloc.h"
24	
25	#define LOGI(fmt, ...) printf("ble_companion: " fmt "\n", ##__VA_ARGS__)
26	#define LOGE(fmt, ...) printf("ble_companion: ERROR " fmt "\n", ##__VA_ARGS__)
27	
28	struct frag_acc
29	{
30	  uint8_t  msg_id;
31	  uint8_t  type;
32	  uint8_t  flags_or;
33	  uint16_t total;
34	  uint16_t filled;
35	  bool     in_use;
36	  uint8_t *data;
37	};
38	
39	static struct frag_acc g_notif;
40	static struct frag_acc g_nav;
41	
42	/**
43	 * @brief 分片载荷放 BoardPSRAM。
44	 */
45	static bool frag_acc_ensure(struct frag_acc *acc, uint16_t max_total)
46	{
47	  if (acc->data != NULL)
48	    {
49	      return true;
50	    }
51	
52	  acc->data = board_malloc_psram(max_total);
53	  if (acc->data == NULL)
54	    {
55	      return false;
56	    }
57	
58	  memset(acc->data, 0, max_total);
59	  return true;
60	}
61	
62	/**
63	 * @brief 读出小端 uint16。
64	 */
65	static uint16_t get_le16(const uint8_t *p)
66	{
67	  return (uint16_t)((uint16_t)p[0] | ((uint16_t)p[1] << 8));
68	}
69	
70	/**
71	 * @brief 读出小端 uint32。
72	 */
73	static uint32_t get_le32(const uint8_t *p)
74	{
75	  return (uint32_t)p[0] | ((uint32_t)p[1] << 8) |
76	         ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
77	}
78	
79	/**
80	 * @brief 把 @p len 字节拷进以 NUL 结尾的缓冲区。
81	 */
82	static void copy_trunc(char *dst, size_t dstsz, const uint8_t *src, uint16_t len)
83	{
84	  size_t n;
85	
86	  if (dstsz == 0)
87	    {
88	      return;
89	    }
90	
91	  n = (size_t)len;
92	  if (n >= dstsz)
93	    {
94	      n = dstsz - 1;
95	    }
96	
97	  memcpy(dst, src, n);
98	  dst[n] = '\0';
99	}
100	
101	/**
102	 * @brief 去掉用作字段分隔的尾部 '|'。
103	 */
104	static void strip_bar(char *s)
105	{
106	  char *p;
107	
108	  for (p = s; *p != '\0'; p++)
109	    {
110	      if (*p == '|')
111	        {
112	          *p = '/';
113	        }
114	    }
115	}
116	
117	/**
118	 * @brief 累加一次分片写；LAST 时置 complete。
119	 */
120	static bool frag_feed(struct frag_acc *acc, const uint8_t *value, uint16_t length,
121	                      uint16_t max_total, bool *complete)
122	{
123	  uint8_t  flags;
124	  uint8_t  msg_id;
125	  uint16_t total;
126	  uint16_t off;
127	  uint16_t pay_len;
128	
129	  *complete = false;
130	
131	  if (!frag_acc_ensure(acc, max_total))
132	    {
133	      return false;
134	    }
135	
136	  if (length < COMPANION_NOTIF_HDR_LEN)
137	    {
138	      return false;
139	    }
140	
141	  if (value[0] != COMPANION_NOTIF_HDR_VER)
142	    {
143	      return false;
144	    }
145	
146	  flags   = value[2];
147	  msg_id  = value[3];
148	  total   = get_le16(value + 4);
149	  off     = get_le16(value + 6);
150	  pay_len = (uint16_t)(length - COMPANION_NOTIF_HDR_LEN);
151	
152	  if (total == 0 || total > max_total || off > total)
153	    {
154	      acc->in_use = false;
155	      return false;
156	    }
157	
158	  if ((flags & COMPANION_NOTIF_FLAG_FIRST) != 0)
159	    {
160	      acc->in_use   = true;
161	      acc->msg_id   = msg_id;
162	      acc->type     = value[1];
163	      acc->flags_or = flags;
164	      acc->total    = total;
165	      acc->filled   = 0;
166	    }
167	  else if (!acc->in_use || acc->msg_id != msg_id || acc->total != total)
168	    {
169	      return false;
170	    }
171	  else
172	    {
173	      acc->flags_or = (uint8_t)(acc->flags_or | flags);
174	    }
175	
176	  if (off != acc->filled)
177	    {
178	      acc->in_use = false;
179	      return false;
180	    }
181	
182	  if ((uint32_t)off + pay_len > acc->total)
183	    {
184	      acc->in_use = false;
185	      return false;
186	    }
187	
188	  memcpy(acc->data + off, value + COMPANION_NOTIF_HDR_LEN, pay_len);
189	  acc->filled = (uint16_t)(off + pay_len);
190	
191	  if ((flags & COMPANION_NOTIF_FLAG_LAST) != 0)
192	    {
193	      if (acc->filled != acc->total)
194	        {
195	          acc->in_use = false;
196	          return false;
197	        }
198	
199	      *complete = true;
200	      acc->in_use = false;
201	    }
202	
203	  return true;
204	}
205	
206	/**
207	 * @brief 在重组后的通知载荷里查找 TLV 标签。
208	 */
209	static void tlv_find(const uint8_t *buf, uint16_t len, uint8_t tag,
210	                     const uint8_t **val, uint16_t *vlen)
211	{
212	  uint16_t i = 0;
213	
214	  *val  = NULL;
215	  *vlen = 0;
216	
217	  while ((uint32_t)i + 3 <= len)
218	    {
219	      uint8_t  t = buf[i];
220	      uint16_t l = get_le16(buf + i + 1);
221	
222	      i = (uint16_t)(i + 3);
223	      if ((uint32_t)i + l > len)
224	        {
225	          return;
226	        }
227	
228	      if (t == tag)
229	        {
230	          *val  = buf + i;
231	          *vlen = l;
232	          return;
233	        }
234	
235	      i = (uint16_t)(i + l);
236	    }
237	}
238	
239	/**
240	 * @brief 清洗 Android 包名，用作图标文件名。
241	 */
242	static void sanitize_pkg(char *dst, size_t dstsz, const char *src)
243	{
244	  size_t i = 0;
245	  size_t o = 0;
246	
247	  if (dstsz == 0)
248	    {
249	      return;
250	    }
251	
252	  while (src[i] != '\0' && o + 1 < dstsz)
253	    {
254	      char c = src[i++];
255	
256	      if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
257	          (c >= '0' && c <= '9') || c == '.' || c == '_' || c == '-')
258	        {
259	          dst[o++] = c;
260	        }
261	      else
262	        {
263	          dst[o++] = '_';
264	        }
265	    }
266	
267	  dst[o] = '\0';
268	}
269	
270	/**
271	 * @brief 取 basename 再清洗，拒绝 `.` / `..`。
272	 */
273	static void icon_basename(char *dst, size_t dstsz, const char *src)
274	{
275	  const char *base = src;
276	  const char *p;
277	
278	  for (p = src; *p != '\0'; p++)
279	    {
280	      if (*p == '/' || *p == '\\')
281	        {
282	          base = p + 1;
283	        }
284	    }
285	
286	  sanitize_pkg(dst, dstsz, base);
287	  if (strcmp(dst, ".") == 0 || strcmp(dst, "..") == 0)
288	    {
289	      dst[0] = '\0';
290	    }
291	}
292	
293	/**
294	 * @brief 一条完整的 0xFF17 消息；`test notif on` 时打印。
295	 */
296	static void notif_complete(const uint8_t *payload, uint16_t len, uint8_t type)
297	{
298	  const uint8_t *title_v = NULL;
299	  const uint8_t *body_v  = NULL;
300	  const uint8_t *pkg_v   = NULL;
301	  const uint8_t *icon_v  = NULL;
302	  const uint8_t *name_v  = NULL;
303	  uint16_t title_l = 0;
304	  uint16_t body_l  = 0;
305	  uint16_t pkg_l   = 0;
306	  uint16_t icon_l  = 0;
307	  uint16_t name_l  = 0;
308	  char title[COMPANION_NOTIF_TITLE_MAX + 1];
309	  char body[COMPANION_NOTIF_BODY_MAX + 1];
310	  char pkg[COMPANION_NOTIF_PACKAGE_MAX + 1];
311	  char icon_name[COMPANION_NOTIF_ICON_NAME_MAX + 1];
312	  char icon_abs[XFER_PATH_MAX];
313	  char rel[96];
314	  const char *show_title;
315	  bool found = false;
316	
317	  tlv_find(payload, len, COMPANION_NOTIF_TAG_TITLE, &title_v, &title_l);
318	  tlv_find(payload, len, COMPANION_NOTIF_TAG_BODY, &body_v, &body_l);
319	  tlv_find(payload, len, COMPANION_NOTIF_TAG_PACKAGE, &pkg_v, &pkg_l);
320	  tlv_find(payload, len, COMPANION_NOTIF_TAG_ICON, &icon_v, &icon_l);
321	  tlv_find(payload, len, COMPANION_NOTIF_TAG_APP_NAME, &name_v, &name_l);
322	
323	  title[0] = '\0';
324	  body[0]  = '\0';
325	  pkg[0]   = '\0';
326	  icon_name[0] = '\0';
327	  icon_abs[0] = '\0';
328	
329	  if (title_v != NULL)
330	    {
331	      copy_trunc(title, sizeof(title), title_v, title_l);
332	    }
333	  else if (name_v != NULL)
334	    {
335	      copy_trunc(title, sizeof(title), name_v, name_l);
336	    }
337	
338	  if (body_v != NULL)
339	    {
340	      copy_trunc(body, sizeof(body), body_v, body_l);
341	    }
342	
343	  if (pkg_v != NULL)
344	    {
345	      char raw[COMPANION_NOTIF_PACKAGE_MAX + 1];
346	
347	      copy_trunc(raw, sizeof(raw), pkg_v, pkg_l);
348	      sanitize_pkg(pkg, sizeof(pkg), raw);
349	    }
350	
351	  if (icon_v != NULL && icon_l > 0)
352	    {
353	      char raw[COMPANION_NOTIF_ICON_NAME_MAX + 1];
354	
355	      copy_trunc(raw, sizeof(raw), icon_v, icon_l);
356	      icon_basename(icon_name, sizeof(icon_name), raw);
357	    }
358	  else if (pkg[0] != '\0')
359	    {
360	      snprintf(icon_name, sizeof(icon_name), "%s.png", pkg);
361	      if (strcmp(icon_name, ".") == 0 || strcmp(icon_name, "..") == 0)
362	        {
363	          icon_name[0] = '\0';
364	        }
365	    }
366	
367	  strip_bar(title);
368	  strip_bar(body);
369	
370	  show_title = title[0] != '\0' ? title : "通知";
371	  if (body[0] == '\0')
372	    {
373	      strncpy(body, show_title, sizeof(body) - 1);
374	      body[sizeof(body) - 1] = '\0';
375	    }
376	
377	  if (companion_bridge_test_notif_get())
378	    {
379	      LOGI("notif type=%u title=%s body=%s icon=%s", (unsigned)type,
380	           show_title, body, icon_name[0] != '\0' ? icon_name : "-");
381	    }
382	
383	  if (!companion_bridge_policy_notif())
384	    {
385	      return;
386	    }
387	
388	  if (companion_bridge_policy_calls_only() &&
389	      type != COMPANION_NOTIF_TYPE_CALL)
390	    {
391	      return;
392	    }
393	
394	  if (icon_name[0] != '\0')
395	    {
396	      snprintf(rel, sizeof(rel), "%s/%s", COMPANION_NOTIF_ICON_DIR, icon_name);
397	      if (xfer_resolve(rel, strlen(rel), icon_abs, sizeof(icon_abs)) == 0 &&
398	          companion_fs_icon_usable(icon_abs))
399	        {
400	          found = true;
401	        }
402	      else
403	        {
404	          companion_fs_need_file(icon_name);
405	          icon_abs[0] = '\0';
406	        }
407	    }
408	
409	  {
410	    struct companion_notif_item item;
411	
412	    memset(&item, 0, sizeof(item));
413	    item.type = type;
414	    strncpy(item.title, show_title, sizeof(item.title) - 1);
415	    strncpy(item.body, body, sizeof(item.body) - 1);
416	    if (found)
417	      {
418	        strncpy(item.icon, icon_abs, sizeof(item.icon) - 1);
419	      }
420	
421	    companion_bridge_notif_post(&item);
422	  }
423	}
