15	/** @brief 向 256 字节历史窗口追加一字节。 */
16	static void hist_push(uint8_t *hist, uint8_t *pos, uint16_t *n, uint8_t b)
17	{
18	  hist[*pos] = b;
19	  *pos = (uint8_t)(*pos + 1);
20	  if (*n < COMPANION_RLE_WIN)
21	    {
22	      (*n)++;
23	    }
24	}
25	
26	/** @brief 读取历史窗口 off 字节前的字节。 */
27	static uint8_t hist_at(const uint8_t *hist, uint8_t pos, uint16_t n,
28	                       uint16_t off)
29	{
30	  (void)n;
31	  return hist[(uint8_t)(pos - (uint8_t)off)];
32	}
