34	/****************************************************************************
35	 * 解码器
36	 ****************************************************************************/
37	
38	/** @brief 初始化解码器。 */
39	void companion_rle_dec_init(struct companion_rle_dec *d)
40	{
41	  memset(d, 0, sizeof(*d));
42	}
43	
44	/** @brief 解码器是否空闲。 */
45	bool companion_rle_dec_idle(const struct companion_rle_dec *d)
46	{
47	  return d->st == COMPANION_RLE_ST_CTRL && d->need == 0;
48	}
49	
50	/** @brief 解码输出一字节并更新历史。 */
51	static int dec_emit(struct companion_rle_dec *d, uint8_t b,
52	                    companion_rle_out_fn out, void *ctx)
53	{
54	  int ret;
55	
56	  ret = out(ctx, &b, 1);
57	  if (ret != 0)
58	    {
59	      return ret;
60	    }
61	
62	  hist_push(d->hist, &d->hist_pos, &d->hist_n, b);
63	  return 0;
64	}
65	
66	/** @brief 喂入压缩流并回调输出明文。 */
67	int companion_rle_dec_feed(struct companion_rle_dec *d,
68	                           const uint8_t *src, uint16_t n,
69	                           companion_rle_out_fn out, void *ctx)
70	{
71	  uint16_t i = 0;
72	  int      ret;
73	
74	  while (i < n || d->st == COMPANION_RLE_ST_RUN ||
75	         d->st == COMPANION_RLE_ST_CPY)
76	    {
77	      switch (d->st)
78	        {
79	        case COMPANION_RLE_ST_CTRL:
80	          if (i >= n)
81	            {
82	              return 0;
83	            }
84	
85	          {
86	            uint8_t c = src[i++];
87	            if (c < 0x80)
88	              {
89	                d->need = (uint8_t)(c + 1);
90	                d->st   = COMPANION_RLE_ST_LIT;
91	              }
92	            else if (c < 0xC0)
93	              {
94	                d->need = (uint8_t)((c & 0x3f) + 2);
95	                d->st   = COMPANION_RLE_ST_RUN_BYTE;
96	              }
97	            else
98	              {
99	                d->need = (uint8_t)((c & 0x3f) + 3);
100	                d->st   = COMPANION_RLE_ST_CPY_OFF;
101	              }
102	          }
103	          break;
104	
105	        case COMPANION_RLE_ST_LIT:
106	          if (i >= n)
107	            {
108	              return 0;
109	            }
110	
111	          ret = dec_emit(d, src[i++], out, ctx);
112	          if (ret != 0)
113	            {
114	              return ret;
115	            }
116	
117	          if (--d->need == 0)
118	            {
119	              d->st = COMPANION_RLE_ST_CTRL;
120	            }
121	          break;
122	
123	        case COMPANION_RLE_ST_RUN_BYTE:
124	          if (i >= n)
125	            {
126	              return 0;
127	            }
128	
129	          d->arg = src[i++];
130	          d->st  = COMPANION_RLE_ST_RUN;
131	          break;
132	
133	        case COMPANION_RLE_ST_RUN:
134	          while (d->need > 0)
135	            {
136	              ret = dec_emit(d, d->arg, out, ctx);
137	              if (ret != 0)
138	                {
139	                  return ret;
140	                }
141	
142	              d->need--;
143	            }
144	
145	          d->st = COMPANION_RLE_ST_CTRL;
146	          break;
147	
148	        case COMPANION_RLE_ST_CPY_OFF:
149	          if (i >= n)
150	            {
151	              return 0;
152	            }
153	
154	          d->arg = src[i++];
155	          if (d->arg == 0)
156	            {
157	              return EINVAL;
158	            }
159	
160	          d->st = COMPANION_RLE_ST_CPY;
161	          break;
162	
163	        case COMPANION_RLE_ST_CPY:
164	          if (d->arg > d->hist_n)
165	            {
166	              return EINVAL;
167	            }
168	
169	          while (d->need > 0)
170	            {
171	              uint8_t b = hist_at(d->hist, d->hist_pos, d->hist_n, d->arg);
172	              ret = dec_emit(d, b, out, ctx);
173	              if (ret != 0)
174	                {
175	                  return ret;
176	                }
177	
178	              d->need--;
179	            }
180	
181	          d->st = COMPANION_RLE_ST_CTRL;
182	          break;
183	
184	        default:
185	          return EINVAL;
186	        }
187	    }
188	
189	  return 0;
190	}
