192	/****************************************************************************
193	 * 编码器
194	 ****************************************************************************/
195	
196	/** @brief 初始化编码器。 */
197	void companion_rle_enc_init(struct companion_rle_enc *e)
198	{
199	  memset(e, 0, sizeof(*e));
200	}
201	
202	/** @brief 编码器 look 缓冲剩余空间。 */
203	uint16_t companion_rle_enc_room(const struct companion_rle_enc *e)
204	{
205	  return (uint16_t)(COMPANION_RLE_LOOK - e->look_n);
206	}
207	
208	/** @brief 待编码字节数。 */
209	uint16_t companion_rle_enc_pending(const struct companion_rle_enc *e)
210	{
211	  return e->look_n;
212	}
213	
214	int companion_rle_enc_push(struct companion_rle_enc *e,
215	                           const uint8_t *src, uint16_t n)
216	{
217	  if (n > companion_rle_enc_room(e))
218	    {
219	      return EINVAL;
220	    }
221	
222	  if (n > 0)
223	    {
224	      memcpy(e->look + e->look_n, src, n);
225	      e->look_n = (uint16_t)(e->look_n + n);
226	    }
227	
228	  return 0;
229	}
230	
231	/** @brief 消费 look 前缀并更新历史。 */
232	static void enc_consume(struct companion_rle_enc *e, uint16_t n)
233	{
234	  uint16_t i;
235	
236	  for (i = 0; i < n; i++)
237	    {
238	      hist_push(e->hist, &e->hist_pos, &e->hist_n, e->look[i]);
239	    }
240	
241	  e->look_n = (uint16_t)(e->look_n - n);
242	  if (e->look_n > 0)
243	    {
244	      memmove(e->look, e->look + n, e->look_n);
245	    }
246	}
247	
248	/** @brief 编码窗口相对偏移读字节。 */
249	static uint8_t window_at(const struct companion_rle_enc *e, uint16_t start,
250	                         uint16_t off)
251	{
252	  if (off <= start)
253	    {
254	      return e->look[start - off];
255	    }
256	
257	  return hist_at(e->hist, e->hist_pos, e->hist_n, (uint16_t)(off - start));
258	}
259	
260	/** @brief 从 start 找最长重复 run。 */
261	static void find_run_from(const struct companion_rle_enc *e, uint16_t start,
262	                          uint16_t *run)
263	{
264	  uint16_t avail = (uint16_t)(e->look_n - start);
265	  uint16_t n     = 1;
266	  uint16_t max   = avail;
267	
268	  if (max > COMPANION_RLE_MAX_RUN)
269	    {
270	      max = COMPANION_RLE_MAX_RUN;
271	    }
272	
273	  while (n < max && e->look[start + n] == e->look[start])
274	    {
275	      n++;
276	    }
277	
278	  *run = n;
279	}
280	
281	/** @brief 从 start 找最长 LZ 匹配。 */
282	static void find_match_from(const struct companion_rle_enc *e, uint16_t start,
283	                            uint16_t *best_len, uint16_t *best_off)
284	{
285	  uint16_t avail      = (uint16_t)(e->look_n - start);
286	  uint16_t hist_total = (uint16_t)(e->hist_n + start);
287	  uint16_t max_len    = avail;
288	  uint16_t off;
289	  uint8_t  b0;
290	  uint8_t  b1;
291	  uint8_t  b2;
292	
293	  *best_len = 0;
294	  *best_off = 0;
295	
296	  if (hist_total > COMPANION_RLE_WIN)
297	    {
298	      hist_total = COMPANION_RLE_WIN;
299	    }
300	
301	  if (avail < 3 || hist_total == 0)
302	    {
303	      return;
304	    }
305	
306	  if (max_len > COMPANION_RLE_MAX_CPY)
307	    {
308	      max_len = COMPANION_RLE_MAX_CPY;
309	    }
310	
311	  /* Compare look[start + m] with the byte `off` behind that position.
312	   * Using window_at(start+m, off) avoids a software `%` in the inner
313	   * loop (the old `off - (m % off)` form was too slow on the MCU, so
314	   * download RLE filled notify pages slower than raw BLE).
315	   */
316	  b0 = e->look[start];
317	  b1 = e->look[start + 1];
318	  b2 = e->look[start + 2];
319	
320	  for (off = 1; off <= hist_total; off++)
321	    {
322	      uint16_t m;
323	
324	      if (window_at(e, start, off) != b0)
325	        {
326	          continue;
327	        }
328	
329	      if (window_at(e, (uint16_t)(start + 1), off) != b1 ||
330	          window_at(e, (uint16_t)(start + 2), off) != b2)
331	        {
332	          continue;
333	        }
334	
335	      m = 3;
336	      while (m < max_len &&
337	             window_at(e, (uint16_t)(start + m), off) == e->look[start + m])
338	        {
339	          m++;
340	        }
341	
342	      if (m > *best_len)
343	        {
344	          *best_len = m;
345	          *best_off = off;
346	          if (m == max_len)
347	            {
348	              break;
349	            }
350	        }
351	    }
352	}
353	
354	/** @brief pull 压缩字节到 out。 */
355	uint16_t companion_rle_enc_pull(struct companion_rle_enc *e,
356	                                uint8_t *out, uint16_t out_max, bool finish)
357	{
358	  uint16_t used = 0;
359	
360	  while (e->look_n > 0)
361	    {
362	      uint16_t run;
363	      uint16_t ml;
364	      uint16_t off;
365	      uint16_t lit;
366	      uint16_t max_lit;
367	
368	      if (!finish && e->look_n < COMPANION_RLE_MAX_CPY)
369	        {
370	          break;
371	        }
372	
373	      find_run_from(e, 0, &run);
374	      find_match_from(e, 0, &ml, &off);
375	
376	      if (ml >= 3 && ml >= run)
377	        {
378	          if ((uint16_t)(out_max - used) < 2)
379	            {
380	              break;
381	            }
382	
383	          out[used++] = (uint8_t)(0xc0 | (ml - 3));
384	          out[used++] = (uint8_t)off;
385	          enc_consume(e, ml);
386	        }
387	      else if (run >= 3)
388	        {
389	          if ((uint16_t)(out_max - used) < 2)
390	            {
391	              break;
392	            }
393	
394	          out[used++] = (uint8_t)(0x80 | (run - 2));
395	          out[used++] = e->look[0];
396	          enc_consume(e, run);
397	        }
398	      else
399	        {
400	          if ((uint16_t)(out_max - used) < 2)
401	            {
402	              break;
403	            }
404	
405	          max_lit = COMPANION_RLE_MAX_LIT;
406	          if (max_lit > e->look_n)
407	            {
408	              max_lit = e->look_n;
409	            }
410	
411	          if (max_lit > (uint16_t)(out_max - used - 1))
412	            {
413	              max_lit = (uint16_t)(out_max - used - 1);
414	            }
415	
416	          if (max_lit < 1)
417	            {
418	              break;
419	            }
420	
421	          lit = 1;
422	          while (lit < max_lit)
423	            {
424	              uint16_t r2;
425	              uint16_t m2;
426	              uint16_t o2;
427	
428	              if (!finish &&
429	                  (uint16_t)(e->look_n - lit) < COMPANION_RLE_MAX_CPY)
430	                {
431	                  break;
432	                }
433	
434	              find_run_from(e, lit, &r2);
435	              find_match_from(e, lit, &m2, &o2);
436	              if ((m2 >= 3 && m2 >= r2) || r2 >= 3)
437	                {
438	                  break;
439	                }
440	
441	              lit++;
442	            }
443	
444	          out[used++] = (uint8_t)(lit - 1);
445	          memcpy(out + used, e->look, lit);
446	          used = (uint16_t)(used + lit);
447	          enc_consume(e, lit);
448	        }
449	    }
450	
451	  return used;
452	}
