456	#include <stdio.h>
457	#include <stdlib.h>
458	
459	struct grow
460	{
461	  uint8_t *p;
462	  size_t   n;
463	  size_t   cap;
464	};
465	
466	static int grow_out(void *ctx, const uint8_t *p, uint16_t n)
467	{
468	  struct grow *g = ctx;
469	  if (g->n + n > g->cap)
470	    {
471	      size_t cap = g->cap ? g->cap * 2 : 4096;
472	      while (cap < g->n + n)
473	        {
474	          cap *= 2;
475	        }
476	
477	      g->p = realloc(g->p, cap);
478	      g->cap = cap;
479	    }
480	
481	  memcpy(g->p + g->n, p, n);
482	  g->n += n;
483	  return 0;
484	}
485	
486	static uint8_t *load(const char *path, size_t *n)
487	{
488	  FILE *fp = fopen(path, "rb");
489	  uint8_t *p;
490	  if (!fp)
491	    {
492	      perror(path);
493	      return NULL;
494	    }
495	
496	  fseek(fp, 0, SEEK_END);
497	  *n = (size_t)ftell(fp);
498	  fseek(fp, 0, SEEK_SET);
499	  p = malloc(*n);
500	  if (!p || fread(p, 1, *n, fp) != *n)
501	    {
502	      fclose(fp);
503	      free(p);
504	      return NULL;
505	    }
506	
507	  fclose(fp);
508	  return p;
509	}
