511	int main(int argc, char **argv)
512	{
513	  uint8_t *src;
514	  size_t   n;
515	  struct companion_rle_enc enc;
516	  struct companion_rle_dec dec;
517	  struct grow encb = {0};
518	  struct grow decb = {0};
519	  uint8_t tmp[256];
520	  size_t off = 0;
521	
522	  if (argc < 2)
523	    {
524	      fprintf(stderr, "usage: %s file\n", argv[0]);
525	      return 1;
526	    }
527	
528	  src = load(argv[1], &n);
529	  if (!src)
530	    {
531	      return 1;
532	    }
533	
534	  companion_rle_enc_init(&enc);
535	  while (off < n || companion_rle_enc_pending(&enc) > 0)
536	    {
537	      uint16_t room = companion_rle_enc_room(&enc);
538	      uint16_t chunk;
539	      uint16_t produced;
540	      bool     finish;
541	
542	      if (room > 0 && off < n)
543	        {
544	          chunk = room;
545	          if ((size_t)chunk > n - off)
546	            {
547	              chunk = (uint16_t)(n - off);
548	            }
549	
550	          companion_rle_enc_push(&enc, src + off, chunk);
551	          off += chunk;
552	        }
553	
554	      finish = (off >= n);
555	      produced = companion_rle_enc_pull(&enc, tmp, sizeof(tmp), finish);
556	      if (produced == 0 && finish && companion_rle_enc_pending(&enc) == 0)
557	        {
558	          break;
559	        }
560	
561	      if (produced == 0 && !finish)
562	        {
563	          continue;
564	        }
565	
566	      grow_out(&encb, tmp, produced);
567	    }
568	
569	  companion_rle_dec_init(&dec);
570	  off = 0;
571	  while (off < encb.n)
572	    {
573	      uint16_t chunk = 256;
574	      if ((size_t)chunk > encb.n - off)
575	        {
576	          chunk = (uint16_t)(encb.n - off);
577	        }
578	
579	      if (companion_rle_dec_feed(&dec, encb.p + off, chunk, grow_out,
580	                                 &decb) != 0)
581	        {
582	          fprintf(stderr, "decode error at %zu\n", off);
583	          return 1;
584	        }
585	
586	      off += chunk;
587	    }
588	
589	  if (!companion_rle_dec_idle(&dec) || decb.n != n ||
590	      memcmp(decb.p, src, n) != 0)
591	    {
592	      fprintf(stderr, "roundtrip FAIL src=%zu enc=%zu dec=%zu idle=%d\n",
593	              n, encb.n, decb.n, companion_rle_dec_idle(&dec));
594	      return 1;
595	    }
596	
597	  printf("ok src=%zu enc=%zu ratio=%.2f\n", n, encb.n,
598	         n ? (double)n / (double)encb.n : 0);
599	  return 0;
600	}
