162	/** @brief 分配 FS 读写/RLE 缓冲（PSRAM/board_malloc）。 */
163	static void fs_buffers_init(void)
164	{
165	  if (g_fs.data_q == NULL)
166	    {
167	      g_fs.data_q = board_malloc_psram(sizeof(struct fs_data_slot) *
168	                                       (size_t)FS_DATA_SLOTS);
169	      if (g_fs.data_q != NULL)
170	        {
171	          g_fs.data_q_cap = FS_DATA_SLOTS;
172	          LOGI("fs rx ring %u slots in PSRAM", (unsigned)FS_DATA_SLOTS);
173	        }
174	      else
175	        {
176	          g_fs.data_q     = g_data_q_sram;
177	          g_fs.data_q_cap = (uint16_t)(sizeof(g_data_q_sram) /
178	                                       sizeof(g_data_q_sram[0]));
179	          LOGE("fs rx ring PSRAM alloc failed, SRAM fallback %u",
180	               (unsigned)g_fs.data_q_cap);
181	        }
182	    }
183	
184	  if (g_fs.wbuf == NULL)
185	    {
186	      g_fs.wbuf = board_malloc_psram(FS_WBUF_SIZE);
187	      if (g_fs.wbuf != NULL)
188	        {
189	          g_fs.wbuf_cap = FS_WBUF_SIZE;
190	          LOGI("fs write cache %u KiB in PSRAM",
191	               (unsigned)(FS_WBUF_SIZE / 1024));
192	        }
193	      else
194	        {
195	          LOGE("fs write cache PSRAM alloc failed, write-through");
196	        }
197	    }
198	
199	  if (g_fs.rbuf == NULL)
200	    {
201	      g_fs.rbuf = board_malloc_psram(FS_RBUF_SIZE);
202	      if (g_fs.rbuf != NULL)
203	        {
204	          g_fs.rbuf_cap = FS_RBUF_SIZE;
205	          LOGI("fs read cache %u KiB in PSRAM",
206	               (unsigned)(FS_RBUF_SIZE / 1024));
207	        }
208	      else
209	        {
210	          LOGE("fs read cache PSRAM alloc failed, uncached reads");
211	        }
