228	/** @brief 从读缓冲或 LFS 取数据（含 RLE 解码）。 */
229	static int rbuf_get(uint32_t off, uint8_t *dst, uint16_t want, uint16_t *got)
230	{
231	  uint16_t copied = 0;
232	  int      ret;
233	
234	  *got = 0;
235	  if (want == 0)
236	    {
237	      return 0;
238	    }
239	
240	  if (g_fs.rfd < 0)
241	    {
242	      return xfer_read(g_fs.path, off, dst, want, got);
243	    }
244	
245	  while (copied < want)
246	    {
247	      uint16_t n;
248	      uint16_t loaded = 0;
249	
250	      if (g_fs.rbuf != NULL && g_fs.rbuf_len > 0 &&
251	          off >= g_fs.rbuf_off &&
252	          off < g_fs.rbuf_off + g_fs.rbuf_len)
253	        {
254	          uint32_t idx = off - g_fs.rbuf_off;
255	          uint32_t have = g_fs.rbuf_len - idx;
256	
257	          n = (uint16_t)have;
258	          if (n > (uint16_t)(want - copied))
259	            {
260	              n = (uint16_t)(want - copied);
261	            }
262	
263	          memcpy(dst + copied, g_fs.rbuf + idx, n);
264	          copied = (uint16_t)(copied + n);
265	          off += n;
266	          continue;
267	        }
268	
269	      if (g_fs.rfd_pos != off)
270	        {
271	          ret = xfer_read_seek(g_fs.rfd, off);
272	          if (ret != 0)
273	            {
274	              return ret;
275	            }
276	
277	          g_fs.rfd_pos = off;
278	        }
279	
280	      if (g_fs.rbuf != NULL && g_fs.rbuf_cap > 0)
281	        {
282	          uint16_t load_n = (uint16_t)g_fs.rbuf_cap;
283	
284	          ret = xfer_read_data(g_fs.rfd, g_fs.rbuf, load_n, &loaded);
285	          if (ret != 0)
286	            {
287	              return ret;
288	            }
289	
290	          g_fs.rbuf_off = off;
291	          g_fs.rbuf_len = loaded;
292	          g_fs.rfd_pos  = off + loaded;
293	          if (loaded == 0)
294	            {
295	              break;
296	            }
297	
298	          continue;
299	        }
300	
301	      n = (uint16_t)(want - copied);
302	      ret = xfer_read_data(g_fs.rfd, dst + copied, n, &loaded);
303	      if (ret != 0)
304	        {
305	          return ret;
306	        }
307	
308	      g_fs.rfd_pos += loaded;
309	      copied = (uint16_t)(copied + loaded);
310	      off += loaded;
311	      if (loaded == 0)
312	        {
313	          break;
314	        }
315	    }
316	
317	  *got = copied;
318	  return 0;
319	}
