329	/** @brief 边收边写。CLOSE 抽环阶段禁止写盘，否则 App 等应答时第一次
330	 * lfs_alloc 会卡数秒。OTA 也曾攒满 256KiB 再写，BLE 环先满丢包变成 seq gap。 */
331	static bool wbuf_stream_disk(void)
332	{
333	  return !g_fs.disk_hold;
334	}
