336	/** @brief 写出写缓冲一个 chunk。 */
337	static int wbuf_flush_chunk(void)
338	{
339	  uint32_t n;
340	  int      ret;
341	
342	  if (g_fs.wbuf_len == 0)
343	    {
344	      return 0;
345	    }
346	
347	  if (g_fs.wfd < 0)
348	    {
349	      g_fs.wbuf_len = 0;
350	      return EINVAL;
351	    }
352	
353	  n = g_fs.wbuf_len;
354	  if (n > FS_FLUSH_CHUNK)
355	    {
356	      n = FS_FLUSH_CHUNK;
357	    }
358	
359	  ret = xfer_write_data(g_fs.wfd, g_fs.wbuf, n);
360	  if (ret != 0)
361	    {
362	      LOGI("fs write flush failed errno=%d n=%lu got=%lu",
363	           ret, (unsigned long)n, (unsigned long)g_fs.w_got);
364	      return ret;
365	    }
366	
367	  {
368	    uint32_t before = g_fs.w_flushed;
369	
370	    g_fs.w_flushed += n;
371	    if (before == 0u ||
372	        (before / (32u * 1024u)) != (g_fs.w_flushed / (32u * 1024u)))
373	      {
374	        LOGI("fs write flushed %lu/%lu",
375	             (unsigned long)g_fs.w_flushed,
376	             (unsigned long)g_fs.w_expected);
377	      }
378	
379	    /* OTA 在 /mnt/kv：不定期 fsync 的话，复位后 LittleFS 会回到
380	     * WRITE_OPEN 时的 size，刚写的一两兆续传就没了。 */
381	    if (path_is_ota_fw(g_fs.path) &&
382	        (before / FS_SYNC_BYTES) != (g_fs.w_flushed / FS_SYNC_BYTES))
383	      {
384	        myvendor_watchdog_work_beat();
385	        myvendor_watchdog_hw_pet();
386	        (void)fsync(g_fs.wfd);
387	        myvendor_watchdog_hw_pet();
388	        LOGI("fs write synced %lu/%lu",
389	             (unsigned long)g_fs.w_flushed,
390	             (unsigned long)g_fs.w_expected);
391	      }
392	  }
393	
394	  if (n < g_fs.wbuf_len)
395	    {
396	      memmove(g_fs.wbuf, g_fs.wbuf + n, g_fs.wbuf_len - n);
397	    }
398	
399	  g_fs.wbuf_len -= n;
400	  return 0;
401	}
402	
403	static int wbuf_flush(void)
404	{
405	  int ret;
406	
407	  while (g_fs.wbuf_len > 0)
408	    {
409	      ret = wbuf_flush_chunk();
410	      if (ret != 0)
411	        {
412	          return ret;
413	        }
414	
415	      if (g_fs.wbuf_len > 0)
416	        {
417	          wbuf_yield();
418	        }
419	    }
420	
421	  return 0;
422	}
423	
424	/** @brief 追加明文到写缓冲（必要时 flush）。 */
425	static int wbuf_append(const uint8_t *p, uint16_t n)
426	{
427	  int ret;
428	
429	  if (n == 0)
430	    {
431	      return 0;
432	    }
433	
434	  if (g_fs.wbuf == NULL || g_fs.wbuf_cap == 0)
435	    {
436	      return xfer_write_data(g_fs.wfd, p, n);
437	    }
438	
439	  while (g_fs.wbuf_len + n > g_fs.wbuf_cap)
440	    {
441	      ret = wbuf_flush_chunk();
442	      if (ret != 0)
443	        {
444	          return ret;
445	        }
446	
447	      wbuf_yield();
448	    }
449	
450	  if (n > g_fs.wbuf_cap)
451	    {
452	      return xfer_write_data(g_fs.wfd, p, n);
453	    }
454	
455	  memcpy(g_fs.wbuf + g_fs.wbuf_len, p, n);
456	  g_fs.wbuf_len += n;
457	
458	  /* 满 4KiB 就写。否则 BLE 先把整文件堆进 RAM，环满丢包。 */
459	  if (wbuf_stream_disk())
460	    {
461	      while (g_fs.wbuf_len >= FS_FLUSH_CHUNK)
462	        {
463	          ret = wbuf_flush_chunk();
464	          if (ret != 0)
465	            {
466	              return ret;
467	            }
468	
469	          wbuf_yield();
470	        }
471	    }
472	
473	  return 0;
474	}
