477	 * @brief 唤醒 companion 线程（READ 等待时不要睡满 500 ms）。
478	 */
479	void companion_fs_kick(void)
480	{
481	  if (g_fs_wake_ready)
482	    {
483	      (void)sem_post(&g_fs_wake);
484	    }
485	}
