487	/**
488	 * @brief 睡到 kick 或超时。
489	 * @param timeout_ms 最长等待。
490	 */
491	void companion_fs_wait(uint32_t timeout_ms)
492	{
493	  struct timespec ts;
494	
495	  if (!g_fs_wake_ready)
496	    {
497	      usleep(timeout_ms * 1000);
498	      return;
499	    }
500	
501	  while (sem_trywait(&g_fs_wake) == 0)
502	    {
503	    }
504	
505	  if (timeout_ms == 0)
506	    {
507	      return;
508	    }
509	
510	  clock_gettime(CLOCK_REALTIME, &ts);
511	  ts.tv_sec += (time_t)(timeout_ms / 1000);
512	  ts.tv_nsec += (long)(timeout_ms % 1000) * 1000000L;
513	  if (ts.tv_nsec >= 1000000000L)
514	    {
515	      ts.tv_sec++;
516	      ts.tv_nsec -= 1000000000L;
517	    }
518	
519	  (void)sem_timedwait(&g_fs_wake, &ts);
520	  while (sem_trywait(&g_fs_wake) == 0)
521	    {
522	    }
523	}
