541	/** @brief 写入小端 uint32。 */
542	static void put_le32(uint8_t *p, uint32_t v)
543	{
544	  p[0] = (uint8_t)(v & 0xff);
545	  p[1] = (uint8_t)((v >> 8) & 0xff);
546	  p[2] = (uint8_t)((v >> 16) & 0xff);
547	  p[3] = (uint8_t)((v >> 24) & 0xff);
548	}
