556	/** @brief 读出小端 uint32。 */
557	static uint32_t get_le32(const uint8_t *p)
558	{
559	  return (uint32_t)p[0] | ((uint32_t)p[1] << 8) |
560	         ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
561	}
