563	/** @brief errno 映射为协议 uint8 错误码。 */
564	static uint8_t errno_u8(int err)
565	{
566	  if (err < 0)
567	    {
568	      err = -err;
569	    }
570	
571	  if (err <= 0)
572	    {
573	      return 0;
574	    }
575	
576	  if (err > 255)
577	    {
578	      return 255;
579	    }
580	
581	  return (uint8_t)err;
582	}
