584	/** @brief 当前 ATT MTU 下 FS notify 载荷预算。 */
585	static uint16_t payload_budget(void)
586	{
587	  uint32_t att;
588	
589	  att = (g_fs.mtu > 3) ? (g_fs.mtu - 3) : 20;
590	  if (att < COMPANION_FS_HDR_LEN + 1)
591	    {
592	      return 0;
593	    }
594	
595	  att -= COMPANION_FS_HDR_LEN;
596	  if (att > sizeof(g_fs.tx) - COMPANION_FS_HDR_LEN)
597	    {
598	      att = sizeof(g_fs.tx) - COMPANION_FS_HDR_LEN;
599	    }
600	
601	  return (uint16_t)att;
602	}
