711	/** @brief 校验 notif 图标文件名合法。 */
712	static bool icon_name_ok(const char *name)
713	{
714	  size_t n;
715	  size_t i;
716	
717	  if (name == NULL || name[0] == '\0')
718	    {
719	      return false;
720	    }
721	
722	  if (strcmp(name, ".") == 0 || strcmp(name, "..") == 0)
723	    {
724	      return false;
725	    }
726	
727	  n = strlen(name);
728	  if (n == 0 || n > FS_NEED_NAME_MAX)
729	    {
730	      return false;
731	    }
732	
733	  for (i = 0; i < n; i++)
734	    {
735	      char c = name[i];
736	
737	      if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
738	            (c >= '0' && c <= '9') || c == '.' || c == '_' || c == '-'))
739	        {
740	          return false;
741	        }
742	    }
743	
744	  return true;
745	}
