754	/** @brief BLE 写入的 GNSS 星历（/eph 下 .ubx），写完后热加载。 */
755	static bool path_is_gnss_eph(const char *path)
756	{
757	  const char *name;
758	  size_t n;
759	
760	  if (path == NULL || strstr(path, "/eph/") == NULL) {
761	    return false;
762	  }
763	
764	  name = strrchr(path, '/');
765	  name = (name != NULL) ? name + 1 : path;
766	  n = strlen(name);
767	  if (n < 5) {
768	    return false;
769	  }
770	
771	  return name[n - 4] == '.' &&
772	         (name[n - 3] == 'u' || name[n - 3] == 'U') &&
773	         (name[n - 2] == 'b' || name[n - 2] == 'B') &&
774	         (name[n - 1] == 'x' || name[n - 1] == 'X');
