787	/** @brief CLOSE 已应答后把 RAM 缓冲写入 *.part 并 rename。 */
788	static void fs_deferred_commit(void)
789	{
790	  int ret;
791	  bool icon = path_is_notif_icon(g_fs.path);
792	  bool eph = path_is_gnss_eph(g_fs.path);
793	  uint32_t t0 = fs_now_ms();
794	  uint32_t left = g_fs.wbuf_len;
795	
796	  ret = wbuf_flush();
797	  if (ret == 0)
798	    {
799	      ret = xfer_write_commit(g_fs.wfd, g_fs.tmp_path, g_fs.path);
800	    }
801	
802	  g_fs.wfd = -1;
803	  if (ret == 0 && icon && !icon_png_ok(g_fs.path))
804	    {
805	      unlink(g_fs.path);
806	      ret = EIO;
807	      LOGI("fs write commit rejected icon %s", g_fs.path);
808	    }
809	
810	  release_lfs();
811	  g_fs.state = FS_IDLE;
812	  if (ret != 0)
813	    {
814	      LOGI("fs write commit after-ack failed %s errno=%d", g_fs.path, ret);
815	      return;
816	    }
817	
818	  LOGI("fs write commit %s %lu bytes leftover=%lu %ums",
819	       g_fs.path, (unsigned long)g_fs.w_expected,
820	       (unsigned long)left,
821	       (unsigned)myvendor_mono_elapsed_ms(fs_now_ms(), t0));
822	  if (eph)
823	    {
824	      myvendor_gnss_eph_reload();
825	      LOGI("fs eph reload %s", g_fs.path);
826	    }
827	}
