829	/** @brief 校验 PNG 头与大小。 */
830	static bool icon_png_ok(const char *abs_path)
831	{
832	  static const uint8_t sig[8] =
833	    {
834	      0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a
835	    };
836	  struct stat st;
837	  uint8_t     hdr[24];
838	  int         fd;
839	  ssize_t     n;
840	
841	  if (abs_path == NULL || abs_path[0] == '\0')
842	    {
843	      return false;
844	    }
845	
846	  if (stat(abs_path, &st) != 0 || !S_ISREG(st.st_mode))
847	    {
848	      return false;
849	    }
850	
851	  if (st.st_size < FS_ICON_PNG_MIN || st.st_size > FS_ICON_PNG_MAX)
852	    {
853	      return false;
854	    }
855	
856	  fd = open(abs_path, O_RDONLY);
857	  if (fd < 0)
858	    {
859	      return false;
860	    }
861	
862	  n = read(fd, hdr, sizeof(hdr));
863	  close(fd);
864	  if (n < (ssize_t)sizeof(hdr))
865	    {
866	      return false;
867	    }
868	
869	  if (memcmp(hdr, sig, sizeof(sig)) != 0)
870	    {
871	      return false;
872	    }
873	
874	  return memcmp(hdr + 12, "IHDR", 4) == 0;
875	}
