928	static bool try_queue_need_locked(void)
929	{
930	  int      i;
931	  uint16_t n;
932	  char     dir[XFER_PATH_MAX];
933	  int      ret;
934	
935	  if (g_fs.state != FS_IDLE || g_fs.tx_len != 0 || g_fs.tx_err ||
936	      g_fs.tx_last || !g_fs.connected || !g_fs.ccc)
937	    {
