948	      n = (uint16_t)strlen(g_fs.need[i].name);
949	      ret = xfer_resolve(COMPANION_NOTIF_ICON_DIR,
950	                         strlen(COMPANION_NOTIF_ICON_DIR),
951	                         dir, sizeof(dir));
952	      if (ret == 0)
953	        {
954	          hold_lfs();
955	          ret = xfer_mkdir(dir);
956	          release_lfs();
957	          if (ret != 0 && ret != EEXIST)
958	            {
959	              LOGI("fs need mkdir %s failed %d", dir, ret);
960	            }
961	        }
962	
963	      g_fs.state = FS_REPLY;
964	      queue_ok(COMPANION_FS_NEED, 0, (const uint8_t *)g_fs.need[i].name,
965	               n, true);
966	      g_fs.need[i].pending = false;
967	      g_fs.need[i].last_ms = fs_now_ms();
968	      LOGI("fs need %s", g_fs.need[i].name);
969	      return true;
970	    }
971	
972	  return false;
973	}
