1045	/** @brief 开始 READ 会话。 */
1046	static void handle_read_begin(uint8_t tid, const uint8_t *payload,
1047	                              uint16_t plen)
1048	{
1049	  uint8_t  flags;
1050	  uint16_t poff;
1051	  int      ret;
1052	  char     prev[XFER_PATH_MAX];
1053	
1054	  if (plen < 8)
1055	    {
1056	      queue_err(COMPANION_FS_READ, tid, EINVAL);
1057	      return;
1058	    }
1059	
1060	  g_fs.read_off = get_le32(payload);
1061	  g_fs.read_len = get_le32(payload + 4);
1062	  flags = 0;
1063	  poff  = 8;
1064	  if (plen >= 9)
1065	    {
1066	      flags = payload[8];
1067	      poff  = 9;
1068	    }
1069	
1070	  prev[0] = '\0';
1071	  if (g_fs.rfd >= 0)
1072	    {
1073	      memcpy(prev, g_fs.path, sizeof(prev));
1074	      prev[sizeof(prev) - 1] = '\0';
1075	    }
1076	
1077	  ret = xfer_resolve((const char *)(payload + poff), (size_t)(plen - poff),
1078	                     g_fs.path, sizeof(g_fs.path));
1079	  if (ret != 0)
1080	    {
1081	      queue_err(COMPANION_FS_READ, tid, ret);
1082	      return;
1083	    }
1084	
1085	  hold_lfs();
1086	  if (g_fs.rfd < 0 || strncmp(prev, g_fs.path, sizeof(prev)) != 0)
1087	    {
1088	      read_fd_close();
1089	      ret = xfer_read_open(g_fs.path, &g_fs.rfd);
1090	      if (ret != 0)
1091	        {
1092	          release_lfs();
1093	          queue_err(COMPANION_FS_READ, tid, ret);
1094	          return;
1095	        }
1096	
1097	      g_fs.rfd_pos  = 0;
1098	      g_fs.rbuf_len = 0;
1099	    }
1100	
1101	  g_fs.cmd   = COMPANION_FS_READ;
1102	  g_fs.tid   = tid;
1103	  g_fs.seq   = 0;
1104	  g_fs.r_rle = (flags & COMPANION_FS_READ_FLAG_RLE) != 0;
1105	  companion_rle_enc_init(&g_fs.rle_enc);
1106	  g_fs.state = FS_READ;
1107	  LOGI("fs read %s off=%lu len=%lu rle=%d",
1108	       g_fs.path, (unsigned long)g_fs.read_off, (unsigned long)g_fs.read_len,
1109	       (int)g_fs.r_rle);
1110	}
