1112	/** @brief 处理 WRITE OPEN。 */
1113	static void handle_write_open(uint8_t tid, const uint8_t *payload,
1114	                              uint16_t plen)
1115	{
1116	  uint8_t  flags;
1117	  uint32_t off = 0;
1118	  uint32_t crc = 0;
1119	  uint8_t  reply[COMPANION_FS_WRITE_OPEN_REPLY_LEN];
1120	  bool     resume;
1121	  int      ret;
1122	
1123	  if (plen < 5)
1124	    {
1125	      queue_err(COMPANION_FS_WRITE_OPEN, tid, EINVAL);
1126	      return;
1127	    }
1128	
1129	  fs_buffers_init();
1130	  session_reset(false);
1131	  g_fs.w_expected = get_le32(payload);
1132	  flags  = payload[4];
1133	  resume = (flags & COMPANION_FS_WRITE_FLAG_RESUME) != 0;
1134	  g_fs.w_rle = (flags & COMPANION_FS_WRITE_FLAG_RLE) != 0;
1135	  companion_rle_dec_init(&g_fs.rle_dec);
1136	  ret = xfer_resolve((const char *)(payload + 5), (size_t)(plen - 5),
1137	                     g_fs.path, sizeof(g_fs.path));
1138	  if (ret != 0)
1139	    {
1140	      queue_err(COMPANION_FS_WRITE_OPEN, tid, ret);
1141	      return;
1142	    }
1143	
1144	  hold_lfs();
1145	  ret = xfer_write_open(g_fs.path, g_fs.tmp_path, sizeof(g_fs.tmp_path),
1146	                        &g_fs.wfd, resume, &off, &crc);
1147	  if (ret != 0)
1148	    {
1149	      release_lfs();
1150	      queue_err(COMPANION_FS_WRITE_OPEN, tid, ret);
1151	      return;
1152	    }
1153	
1154	  if (off > g_fs.w_expected)
1155	    {
1156	      xfer_write_suspend(g_fs.wfd);
1157	      g_fs.wfd = -1;
1158	      release_lfs();
1159	      queue_err(COMPANION_FS_WRITE_OPEN, tid, EINVAL);
1160	      return;
1161	    }
1162	
1163	  g_fs.w_got  = off;
1164	  g_fs.w_flushed = off;
1165	  g_fs.w_crc  = crc;
1166	  g_fs.rx_seq = 0;
1167	  g_fs.w_fail = 0;
1168	  g_fs.cmd    = COMPANION_FS_WRITE_OPEN;
1169	  g_fs.tid    = tid;
1170	  g_fs.seq    = 0;
1171	  g_fs.state  = FS_WRITE;
1172	  put_le32(reply, off);
1173	  put_le32(reply + 4, crc);
1174	  LOGI("fs write open %s resume=%d rle=%d off=%lu crc=%08lx mtu=%lu",
1175	       g_fs.path, (int)resume, (int)g_fs.w_rle,
1176	       (unsigned long)off, (unsigned long)crc, (unsigned long)g_fs.mtu);
1177	  queue_ok(COMPANION_FS_WRITE_OPEN, tid, reply, sizeof(reply), true);
1178	}
1179	
1180	static void write_keep_part(void)
1181	{
1182	  if (g_fs.wfd >= 0)
1183	    {
1184	      /* CLOSE/seq 失败时 RAM 里可能还有未刷的 4KiB～256KiB。不 flush
1185	       * 则下次续传只能接到旧 .part，App 会把已发送的尾巴再发一遍；
1186	       * 更糟的是 CRC 按收到的算、盘上没有，关机后再续会 errno 5。 */
1187	      (void)wbuf_flush();
1188	      xfer_write_suspend(g_fs.wfd);
1189	      g_fs.wfd = -1;
1190	    }
1191	
1192	  release_lfs();
1193	}
1194	
1195	static void write_drop_part(void)
1196	{
1197	  if (g_fs.wfd >= 0)
1198	    {
1199	      xfer_write_abort(g_fs.wfd, g_fs.tmp_path);
1200	      g_fs.wfd = -1;
1201	    }
1202	  else if (g_fs.tmp_path[0] != '\0')
1203	    {
1204	      unlink(g_fs.tmp_path);
1205	    }
1206	
1207	  release_lfs();
1208	}
1209	
1210	static void handle_write_close(uint8_t tid, const uint8_t *payload,
1211	                               uint16_t plen)
1212	{
1213	  uint32_t crc;
1214	  int      ret;
1215	  bool     icon = path_is_notif_icon(g_fs.path);
1216	
1217	  /* Flush/seq failures keep FS_WRITE with w_fail set (and often wfd=-1).
1218	   * Report that errno instead of a generic EIO after the session looks idle.
1219	   */
1220	
1221	  if (g_fs.w_fail != 0)
1222	    {
1223	      LOGI("fs write close aborted state=%d wfd=%d fail=%d",
1224	           (int)g_fs.state, g_fs.wfd, g_fs.w_fail);
1225	      if (icon)
1226	        {
1227	          write_drop_part();
1228	        }
1229	      else
1230	        {
1231	          write_keep_part();
1232	        }
1233	
1234	      g_fs.state = FS_IDLE;
1235	      queue_err(COMPANION_FS_WRITE_CLOSE, tid, g_fs.w_fail);
1236	      return;
1237	    }
1238	
1239	  if (g_fs.state != FS_WRITE || g_fs.wfd < 0)
1240	    {
1241	      LOGI("fs write close aborted state=%d wfd=%d fail=%d",
1242	           (int)g_fs.state, g_fs.wfd, g_fs.w_fail);
1243	      queue_err(COMPANION_FS_WRITE_CLOSE, tid, EIO);
1244	      return;
1245	    }
1246	
1247	  if (plen < 4)
1248	    {
1249	      (void)wbuf_flush();
1250	      if (icon)
1251	        {
1252	          write_drop_part();
1253	        }
1254	      else
1255	        {
1256	          xfer_write_suspend(g_fs.wfd);
1257	          g_fs.wfd = -1;
1258	          release_lfs();
1259	        }
1260	
1261	      g_fs.state = FS_IDLE;
1262	      queue_err(COMPANION_FS_WRITE_CLOSE, tid, EINVAL);
1263	      return;
1264	    }
1265	
1266	  crc = get_le32(payload);
1267	  if (g_fs.w_rle && !companion_rle_dec_idle(&g_fs.rle_dec))
1268	    {
1269	      (void)wbuf_flush();
1270	      if (icon)
1271	        {
1272	          write_drop_part();
1273	        }
1274	      else
1275	        {
1276	          xfer_write_suspend(g_fs.wfd);
1277	          g_fs.wfd = -1;
1278	          release_lfs();
1279	        }
1280	
1281	      g_fs.state = FS_IDLE;
1282	      LOGI("fs write close rle truncated (%s)",
1283	           icon ? "dropped .part" : "kept .part");
1284	      queue_err(COMPANION_FS_WRITE_CLOSE, tid, EINVAL);
1285	      return;
1286	    }
1287	
1288	  if (g_fs.w_got != g_fs.w_expected || crc != g_fs.w_crc)
1289	    {
1290	      (void)wbuf_flush();
1291	      if (icon)
1292	        {
1293	          write_drop_part();
1294	        }
1295	      else
1296	        {
1297	          xfer_write_suspend(g_fs.wfd);
1298	          g_fs.wfd = -1;
1299	          release_lfs();
1300	        }
1301	
1302	      g_fs.state = FS_IDLE;
1303	      LOGI("fs write close mismatch got=%lu expect=%lu crc=%08lx/%08lx (%s)",
1304	           (unsigned long)g_fs.w_got, (unsigned long)g_fs.w_expected,
1305	           (unsigned long)g_fs.w_crc, (unsigned long)crc,
1306	           icon ? "dropped .part" : "kept .part");
1307	      queue_err(COMPANION_FS_WRITE_CLOSE, tid, EIO);
1308	      return;
1309	    }
1310	
1311	  if (path_is_ota_fw(g_fs.path))
1312	    {
1313	      ret = wbuf_flush();
1314	      if (ret != 0)
1315	        {
1316	          xfer_write_suspend(g_fs.wfd);
1317	          g_fs.wfd = -1;
1318	          release_lfs();
1319	          g_fs.state = FS_IDLE;
1320	          queue_err(COMPANION_FS_WRITE_CLOSE, tid, ret);
1321	          return;
1322	        }
1323	
1324	      ret = xfer_write_commit(g_fs.wfd, g_fs.tmp_path, g_fs.path);
1325	      g_fs.wfd = -1;
1326	      release_lfs();
1327	      if (ret != 0)
1328	        {
1329	          g_fs.state = FS_IDLE;
1330	          queue_err(COMPANION_FS_WRITE_CLOSE, tid, ret);
1331	          return;
1332	        }
1333	
1334	      g_fs.state = FS_REPLY;
1335	      queue_ok(COMPANION_FS_WRITE_CLOSE, tid, NULL, 0, true);
1336	      LOGI("fs write commit %s %lu bytes",
1337	           g_fs.path, (unsigned long)g_fs.w_expected);
1338	      return;
1339	    }
1340	
1341	  /* GPX/图标等：先 CLOSE OK 让 App 结束，落盘在 notify 之后。
1342	   * 否则 fsync/write 十几秒，手机进度条卡死。 */
1343	  g_fs.commit_pending = true;
1344	  queue_ok(COMPANION_FS_WRITE_CLOSE, tid, NULL, 0, true);
1345	  LOGI("fs write close acked %s %lu bytes (flush deferred wbuf=%lu)",
1346	       g_fs.path, (unsigned long)g_fs.w_expected,
1347	       (unsigned long)g_fs.wbuf_len);
1348	}
