1350	static void handle_simple_path(uint8_t cmd, uint8_t tid,
1351	                               const uint8_t *path, uint16_t plen)
1352	{
1353	  int ret;
1354	
1355	  ret = xfer_resolve((const char *)path, plen, g_fs.path, sizeof(g_fs.path));
1356	  if (ret != 0)
1357	    {
1358	      queue_err(cmd, tid, ret);
1359	      return;
1360	    }
1361	
1362	  hold_lfs();
1363	  if (cmd == COMPANION_FS_DELETE)
1364	    {
1365	      ret = xfer_delete(g_fs.path);
1366	    }
1367	  else
1368	    {
1369	      ret = xfer_mkdir(g_fs.path);
1370	    }
1371	
1372	  release_lfs();
1373	  if (ret != 0)
1374	    {
1375	      queue_err(cmd, tid, ret);
1376	      return;
1377	    }
1378	
1379	  g_fs.state = FS_REPLY;
1380	  queue_ok(cmd, tid, NULL, 0, true);
1381	  LOGI("fs %s %s", cmd == COMPANION_FS_DELETE ? "delete" : "mkdir", g_fs.path);
1382	}
