1384	/** @brief 处理 RENAME。 */
1385	static void handle_rename(uint8_t tid, const uint8_t *payload, uint16_t plen)
1386	{
1387	  char oldp[XFER_PATH_MAX];
1388	  char newp[XFER_PATH_MAX];
1389	  uint8_t old_len;
1390	  int     ret;
1391	
1392	  if (plen < 1)
1393	    {
1394	      queue_err(COMPANION_FS_RENAME, tid, EINVAL);
1395	      return;
1396	    }
1397	
1398	  old_len = payload[0];
1399	  if ((uint16_t)(1 + old_len) > plen)
1400	    {
1401	      queue_err(COMPANION_FS_RENAME, tid, EINVAL);
1402	      return;
1403	    }
1404	
1405	  ret = xfer_resolve((const char *)(payload + 1), old_len,
1406	                     oldp, sizeof(oldp));
1407	  if (ret != 0)
1408	    {
1409	      queue_err(COMPANION_FS_RENAME, tid, ret);
1410	      return;
1411	    }
1412	
1413	  ret = xfer_resolve((const char *)(payload + 1 + old_len),
1414	                     (size_t)(plen - 1 - old_len), newp, sizeof(newp));
1415	  if (ret != 0)
1416	    {
1417	      queue_err(COMPANION_FS_RENAME, tid, ret);
1418	      return;
1419	    }
1420	
1421	  hold_lfs();
1422	  ret = xfer_rename(oldp, newp);
1423	  release_lfs();
1424	  if (ret != 0)
1425	    {
1426	      queue_err(COMPANION_FS_RENAME, tid, ret);
1427	      return;
1428	    }
1429	
1430	  g_fs.state = FS_REPLY;
1431	  queue_ok(COMPANION_FS_RENAME, tid, NULL, 0, true);
1432	  LOGI("fs rename %s -> %s", oldp, newp);
1433	}
