1435	static void dispatch_cmd(const uint8_t *buf, uint16_t len)
1436	{
1437	  uint8_t        cmd;
1438	  uint8_t        tid;
1439	  const uint8_t *payload;
1440	  uint16_t       plen;
1441	
1442	  if (len < COMPANION_FS_CMD_HDR_LEN)
1443	    {
1444	      return;
1445	    }
1446	
1447	  cmd     = buf[0];
1448	  tid     = buf[1];
1449	  payload = buf + COMPANION_FS_CMD_HDR_LEN;
1450	  plen    = (uint16_t)(len - COMPANION_FS_CMD_HDR_LEN);
1451	
1452	  if (myvendor_is_factory())
1453	    {
1454	      static bool logged;
1455	
1456	      if (!logged)
1457	        {
1458	          logged = true;
1459	          LOGI("fs disabled in factory; copy files over USB MTP");
1460	        }
1461	
1462	      queue_err(cmd, tid, EACCES);
1463	      return;
1464	    }
1465	
1466	  if (xfer_usb_busy())
1467	    {
1468	      queue_err(cmd, tid, EBUSY);
1469	      return;
1470	    }
1471	
1472	  /* A new command aborts an in-flight LIST/READ.  WRITE_CLOSE is the
1473	   * exception: it finishes the WRITE session opened earlier.
1474	   */
1475	
1476	  if (g_fs.state != FS_IDLE && g_fs.state != FS_WRITE &&
1477	      cmd != COMPANION_FS_WRITE_CLOSE)
1478	    {
1479	      session_reset(false);
1480	    }
1481	
1482	  /* Each command is its own seq space.  Forgetting this makes STAT/DELETE
1483	   * after LIST start at seq=1; the App then rejects a perfectly good LAST.
1484	   */
1485	
1486	  g_fs.seq = 0;
1487	
1488	  switch (cmd)
1489	    {
1490	      case COMPANION_FS_STATFS:
1491	        handle_statfs(tid);
1492	        break;
1493	
1494	      case COMPANION_FS_LIST:
1495	        handle_list_begin(tid, payload, plen);
1496	        break;
1497	
1498	      case COMPANION_FS_STAT:
1499	        handle_stat(tid, payload, plen);
1500	        break;
1501	
1502	      case COMPANION_FS_READ:
1503	        handle_read_begin(tid, payload, plen);
1504	        break;
1505	
1506	      case COMPANION_FS_WRITE_OPEN:
1507	        handle_write_open(tid, payload, plen);
1508	        break;
1509	
1510	      case COMPANION_FS_WRITE_CLOSE:
1511	        handle_write_close(tid, payload, plen);
1512	        break;
1513	
1514	      case COMPANION_FS_DELETE:
1515	      case COMPANION_FS_MKDIR:
1516	        handle_simple_path(cmd, tid, payload, plen);
1517	        break;
1518	
1519	      case COMPANION_FS_RENAME:
1520	        handle_rename(tid, payload, plen);
1521	        break;
1522	
1523	      default:
1524	        queue_err(cmd, tid, ENOSYS);
1525	        break;
1526	    }
1527	}
1528	
1529	static int rle_write_out(void *ctx, const uint8_t *p, uint16_t n)
1530	{
1531	  int ret;
1532	
1533	  (void)ctx;
1534	  if (n == 0)
1535	    {
1536	      return 0;
1537	    }
1538	
1539	  if (g_fs.w_got > g_fs.w_expected ||
1540	      (uint32_t)n > g_fs.w_expected - g_fs.w_got)
1541	    {
1542	      return EINVAL;
1543	    }
1544	
1545	  ret = wbuf_append(p, n);
1546	  if (ret != 0)
1547	    {
1548	      return ret;
1549	    }
1550	
1551	  g_fs.w_crc = crc32part(p, n, g_fs.w_crc);
1552	  g_fs.w_got += n;
1553	  return 0;
1554	}
1555	
1556	static void dispatch_data(const uint8_t *buf, uint16_t len)
1557	{
1558	  struct companion_fs_hdr hdr;
1559	  const uint8_t          *payload;
1560	  int                     ret;
1561	
1562	  if (len < COMPANION_FS_HDR_LEN)
1563	    {
1564	      return;
1565	    }
1566	
1567	  hdr.cmd    = buf[0];
1568	  hdr.tid    = buf[1];
1569	  hdr.flags  = buf[2];
1570	  hdr.status = buf[3];
1571	  hdr.seq    = get_le16(buf + 4);
1572	  hdr.len    = get_le16(buf + 6);
1573	  if ((uint16_t)(COMPANION_FS_HDR_LEN + hdr.len) > len)
1574	    {
1575	      queue_err(COMPANION_FS_WRITE_DATA, hdr.tid, EINVAL);
1576	      return;
1577	    }
1578	
1579	  payload = buf + COMPANION_FS_HDR_LEN;
1580	  (void)hdr.flags;
1581	  (void)hdr.status;
1582	
1583	  if (myvendor_is_factory())
1584	    {
1585	      queue_err(hdr.cmd, hdr.tid, EACCES);
1586	      return;
1587	    }
1588	
1589	  if (hdr.cmd != COMPANION_FS_WRITE_DATA)
1590	    {
1591	      queue_err(hdr.cmd, hdr.tid, EINVAL);
1592	      return;
1593	    }
1594	
1595	  if (g_fs.state != FS_WRITE || g_fs.wfd < 0)
1596	    {
1597	      return;
1598	    }
1599	
1600	  if (g_fs.w_fail != 0)
1601	    {
1602	      return;
1603	    }
1604	
1605	  if (hdr.seq != g_fs.rx_seq)
1606	    {
1607	      LOGI("fs write seq gap got=%u expect=%u (kept .part)",
1608	           (unsigned)hdr.seq, (unsigned)g_fs.rx_seq);
1609	      g_fs.w_fail = EIO;
1610	      /* 马上 notify，别等 App 把剩余两兆发完再 CLOSE 才知道失败。 */
1611	      queue_err(COMPANION_FS_WRITE_DATA, hdr.tid, EIO);
1612	      return;
1613	    }
1614	
1615	  if (g_fs.w_rle)
1616	    {
1617	      ret = companion_rle_dec_feed(&g_fs.rle_dec, payload, hdr.len,
1618	                                   rle_write_out, NULL);
1619	    }
1620	  else
1621	    {
1622	      ret = wbuf_append(payload, hdr.len);
1623	      if (ret == 0)
1624	        {
1625	          g_fs.w_crc = crc32part(payload, hdr.len, g_fs.w_crc);
1626	          g_fs.w_got += hdr.len;
1627	        }
1628	    }
1629	
1630	  if (ret != 0)
1631	    {
1632	      g_fs.w_fail = ret;
1633	      LOGI("fs write data failed errno=%d seq=%u got=%lu rle=%d (kept .part)",
1634	           g_fs.w_fail, (unsigned)hdr.seq, (unsigned long)g_fs.w_got,
1635	           (int)g_fs.w_rle);
1636	      write_keep_part();
1637	      return;
1638	    }
1639	
1640	  g_fs.rx_seq++;
1641	}
