1643	static void fill_list_page(void)
1644	{
1645	  uint16_t budget = payload_budget();
1646	  bool     last   = false;
1647	  int      n;
1648	
1649	  if (budget == 0)
1650	    {
1651	      return;
1652	    }
1653	
1654	  n = xfer_list_pack(g_fs.path, &g_fs.list_cursor, g_fs.tx, budget, &last);
1655	  if (n < 0)
1656	    {
1657	      release_lfs();
1658	      queue_err(COMPANION_FS_LIST, g_fs.tid, n);
1659	      return;
1660	    }
1661	
1662	  g_fs.tx_len    = (uint16_t)n;
1663	  g_fs.tx_last   = last;
1664	  g_fs.tx_err    = false;
1665	  g_fs.tx_status = 0;
1666	  if (last)
1667	    {
1668	      release_lfs();
1669	      g_fs.state = FS_REPLY;
1670	    }
1671	}
1672	
1673	static void fill_read_page(void)
1674	{
1675	  uint16_t budget = payload_budget();
1676	  uint16_t want;
1677	  uint16_t got = 0;
1678	  int      ret;
1679	
1680	  if (budget == 0)
1681	    {
1682	      return;
1683	    }
1684	
1685	  if (g_fs.r_rle)
1686	    {
1687	      g_fs.tx_len = 0;
1688	      while (g_fs.tx_len < budget)
1689	        {
1690	          uint16_t room;
1691	          uint16_t produced;
1692	          bool     finish;
1693	          uint8_t  tmp[COMPANION_RLE_LOOK];
1694	
1695	          room = companion_rle_enc_room(&g_fs.rle_enc);
1696	          if (room > 0 && g_fs.read_len > 0)
1697	            {
1698	              want = room;
1699	              if (want > g_fs.read_len)
1700	                {
1701	                  want = (uint16_t)g_fs.read_len;
1702	                }
1703	
1704	              got = 0;
1705	              ret = rbuf_get(g_fs.read_off, tmp, want, &got);
1706	              if (ret != 0)
1707	                {
1708	                  release_lfs();
1709	                  queue_err(COMPANION_FS_READ, g_fs.tid, ret);
1710	                  return;
1711	                }
1712	
1713	              ret = companion_rle_enc_push(&g_fs.rle_enc, tmp, got);
1714	              if (ret != 0)
1715	                {
1716	                  release_lfs();
1717	                  queue_err(COMPANION_FS_READ, g_fs.tid, ret);
1718	                  return;
1719	                }
1720	
1721	              g_fs.read_off += got;
1722	              if (g_fs.read_len >= got)
1723	                {
1724	                  g_fs.read_len -= got;
1725	                }
1726	              else
1727	                {
1728	                  g_fs.read_len = 0;
1729	                }
1730	
1731	              if (got < want)
1732	                {
1733	                  g_fs.read_len = 0;
1734	                }
1735	            }
1736	
1737	          finish = (g_fs.read_len == 0);
1738	          produced = companion_rle_enc_pull(&g_fs.rle_enc,
1739	                                            g_fs.tx + g_fs.tx_len,
1740	                                            (uint16_t)(budget - g_fs.tx_len),
1741	                                            finish);
1742	          if (produced == 0)
1743	            {
1744	              break;
1745	            }
1746	
1747	          g_fs.tx_len = (uint16_t)(g_fs.tx_len + produced);
1748	        }
1749	
1750	      g_fs.tx_err    = false;
1751	      g_fs.tx_status = 0;
1752	      g_fs.tx_last   = (g_fs.read_len == 0 &&
1753	                        companion_rle_enc_pending(&g_fs.rle_enc) == 0);
1754	      if (g_fs.tx_last)
1755	        {
1756	          release_lfs();
1757	          g_fs.state = FS_REPLY;
1758	        }
1759	
1760	      return;
1761	    }
1762	
1763	  want = budget;
1764	  if (g_fs.read_len < want)
1765	    {
1766	      want = (uint16_t)g_fs.read_len;
1767	    }
1768	
1769	  ret = rbuf_get(g_fs.read_off, g_fs.tx, want, &got);
1770	  if (ret != 0)
1771	    {
1772	      release_lfs();
1773	      queue_err(COMPANION_FS_READ, g_fs.tid, ret);
1774	      return;
1775	    }
1776	
1777	  g_fs.read_off += got;
1778	  if (g_fs.read_len >= got)
1779	    {
1780	      g_fs.read_len -= got;
1781	    }
1782	  else
1783	    {
1784	      g_fs.read_len = 0;
1785	    }
1786	
1787	  g_fs.tx_len    = got;
1788	  g_fs.tx_err    = false;
1789	  g_fs.tx_status = 0;
1790	  g_fs.tx_last   = (got < want) || (g_fs.read_len == 0);
1791	  if (g_fs.tx_last)
1792	    {
1793	      release_lfs();
1794	      g_fs.state = FS_REPLY;
1795	    }
1796	}
1797	
1798	static bool send_tx(void)
1799	{
1800	  uint8_t      frame[FS_STAGING_MAX];
1801	  bt_status_t  ret;
1802	  uint8_t      flags = 0;
1803	
1804	  if (g_fs.handle == NULL || !g_fs.connected || !g_fs.ccc)
1805	    {
1806	      return false;
1807	    }
1808	
1809	  if (g_fs.tx_last)
1810	    {
1811	      flags |= COMPANION_FS_FLAG_LAST;
1812	    }
1813	
1814	  if (g_fs.tx_err)
1815	    {
1816	      flags |= COMPANION_FS_FLAG_ERR;
1817	    }
1818	
1819	  frame[0] = g_fs.cmd;
1820	  frame[1] = g_fs.tid;
1821	  frame[2] = flags;
1822	  frame[3] = g_fs.tx_status;
1823	  put_le16(frame + 4, g_fs.seq);
1824	  put_le16(frame + 6, g_fs.tx_len);
1825	  if (g_fs.tx_len > 0)
1826	    {
1827	      memcpy(frame + COMPANION_FS_HDR_LEN, g_fs.tx, g_fs.tx_len);
1828	    }
1829	
1830	  ret = bt_gatts_notify(g_fs.handle, &g_fs.peer, g_fs.data_attr,
1831	                        frame, (uint16_t)(COMPANION_FS_HDR_LEN + g_fs.tx_len));
1832	  if (ret != BT_STATUS_SUCCESS)
1833	    {
1834	      LOGE("fs notify failed: %d", (int)ret);
1835	      return false;
1836	    }
1837	
1838	  if (g_fs.inflight < 255)
1839	    {
1840	      g_fs.inflight++;
1841	    }
1842	
1843	  g_fs.send_ms = fs_now_ms();
1844	  g_fs.seq++;
1845	  g_fs.tx_len = 0;
1846	  if (g_fs.tx_last && g_fs.state != FS_WRITE)
1847	    {
1848	      g_fs.state = FS_IDLE;
1849	    }
1850	
1851	  g_fs.tx_last = false;
1852	  g_fs.tx_err  = false;
1853	  return true;
1854	}
