1948	/**
1949	 * @brief 拷贝一次 0xFF15 命令写；真正 I/O 在 companion_fs_pump()。
1950	 */
1951	uint16_t companion_fs_on_cmd(const uint8_t *value, uint16_t length)
1952	{
1953	  if (value == NULL || length == 0)
1954	    {
1955	      return 0;
1956	    }
1957	
1958	  if (length > sizeof(g_fs.cmd_req.buf))
1959	    {
1960	      length = sizeof(g_fs.cmd_req.buf);
1961	    }
1962	
1963	  pthread_mutex_lock(&g_fs.lock);
1964	  memcpy(g_fs.cmd_req.buf, value, length);
1965	  g_fs.cmd_req.len     = length;
1966	  g_fs.cmd_req.pending = true;
1967	  pthread_mutex_unlock(&g_fs.lock);
1968	  companion_fs_kick();
1969	  return length;
1970	}
