1972	/**
1973	 * @brief 拷贝一次 0xFF16 数据写；真正 I/O 在 companion_fs_pump()。
1974	 */
1975	uint16_t companion_fs_on_data(const uint8_t *value, uint16_t length)
1976	{
1977	  uint16_t wr;
1978	  int      waits = 0;
1979	  static unsigned s_drop_log;
1980	
1981	  if (value == NULL || length == 0)
1982	    {
1983	      return 0;
1984	    }
1985	
1986	  if (length > FS_SLOT_MAX)
1987	    {
1988	      length = FS_SLOT_MAX;
1989	    }
1990	
1991	  pthread_mutex_lock(&g_fs.lock);
1992	  if (g_fs.data_q == NULL || g_fs.data_q_cap == 0)
1993	    {
1994	      fs_buffers_init();
1995	    }
1996	
1997	  while (g_fs.data_q != NULL && g_fs.data_q_cap != 0 &&
1998	         g_fs.data_q_n >= g_fs.data_q_cap && waits < FS_ENQ_WAIT_MAX)
1999	    {
2000	      pthread_mutex_unlock(&g_fs.lock);
2001	      companion_fs_kick();
2002	      usleep(FS_ENQ_WAIT_US);
2003	      waits++;
2004	      pthread_mutex_lock(&g_fs.lock);
2005	    }
2006	
2007	  if (g_fs.data_q == NULL || g_fs.data_q_cap == 0 ||
2008	      g_fs.data_q_n >= g_fs.data_q_cap)
2009	    {
2010	      pthread_mutex_unlock(&g_fs.lock);
2011	      if ((s_drop_log++ & 63) == 0)
2012	        {
2013	          LOGE("fs data queue full, drop %u (x%u)",
2014	               (unsigned)length, s_drop_log);
2015	        }
2016	
2017	      return 0;
2018	    }
2019	
2020	  wr = (uint16_t)((g_fs.data_q_rd + g_fs.data_q_n) % g_fs.data_q_cap);
2021	  memcpy(g_fs.data_q[wr].buf, value, length);
2022	  g_fs.data_q[wr].len = length;
2023	  g_fs.data_q_n++;
2024	  pthread_mutex_unlock(&g_fs.lock);
2025	  companion_fs_kick();
2026	  return length;
2027	}
