2076	/**
2077	 * @brief companion 线程上的 FS 工作函数。
2078	 * @return 还有未完成工作则为 true。
2079	 */
2080	bool companion_fs_pump(void)
2081	{
2082	  uint8_t  cmd_buf[FS_STAGING_MAX];
2083	  uint16_t cmd_len = 0;
2084	  uint8_t  data_buf[FS_SLOT_MAX];
2085	  uint16_t data_len = 0;
2086	  bool     abort = false;
2087	  bool     busy;
2088	  int      drained = 0;
2089	
2090	  pthread_mutex_lock(&g_fs.lock);
2091	  if (g_fs.abort_req)
2092	    {
2093	      if (g_fs.commit_pending)
2094	        {
2095	          g_fs.abort_req = false;
2096	        }
2097	      else
2098	        {
2099	          g_fs.abort_req = false;
2100	          abort = true;
2101	          g_fs.data_q_n = 0;
2102	          g_fs.data_q_rd = 0;
2103	        }
2104	    }
2105	
2106	  if (g_fs.cmd_req.pending)
2107	    {
2108	      cmd_len = g_fs.cmd_req.len;
2109	      memcpy(cmd_buf, g_fs.cmd_req.buf, cmd_len);
2110	      g_fs.cmd_req.pending = false;
2111	    }
2112	
2113	  pthread_mutex_unlock(&g_fs.lock);
2114	
2115	  if (abort)
2116	    {
2117	      pthread_mutex_lock(&g_fs.lock);
2118	      session_reset(true);
2119	      pthread_mutex_unlock(&g_fs.lock);
2120	      LOGI("fs abort");
2121	    }
2122	
2123	  /* WRITE_CLOSE lives on the command characteristic.  Drain queued DATA
2124	   * first so the last packets are in the PSRAM cache (and CRC) before we
2125	   * commit.  Other commands still run first so WRITE_OPEN beats leftover
2126	   * DATA from a previous transfer.
2127	   */
2128	
2129	  if (cmd_len > 0 && cmd_buf[0] == COMPANION_FS_WRITE_CLOSE)
2130	    {
2131	      unsigned drained_close = 0;
2132	
2133	      /* 先把环里的 DATA 解到 RAM 算 CRC，不要在应答前写 /mnt/lfs。
2134	       * App 无响应写 1 秒把整文件塞进环，再立刻 CLOSE；若这里落盘，
2135	       * 第一次 lfs_alloc（地图盘很满）会卡数秒，手机进度条和导入列表一起死。 */
2136	      g_fs.disk_hold = true;
2137	      while (true)
2138	        {
2139	          pthread_mutex_lock(&g_fs.lock);
2140	          if (g_fs.data_q_n == 0 || g_fs.data_q == NULL ||
2141	              g_fs.data_q_cap == 0)
2142	            {
2143	              pthread_mutex_unlock(&g_fs.lock);
2144	              break;
2145	            }
2146	
2147	          data_len = g_fs.data_q[g_fs.data_q_rd].len;
2148	          memcpy(data_buf, g_fs.data_q[g_fs.data_q_rd].buf, data_len);
2149	          g_fs.data_q_rd =
2150	            (uint16_t)((g_fs.data_q_rd + 1) % g_fs.data_q_cap);
2151	          g_fs.data_q_n--;
2152	          pthread_mutex_unlock(&g_fs.lock);
2153	          dispatch_data(data_buf, data_len);
2154	          drained_close++;
2155	          if ((drained_close & 31u) == 0u)
2156	            {
2157	              wbuf_yield();
2158	            }
2159	        }
2160	
2161	      g_fs.disk_hold = false;
2162	
2163	      /* CLOSE 应答不要握着 g_fs.lock。落盘在 notify 之后。 */
2164	      dispatch_cmd(cmd_buf, cmd_len);
2165	    }
2166	  else
2167	    {
2168	      if (cmd_len > 0)
2169	        {
2170	          pthread_mutex_lock(&g_fs.lock);
2171	          dispatch_cmd(cmd_buf, cmd_len);
2172	          pthread_mutex_unlock(&g_fs.lock);
2173	        }
2174	
2175	      while (drained < FS_DATA_DRAIN_MAX)
2176	        {
2177	          pthread_mutex_lock(&g_fs.lock);
2178	          if (g_fs.data_q_n == 0 || g_fs.data_q == NULL ||
2179	              g_fs.data_q_cap == 0)
2180	            {
2181	              pthread_mutex_unlock(&g_fs.lock);
2182	              break;
2183	            }
2184	
2185	          data_len = g_fs.data_q[g_fs.data_q_rd].len;
2186	          memcpy(data_buf, g_fs.data_q[g_fs.data_q_rd].buf, data_len);
2187	          g_fs.data_q_rd =
2188	            (uint16_t)((g_fs.data_q_rd + 1) % g_fs.data_q_cap);
2189	          g_fs.data_q_n--;
2190	          pthread_mutex_unlock(&g_fs.lock);
2191	          dispatch_data(data_buf, data_len);
2192	          drained++;
2193	        }
2194	    }
2195	
2196	  pthread_mutex_lock(&g_fs.lock);
2197	
2198	  if (g_fs.inflight > 0 && g_fs.send_ms != 0 &&
2199	      myvendor_mono_elapsed_ms(fs_now_ms(), g_fs.send_ms) >
2200	      FS_CREDIT_TIMEOUT_MS)
2201	    {
2202	      g_fs.inflight = 0;
2203	    }
2204	
2205	  while (g_fs.connected && g_fs.ccc &&
2206	         g_fs.inflight < FS_NOTIFY_INFLIGHT_MAX &&
2207	         (g_fs.send_ms == 0 ||
2208	          myvendor_mono_elapsed_ms(fs_now_ms(), g_fs.send_ms) >=
2209	          FS_NOTIFY_GAP_MS))
2210	    {
2211	      if (g_fs.state == FS_IDLE && g_fs.tx_len == 0 && !g_fs.tx_last &&
2212	          !g_fs.tx_err)
2213	        {
2214	          (void)try_queue_need_locked();
2215	        }
2216	
2217	      if (g_fs.state == FS_LIST && g_fs.tx_len == 0 && !g_fs.tx_err)
2218	        {
2219	          fill_list_page();
2220	        }
2221	      else if (g_fs.state == FS_READ && g_fs.tx_len == 0 && !g_fs.tx_err)
2222	        {
2223	          fill_read_page();
2224	        }
2225	
2226	      if (g_fs.state == FS_REPLY ||
2227	          ((g_fs.state == FS_LIST || g_fs.state == FS_READ ||
2228	            g_fs.state == FS_WRITE) &&
2229	           (g_fs.tx_len > 0 || g_fs.tx_last || g_fs.tx_err)))
2230	        {
2231	          if (!send_tx())
2232	            {
2233	              break;
2234	            }
2235	        }
2236	      else
2237	        {
2238	          break;
2239	        }
2240	    }
2241	
2242	  busy = (g_fs.state != FS_IDLE) || g_fs.cmd_req.pending ||
2243	         (g_fs.data_q_n > 0) || g_fs.commit_pending ||
2244	         (need_any_pending_locked() && g_fs.connected && g_fs.ccc);
2245	  {
2246	    bool do_commit = g_fs.commit_pending;
2247	
2248	    if (do_commit)
2249	      {
2250	        g_fs.commit_pending = false;
2251	      }
2252	
2253	    pthread_mutex_unlock(&g_fs.lock);
2254	    if (do_commit)
2255	      {
2256	        fs_deferred_commit();
2257	      }
2258	  }
2259	  return busy;
2260	}
