2262	/**
2263	 * @brief 请 App 把本地缓存的图标上传到设备的 notif_icons/。
2264	 */
2265	void companion_fs_need_file(const char *name)
2266	{
2267	  uint32_t now;
2268	  int      i;
2269	  int      free_i = -1;
2270	  int      evict_i = -1;
2271	
2272	  if (myvendor_is_factory() || !icon_name_ok(name))
2273	    {
2274	      return;
2275	    }
2276	
2277	  pthread_mutex_lock(&g_fs.lock);
2278	  now = fs_now_ms();
2279	  for (i = 0; i < FS_NEED_Q; i++)
2280	    {
2281	      if (g_fs.need[i].name[0] == '\0')
2282	        {
2283	          if (free_i < 0)
2284	            {
2285	              free_i = i;
2286	            }
2287	
2288	          continue;
2289	        }
2290	
2291	      if (strcmp(g_fs.need[i].name, name) == 0)
2292	        {
2293	          if (g_fs.need[i].pending)
2294	            {
2295	              pthread_mutex_unlock(&g_fs.lock);
2296	              return;
2297	            }
2298	
2299	          if (g_fs.need[i].last_ms != 0 &&
2300	              myvendor_mono_elapsed_ms(now, g_fs.need[i].last_ms) <
2301	              FS_NEED_RETRY_MS)
2302	            {
2303	              pthread_mutex_unlock(&g_fs.lock);
2304	              return;
2305	            }
2306	
2307	          g_fs.need[i].pending = true;
2308	          pthread_mutex_unlock(&g_fs.lock);
2309	          companion_fs_kick();
2310	          return;
2311	        }
2312	
2313	      if (!g_fs.need[i].pending &&
2314	          (evict_i < 0 ||
2315	           g_fs.need[i].last_ms < g_fs.need[evict_i].last_ms))
2316	        {
2317	          evict_i = i;
2318	        }
2319	    }
2320	
2321	  if (free_i < 0)
2322	    {
2323	      free_i = evict_i;
2324	    }
2325	
2326	  if (free_i < 0)
2327	    {
2328	      pthread_mutex_unlock(&g_fs.lock);
2329	      return;
2330	    }
2331	
2332	  strncpy(g_fs.need[free_i].name, name, FS_NEED_NAME_MAX);
2333	  g_fs.need[free_i].name[FS_NEED_NAME_MAX] = '\0';
2334	  g_fs.need[free_i].pending = true;
2335	  pthread_mutex_unlock(&g_fs.lock);
2336	  companion_fs_kick();
2337	}
