370	static void slot_bind_addr(struct sensor_slot *slot, const bt_address_t *addr,
371	                           uint8_t addr_type, int8_t rssi, const char *name,
372	                           bool seen)
373	{
374	  uint32_t now = sensor_now_ms();
375	
376	  slot->addr       = *addr;
377	  slot->addr_type  = addr_type;
378	  slot->rssi       = rssi;
379	  slot->seen_ms    = now;
380	  slot->state_ms   = 0;
381	  slot->retry_ms   = 0;
382	  slot->skip_dwell = seen;
383	  slot->want_link  = true;
384	  slot->adv_seen   = seen;
385	  slot->state      = SENSOR_IDLE;
386	  slot->op_sent    = false;
387	  memset(slot->name, 0, sizeof(slot->name));
388	  if (name != NULL && name[0] != '\0')
389	    {
390	      size_t n = strlen(name);
391	
392	      if (n >= SENSOR_NAME_MAX)
393	        {
394	          n = SENSOR_NAME_MAX - 1u;
395	        }
396	
397	      memcpy(slot->name, name, n);
398	    }
399	}
