402	 * @brief 按已保存地址找槽位（HCI 备份路径；GATTC 句柄可能对不上）。
403	 */
404	static struct sensor_slot *slot_by_addr(const bt_address_t *addr)
405	{
406	  uint8_t i;
407	
408	  if (addr == NULL)
409	    {
410	      return NULL;
411	    }
412	
413	  for (i = 0; i < SENSOR_KIND_COUNT; i++)
414	    {
415	      if (!addr_empty(&g_slots[i].addr) && addr_eq(&g_slots[i].addr, addr))
416	        {
417	          return &g_slots[i];
418	        }
419	    }
420	
421	  return NULL;
422	}
