480	/**
481	 * @brief GATTC 或 HCI 备份确认断链后回收槽位（可重入：已 IDLE 则忽略）。
482	 */
483	static void slot_handle_disconnected(struct sensor_slot *slot)
484	{
485	  char a[BT_ADDR_STR_LENGTH];
486	  bool keep;
487	  bool early;
488	  bool rearm;
489	  uint8_t reason;
490	
491	  if (slot == NULL || slot->state == SENSOR_IDLE)
492	    {
493	      return;
494	    }
495	
496	  bt_addr_ba2str(&slot->addr, a);
497	  keep   = slot_keep_link(slot);
498	  early  = (slot->state == SENSOR_CONNECTING ||
499	            slot->state == SENSOR_DISCOVERING);
500	  rearm  = slot->rearm_adv;
501	  reason = slot->hci_reason;
502	
503	  if (keep)
504	    {
505	      if (early)
506	        {
507	          LOGI("%s connect failed %s, scanning", kind_name(slot->kind), a);
508	        }
509	      else
510	        {
511	          LOGI("%s disconnected %s, scanning to reconnect",
512	               kind_name(slot->kind), a);
513	        }
514	    }
515	  else
516	    {
517	      LOGI("%s disconnected %s", kind_name(slot->kind), a);
518	    }
519	
520	  slot_idle_keep_addr(slot, sensor_now_ms());
521	
522	  if (!keep)
523	    {
524	      uint8_t k = slot->kind;
525	
526	      slot->want_link = false;
527	      memset(&slot->addr, 0, sizeof(slot->addr));
528	      memset(slot->name, 0, sizeof(slot->name));
529	      if (g_pending_bind[k].valid)
530	        {
531	          slot_bind_addr(slot, &g_pending_bind[k].addr,
532	                         g_pending_bind[k].addr_type, 0,
533	                         g_pending_bind[k].name, false);
534	          g_pending_bind[k].valid = false;
535	        }
536	
537	      sensor_ui_publish();
538	      return;
539	    }
540	
541	  if (rearm)
542	    {
543	      slot->adv_seen   = true;
544	      slot->skip_dwell = true;
545	      LOGI("%s already saw advertiser, connect now", kind_name(slot->kind));
546	    }
547	
548	  {
549	    uint32_t cool = SENSOR_RECONNECT_MS;
550	
551	    if (reason == HCI_ERR_CONN_FAIL_TO_ESTAB)
552	      {
553	        cool = SENSOR_RECONNECT_3E_MS;
554	      }
555	    else if (!rearm && (early || sensor_ready_count() >= 1))
556	      {
557	        cool = SENSOR_RECONNECT_BUSY_MS;
558	      }
559	
560	    slot->retry_ms = sensor_now_ms() + cool;
561	  }
562	  sensor_ui_publish();
563	}
