565	/**
566	 * @brief 在 companion 线程发起拆链；成功则进 DISCONNECTING 等回调。
567	 *
568	 * UI 立刻离开「已连接」。回调丢失由健康看门狗重建 GATTC。
569	 */
570	static void slot_begin_disconnect(struct sensor_slot *slot, uint32_t now_ms)
571	{
572	  if (slot == NULL || slot->state == SENSOR_IDLE ||
573	      slot->state == SENSOR_DISCONNECTING)
574	    {
575	      return;
576	    }
577	
578	  slot->state     = SENSOR_DISCONNECTING;
579	  slot->state_ms  = now_ms;
580	  slot->op_sent   = false;
581	  slot->drop_link = false;
582	  LOGI("%s disconnecting", kind_name(slot->kind));
583	  sensor_ui_publish();
584	
585	  if (slot->gatt == NULL ||
586	      bt_gattc_disconnect(slot->gatt) != BT_STATUS_SUCCESS)
587	    {
588	      slot_handle_disconnected(slot);
589	    }
590	}
