592	/**
593	 * @brief 把 SENSOR_FEAT_* 格式化成 HR+BAT（没有则 "-"）。
594	 */
595	static void mask_str(uint16_t mask, char *buf, size_t n)
596	{
597	  size_t off = 0;
598	
599	  buf[0] = '\0';
600	  if (n == 0)
601	    {
602	      return;
603	    }
604	
605	  if ((mask & SENSOR_FEAT_HR) != 0)
606	    {
607	      off += (size_t)snprintf(buf + off, n - off, "%sHR", off ? "+" : "");
608	    }
609	
610	  if ((mask & SENSOR_FEAT_CSC) != 0 && off < n)
611	    {
612	      off += (size_t)snprintf(buf + off, n - off, "%sCSC", off ? "+" : "");
613	    }
614	
615	  if ((mask & SENSOR_FEAT_CPS) != 0 && off < n)
616	    {
617	      off += (size_t)snprintf(buf + off, n - off, "%sCPS", off ? "+" : "");
618	    }
619	
620	  if ((mask & SENSOR_FEAT_BAT) != 0 && off < n)
621	    {
622	      (void)snprintf(buf + off, n - off, "%sBAT", off ? "+" : "");
623	    }
624	
625	  if (buf[0] == '\0')
626	    {
627	      (void)snprintf(buf, n, "-");
628	    }
629	}
