631	/**
632	 * @brief 按 BLE 地址插入或合并扫描行。
633	 * @param result 观察者报告。
634	 * @param svc_mask AD 里的 SENSOR_FEAT_HR / CSC / CPS 位。
635	 * @param name 完整或缩短的本地名（可为空）。
636	 */
637	static void found_upsert(const ble_scan_result_t *result, uint16_t svc_mask,
638	                         const char *name)
639	{
640	  uint8_t i;
641	  uint8_t weakest = 0;
642	
643	  if (result == NULL || svc_mask == 0)
644	    {
645	      return;
646	    }
647	
648	  for (i = 0; i < g_found_n; i++)
649	    {
650	      if (addr_eq(&g_found[i].addr, &result->addr))
651	        {
652	          g_found[i].svc_mask |= svc_mask;
653	          g_found[i].addr_type = result->addr_type;
654	          g_found[i].last_ms   = sensor_now_ms();
655	          if (result->rssi > g_found[i].rssi)
656	            {
657	              g_found[i].rssi = result->rssi;
658	            }
659	
660	          if (name != NULL && name[0] != '\0')
661	            {
662	              memcpy(g_found[i].name, name, SENSOR_NAME_MAX);
663	            }
664	
665	          return;
666	        }
667	
668	      if (g_found[i].rssi < g_found[weakest].rssi)
669	        {
670	          weakest = i;
671	        }
672	    }
673	
674	  if (g_found_n < SENSOR_FOUND_MAX)
675	    {
676	      i = g_found_n++;
677	    }
678	  else if (result->rssi > g_found[weakest].rssi)
679	    {
680	      i = weakest;
681	    }
682	  else
683	    {
684	      return;
685	    }
686	
687	  g_found[i].addr      = result->addr;
688	  g_found[i].addr_type = result->addr_type;
689	  g_found[i].rssi      = result->rssi;
690	  g_found[i].svc_mask  = svc_mask;
691	  g_found[i].last_ms   = sensor_now_ms();
692	  memset(g_found[i].name, 0, sizeof(g_found[i].name));
693	  if (name != NULL && name[0] != '\0')
694	    {
695	      memcpy(g_found[i].name, name, SENSOR_NAME_MAX);
696	    }
697	}
