830	 *
831	 * CSC/CPS 停车会停发测量，但电量 CCC 仍在。不能因此一直开重连观察者
832	 *（日志里会反复 `[scan] observer on`，还和已连的 HR 抢射频，易 0x3e）。
833	 */
834	static bool slot_link_alive(const struct sensor_slot *s, uint32_t now_ms)
835	{
836	  if (s->state != SENSOR_READY)
837	    {
838	      return false;
839	    }
840	
841	  if (s->notify_ms != 0 &&
842	      sensor_age_ms(now_ms, s->notify_ms) < SENSOR_NOTIFY_STALE_MS)
843	    {
844	      return true;
845	    }
846	
847	  if (s->bat_ms != 0 &&
848	      sensor_age_ms(now_ms, s->bat_ms) < SENSOR_NOTIFY_STALE_MS)
849	    {
850	      return true;
851	    }
852	
853	  return false;
854	}
