1015	/**
1016	 * @brief 解析心率测量（0x2A37）；没有能量则保持 NA。
1017	 */
1018	static void parse_hr_meas(struct sensor_slot *slot, const uint8_t *p,
1019	                         uint16_t len, uint32_t now_ms)
1020	{
1021	  uint8_t flags;
1022	  uint16_t off = 1;
1023	  uint16_t bpm;
1024	  uint16_t energy = 0;
1025	  bool energy_ok = false;
1026	  int8_t contact = -1;
1027	
1028	  if (len < 2)
1029	    {
1030	      return;
1031	    }
1032	
1033	  flags = p[0];
1034	  if ((flags & 0x01) != 0)
1035	    {
1036	      if (len < 3)
1037	        {
1038	          return;
1039	        }
1040	
1041	      bpm = (uint16_t)(p[1] | ((uint16_t)p[2] << 8));
1042	      off = 3;
1043	    }
1044	  else
1045	    {
1046	      bpm = p[1];
1047	      off = 2;
1048	    }
1049	
1050	  if ((flags & 0x02) != 0)
1051	    {
1052	      contact = ((flags & 0x04) != 0) ? 1 : 0;
1053	    }
1054	
1055	  if ((flags & 0x08) != 0 && (uint16_t)(off + 2) <= len)
1056	    {
1057	      energy = (uint16_t)(p[off] | ((uint16_t)p[off + 1] << 8));
1058	      energy_ok = true;
1059	    }
1060	
1061	  if (bpm == 0 || bpm > 250)
1062	    {
1063	      return;
1064	    }
1065	
1066	  if (slot != NULL)
1067	    {
1068	      slot->last_bpm     = bpm;
1069	      slot->last_contact = contact;
1070	      slot->last_energy  = energy;
1071	      slot->energy_ok    = energy_ok;
1072	    }
1073	
1074	  companion_bridge_sensor_set_hr(bpm, now_ms);
1075	}
1076	
1077	/**
1078	 * @brief 解析 CSC 测量（0x2A5B）曲柄增量，换成 RPM。
1079	 */
1080	static void parse_csc_meas(struct sensor_slot *slot, const uint8_t *p,
1081	                           uint16_t len, uint32_t now_ms)
1082	{
1083	  uint8_t  flags;
1084	  uint16_t off = 1;
1085	  uint16_t crank_revs;
1086	  uint16_t crank_time;
1087	
1088	  if (len < 1 || slot == NULL)
1089	    {
1090	      return;
1091	    }
1092	
1093	  flags = p[0];
1094	  if ((flags & 0x01) != 0)
1095	    {
1096	      off = (uint16_t)(off + 6);
1097	    }
1098	
1099	  if ((flags & 0x02) == 0)
1100	    {
1101	      return;
1102	    }
1103	
1104	  if ((uint16_t)(off + 4) > len)
1105	    {
1106	      return;
1107	    }
1108	
1109	  crank_revs = (uint16_t)(p[off] | ((uint16_t)p[off + 1] << 8));
1110	  crank_time = (uint16_t)(p[off + 2] | ((uint16_t)p[off + 3] << 8));
1111	
1112	  if (slot->csc_have)
1113	    {
1114	      uint16_t drev  = (uint16_t)(crank_revs - slot->crank_revs);
1115	      uint16_t dtime = (uint16_t)(crank_time - slot->crank_time);
1116	
1117	      if (drev > 0 && dtime > 0)
1118	        {
1119	          uint32_t rpm = ((uint32_t)drev * 1024u * 60u) / dtime;
1120	
1121	          if (rpm > 0 && rpm < 300)
1122	            {
1123	              slot->last_csc_rpm = (uint16_t)rpm;
1124	              slot->meas_idle    = false;
1125	              companion_bridge_sensor_set_cadence((uint16_t)rpm, now_ms);
1126	            }
1127	        }
1128	    }
1129	
1130	  slot->crank_revs = crank_revs;
1131	  slot->crank_time = crank_time;
1132	  slot->csc_have   = true;
1133	}
