1135	/**
1136	 * @brief 解析骑行功率测量（0x2A63）瞬时瓦数。
1137	 */
1138	static void parse_cps_meas(struct sensor_slot *slot, const uint8_t *p,
1139	                           uint16_t len, uint32_t now_ms)
1140	{
1141	  int16_t watts;
1142	
