1144	    {
1145	      return;
1146	    }
1147	
1148	  watts = (int16_t)(p[2] | ((uint16_t)p[3] << 8));
1149	  if (watts < 0)
1150	    {
1151	      watts = 0;
1152	    }
1153	
1154	  if (watts > 3000)
1155	    {
1156	      return;
1157	    }
1158	
1159	  if (slot != NULL)
1160	    {
1161	      slot->last_cps_w = (uint16_t)watts;
1162	      slot->meas_idle  = false;
1163	    }
