1203	/**
1204	 * @brief 按特征 UUID 分发 notify/read 值。
1205	 */
1206	static void apply_meas(struct sensor_slot *slot, uint16_t uuid,
1207	                       const uint8_t *p, uint16_t len, uint32_t now_ms)
1208	{
1209	  if (uuid == UUID_HR_MEAS)
1210	    {
1211	      parse_hr_meas(slot, p, len, now_ms);
1212	    }
1213	  else if (uuid == UUID_CSC_MEAS)
1214	    {
1215	      parse_csc_meas(slot, p, len, now_ms);
1216	    }
1217	  else if (uuid == UUID_CP_MEAS)
1218	    {
1219	      parse_cps_meas(slot, p, len, now_ms);
1220	    }
1221	  else if (uuid == UUID_BAT_LEVEL)
1222	    {
1223	      parse_bat(slot, p, len);
1224	    }
1225	}
