1227	/**
1228	 * @brief 遍历 AD 类型，取 16 位 UUID 和本地名。
1229	 *
1230	 * 连接绝不按名：是否入表由 UUID 掩码决定。
1231	 */
1232	static void walk_ad(const uint8_t *ad, uint8_t ad_len, uint32_t now_ms,
1233	                    uint16_t *svc_mask, char *name, size_t namesz)
1234	{
1235	  uint8_t i = 0;
1236	
1237	  *svc_mask = 0;
1238	  if (namesz > 0)
1239	    {
1240	      name[0] = '\0';
1241	    }
1242	
1243	  while ((uint16_t)i + 1 < ad_len)
1244	    {
1245	      uint8_t elen = ad[i];
1246	      uint8_t type;
1247	      uint8_t dlen;
1248	      const uint8_t *d;
1249	      uint8_t k;
1250	
1251	      if (elen == 0 || (uint16_t)i + 1 + elen > ad_len)
1252	        {
1253	          break;
1254	        }
1255	
1256	      type = ad[i + 1];
1257	      d    = ad + i + 2;
1258	      dlen = (uint8_t)(elen - 1);
1259	      i    = (uint8_t)(i + 1 + elen);
1260	
1261	      if (type == BT_AD_UUID16_SOME || type == BT_AD_UUID16_ALL)
1262	        {
1263	          for (k = 0; (uint16_t)k + 1 < dlen; k = (uint8_t)(k + 2))
1264	            {
1265	              uint16_t u = (uint16_t)(d[k] | ((uint16_t)d[k + 1] << 8));
1266	
1267	              if (u == UUID_HRS)
1268	                {
1269	                  *svc_mask |= SENSOR_FEAT_HR;
1270	                }
1271	              else if (u == UUID_CSCS)
1272	                {
1273	                  *svc_mask |= SENSOR_FEAT_CSC;
1274	                }
1275	              else if (u == UUID_CPS)
1276	                {
1277	                  *svc_mask |= SENSOR_FEAT_CPS;
1278	                }
1279	              else if (u == UUID_BAS)
1280	                {
1281	                  *svc_mask |= SENSOR_FEAT_BAT;
1282	                }
1283	            }
1284	        }
1285	      else if (type == BT_AD_SERVICE_DATA16 && dlen >= 2)
1286	        {
1287	          uint16_t u = (uint16_t)(d[0] | ((uint16_t)d[1] << 8));
1288	
1289	          if (u == UUID_HRS)
1290	            {
1291	              *svc_mask |= SENSOR_FEAT_HR;
1292	              parse_hr_meas(NULL, d + 2, (uint16_t)(dlen - 2), now_ms);
1293	            }
1294	          else if (u == UUID_CSCS)
1295	            {
1296	              *svc_mask |= SENSOR_FEAT_CSC;
1297	              parse_csc_meas(&g_slots[SENSOR_KIND_CSC], d + 2,
1298	                             (uint16_t)(dlen - 2), now_ms);
1299	            }
1300	          else if (u == UUID_CPS)

1300	          else if (u == UUID_CPS)
1301	            {
1302	              *svc_mask |= SENSOR_FEAT_CPS;
1303	              parse_cps_meas(NULL, d + 2, (uint16_t)(dlen - 2), now_ms);
1304	            }
1305	          else if (u == UUID_BAS)
1306	            {
1307	              *svc_mask |= SENSOR_FEAT_BAT;
1308	            }
1309	        }
1310	      else if ((type == BT_AD_NAME_COMPLETE || type == BT_AD_NAME_SHORT) &&
1311	               namesz > 1 && dlen > 0)
1312	        {
1313	          size_t n = dlen < namesz - 1 ? dlen : namesz - 1;
1314	
1315	          memcpy(name, d, n);
1316	          name[n] = '\0';
1317	        }
1318	    }
1319	}
