1426	 *
1427	 * 板卡 SAL keep_db 后第二次发现不会冲掉该 handle。
1428	 */
1429	static void slot_cache_bat_handle(struct sensor_slot *slot)
1430	{
1431	  bt_uuid_t        uuid;
1432	  gatt_attr_desc_t desc;
1433	
1434	  uuid = BT_UUID_DECLARE_16(UUID_BAT_LEVEL);
1435	  memset(&desc, 0, sizeof(desc));
