1437	                                     &uuid, &desc) != BT_STATUS_SUCCESS)
1438	    {
1439	      slot->bat_h      = 0;
1440	      slot->bat_notify = false;
1441	      slot->feat      &= (uint16_t)~SENSOR_FEAT_BAT;
1442	      return;
1443	    }
1444	
1445	  slot->bat_h  = desc.handle;
1446	  slot->feat  |= SENSOR_FEAT_BAT;
1447	  LOGD("%s bat handle 0x%04x%s", kind_name(slot->kind),
1448	       (unsigned)slot->bat_h,
1449	       (desc.properties & GATT_PROP_NOTIFY) ? " (notify)" : " (read)");
