1452	/**
1453	 * @brief UUID 发现完成：先 BAS 缓存电量 handle，再槽位服务，再订测量和电量。
1454	 *
1455	 * 板卡 SAL 第二次发现追加表，BAS 的 0x2A19 仍可查找/订阅。
1456	 */
1457	static void gattc_on_discovered(gattc_handle_t h, gatt_status_t status,
1458	                                bt_uuid_t *uuid, uint16_t start_handle,
1459	                                uint16_t end_handle)
1460	{
1461	  struct sensor_slot *slot = slot_by_gatt(h);
1462	  uint16_t u16;
1463	  char feats[24];
1464	
1465	  if (slot == NULL)
1466	    {
1467	      return;
1468	    }
1469	
1470	  if (status != GATT_STATUS_SUCCESS)
1471	    {
1472	      if (slot->disc_step == 0)
1473	        {
1474	          LOGI("%s battery skip status %d", kind_name(slot->kind),
1475	               (int)status);
1476	          slot->disc_step = 1;
1477	          slot->state     = SENSOR_DISCOVERING;
1478	          slot->op_sent   = false;
1479	          slot->state_ms  = sensor_now_ms();
1480	          return;
1481	        }
1482	
1483	      LOGE("%s discover status %d", kind_name(slot->kind), (int)status);
1484	      slot->drop_link = true;
1485	      return;
1486	    }
1487	
1488	  if (uuid != NULL && uuid->type != 0)
1489	    {
1490	      u16 = uuid16_of(uuid);
1491	      if (u16 == UUID_HRS)
1492	        {
1493	          slot->feat |= SENSOR_FEAT_HR;
1494	        }
1495	      else if (u16 == UUID_CSCS)
1496	        {
1497	          slot->feat |= SENSOR_FEAT_CSC;
1498	        }
1499	      else if (u16 == UUID_CPS)
1500	        {
1501	          slot->feat |= SENSOR_FEAT_CPS;
1502	        }
1503	
1504	      LOGD("%s svc 0x%04x handles %04x-%04x", kind_name(slot->kind),
1505	           (unsigned)u16, (unsigned)start_handle, (unsigned)end_handle);
1506	      return;
1507	    }
1508	
1509	  mask_str(slot->feat, feats, sizeof(feats));
1510	  LOGD("%s discover done feat=%s", kind_name(slot->kind), feats);
1511	
1512	  if (slot->disc_step == 0)
1513	    {
1514	      slot_cache_bat_handle(slot);
1515	      slot->disc_step = 1;
1516	      slot->state     = SENSOR_DISCOVERING;
1517	      slot->op_sent   = false;
1518	      slot->state_ms  = sensor_now_ms();
1519	      LOGD("%s discover 0x%04x", kind_name(slot->kind),
1520	           (unsigned)kind_svc_uuid(slot->kind));
1521	      return;
1522	    }
1523	
1524	  if ((slot->feat & kind_feat_bit(slot->kind)) == 0)
1525	    {
1526	      LOGE("%s discover missing 0x%04x", kind_name(slot->kind),
1527	           (unsigned)kind_svc_uuid(slot->kind));
1528	      slot->drop_link = true;
1529	      return;
1530	    }
1531	
1532	  slot->state    = SENSOR_SUBSCRIBING;
1533	  slot->state_ms = sensor_now_ms();
1534	  slot->op_sent  = false;
1535	  slot->sub_step = 0;
1536	}
