1538	/**
1539	 * @brief CCC 写完；pump 推进 sub_step（测量，然后电量若有 Notify）。
1540	 */
1541	static void gattc_on_subscribed(gattc_handle_t h, gatt_status_t status,
1542	                                uint16_t attr_handle, bool enable)
1543	{
1544	  struct sensor_slot *slot = slot_by_gatt(h);
1545	
1546	  if (slot == NULL)
1547	    {
1548	      return;
1549	    }
1550	
1551	  if (status == GATT_STATUS_SUCCESS && enable)
1552	    {
1553	      LOGD("%s notify on handle 0x%04x", kind_name(slot->kind),
1554	           (unsigned)attr_handle);
1555	      slot->sub_fail = 0;
1556	      if (attr_handle == slot->hr_h || attr_handle == slot->csc_h ||
1557	          attr_handle == slot->cps_h)
1558	        {
1559	          slot->meas_sub_ok = true;
1560	          slot->sub_step    = 1;
1561	        }
1562	      else if (attr_handle == slot->bat_h)
1563	        {
1564	          slot->sub_step = 2;
1565	        }
1566	    }
1567	  else
1568	    {
1569	      LOGE("%s subscribe status %d handle=0x%04x enable=%d",
1570	           kind_name(slot->kind), (int)status, (unsigned)attr_handle,
1571	           (int)enable);
1572	      slot->sub_fail++;
1573	      if (slot->sub_fail >= SENSOR_SUB_RETRY_MAX)
1574	        {
1575	          slot->drop_link = true;
1576	        }
1577	    }
1578	
1579	  slot->op_sent = false;
1580	}
