1628	/**
1629	 * @brief 体感位置（或其它）读完成。停车探活失败则拆链重连。
1630	 */
1631	static void gattc_on_read(gattc_handle_t h, gatt_status_t status,
1632	                          uint16_t attr_handle, uint8_t *value, uint16_t length)
1633	{
1634	  struct sensor_slot *slot = slot_by_gatt(h);
1635	  bool was_probe;
1636	
1637	  if (slot == NULL)
1638	    {
1639	      return;
1640	    }
1641	
1642	  was_probe = slot->probe_sent &&
1643	              (attr_handle == slot->bat_h || attr_handle == slot->csc_h ||
1644	               attr_handle == slot->cps_h || attr_handle == slot->hr_h);
1645	  if (was_probe)
1646	    {
1647	      slot->probe_sent = false;
1648	    }
1649	
1650	  if (status != GATT_STATUS_SUCCESS || value == NULL)
1651	    {
1652	      if (was_probe && slot_keep_link(slot) &&
1653	          (slot->meas_idle || slot->kind == SENSOR_KIND_HR))
1654	        {
1655	          LOGI("%s idle ATT status %d, reconnect",
1656	               kind_name(slot->kind), (int)status);
1657	          slot->drop_link = true;
1658	        }
1659	
1660	      return;
1661	    }
1662	
1663	  if (was_probe && slot->kind == SENSOR_KIND_HR)
1664	    {
1665	      slot->notify_ms = sensor_now_ms();
1666	    }
1667	
1668	  if (attr_handle == slot->bat_h)
1669	    {
1670	      parse_bat(slot, value, length);
1671	    }
1672	  else if (attr_handle == slot->loc_h)
1673	    {
1674	      parse_loc(slot, value, length);
1675	    }
1676	}
