1691	 */
1692	static int slot_gattc_recreate(struct sensor_slot *slot)
1693	{
1694	  bt_status_t ret;
1695	
1696	  if (g_sensor_ins == NULL || slot == NULL)
1697	    {
1698	      return -1;
1699	    }
1700	
1701	  if (slot->gatt != NULL)
1702	    {
1703	      (void)bt_gattc_delete_connect(slot->gatt);
1704	      slot->gatt = NULL;
