1713	      ble_supervisor_report(BLE_SUPERVISOR_FAULT_GATTC, sensor_now_ms());
1714	      return -1;
1715	    }
1716	
1717	  slot->gatt_ok = true;
1718	  g_health_recreate_n++;
1719	  LOGI("%s GATTC recreated", kind_name(slot->kind));
1720	  return 0;
1721	}
