1723	/**
1724	 * @brief 可选的原始 ADV hex 转储（调试）。
1725	 */
1726	static void adv_debug_print(const ble_scan_result_t *result,
1727	                            uint16_t svc_mask, const char *name)
1728	{
1729	  char     addr[BT_ADDR_STR_LENGTH];
1730	  char     hex[ADV_HEX_MAX * 2 + 4];
1731	  char     match[16];
1732	  uint8_t  n;
1733	  uint8_t  i;
1734	  size_t   off = 0;
1735	
1736	  bt_addr_ba2str(&result->addr, addr);
1737	
1738	  match[0] = '\0';
1739	  if ((svc_mask & (1u << SENSOR_KIND_HR)) != 0)
1740	    {
1741	      strcat(match, "HR ");
1742	    }
1743	
1744	  if ((svc_mask & (1u << SENSOR_KIND_CSC)) != 0)
1745	    {
1746	      strcat(match, "CSC ");
1747	    }
1748	
1749	  if ((svc_mask & (1u << SENSOR_KIND_CPS)) != 0)
1750	    {
1751	      strcat(match, "CPS ");
1752	    }
1753	
1754	  if (match[0] == '\0')
1755	    {
1756	      strcpy(match, "-");
1757	    }
1758	
1759	  n = result->length;
1760	  if (n > ADV_HEX_MAX)
1761	    {
1762	      n = ADV_HEX_MAX;
1763	    }
1764	
1765	  for (i = 0; i < n; i++)
1766	    {
1767	      hex[off++] = "0123456789ABCDEF"[(result->adv_data[i] >> 4) & 0x0f];
1768	      hex[off++] = "0123456789ABCDEF"[result->adv_data[i] & 0x0f];
1769	    }
1770	
1771	  if (result->length > ADV_HEX_MAX)
1772	    {
1773	      hex[off++] = '.';
1774	      hex[off++] = '.';
1775	      hex[off++] = '.';
1776	    }
1777	
1778	  hex[off] = '\0';
1779	
1780	  LOGI("[scan] ADV rssi=%d atype=%u evt=%u %s name=%s match=%s hex=%s",
1781	       result->rssi, result->addr_type, result->adv_type, addr,
1782	       (name != NULL && name[0] != '\0') ? name : "-", match,
1783	       off > 0 ? hex : "-");
1784	}
