1786	/**
1787	 * @brief 观察者回调：拷贝 ADV，更新表格 / 重连 seen。
1788	 *
1789	 * 禁止在此回调里连接；GATT 由 pump() 负责。
1790	 */
1791	static void on_scan_result(bt_scanner_t *scanner, ble_scan_result_t *result)
1792	{
1793	  uint16_t svc_mask = 0;
1794	  char     name[SENSOR_NAME_MAX];
1795	  uint8_t  kind;
1796	  uint32_t now;
1797	  struct sensor_slot *slot;
1798	
1799	  if (!g_started || scanner != g_scanner || result == NULL)
1800	    {
1801	      return;
1802	    }
1803	
1804	  now = sensor_now_ms();
1805	  walk_ad(result->adv_data, result->length, now, &svc_mask,
1806	          name, sizeof(name));
1807	
1808	  g_adv_reports++;
1809	  seen_note(&result->addr);
1810	  if (g_adv_debug)
1811	    {
1812	      adv_debug_print(result, svc_mask, name);
1813	    }
1814	
1815	  if (svc_mask != 0 && result->rssi >= SENSOR_RSSI_MIN)
1816	    {
1817	      found_upsert(result, svc_mask, name);
1818	    }
1819	
1820	  /** 已绑定槽位按地址认人，不要求这包 ADV 里带服务 UUID。 */
1821	
1822	  if (result->rssi >= SENSOR_RSSI_MIN)
1823	    {
1824	      for (kind = 0; kind < SENSOR_KIND_COUNT; kind++)
1825	        {
1826	          slot = &g_slots[kind];
1827	          if (!slot->want_link || !addr_eq(&slot->addr, &result->addr))
1828	            {
1829	              continue;
1830	            }
1831	
1832	          slot->rssi      = result->rssi;
1833	          slot->seen_ms   = now;
1834	          slot->addr_type = result->addr_type;
1835	          if (name[0] != '\0')
1836	            {
1837	              memcpy(slot->name, name, sizeof(slot->name));
1838	            }
1839	
1840	          if (slot->state == SENSOR_IDLE)
1841	            {
1842	              slot->adv_seen   = true;
1843	              slot->skip_dwell = true;
1844	            }
1845	          else if ((slot->state == SENSOR_READY ||
1846	                    slot->state == SENSOR_SUBSCRIBING) &&
1847	                   adv_is_connectable(result->adv_type))
1848	            {
1849	              bool alive;
1850	
1851	              alive = slot_link_alive(slot, now);
1852	              if (!alive)
1853	                {
1854	                  slot->adv_live++;
1855	                  if (slot->adv_live >= SENSOR_HEALTH_ADV_HITS)
1856	                    {
1857	                      slot->drop_link = true;
1858	                      slot->rearm_adv = true;
1859	                      g_health_zombie_n++;
1860	                      LOGI("%s advertised while linked (zombie), reconnect",
1861	                           kind_name(kind));
1862	                    }
1863	                }
1864	            }
1865	        }
1866	    }
1867	
1868	  if (result->rssi < SENSOR_RSSI_MIN || svc_mask == 0)
1869	    {
1870	      return;
1871	    }
1872	
1873	  for (kind = 0; kind < SENSOR_KIND_COUNT; kind++)
1874	    {
1875	      if ((svc_mask & (1u << kind)) == 0)
1876	        {
1877	          continue;
1878	        }
1879	
1880	      slot = &g_slots[kind];
1881	
1882	      /** 已绑定地址上面已经处理。不要换成更强的另一台广播设备。 */
1883	
1884	      if (slot->want_link)
1885	        {
1886	          continue;
1887	        }
1888	
1889	      /** 优先已有连接。否则保留信号最强的广播者。 */
1890	
1891	      if (slot->state >= SENSOR_CONNECTING &&
1892	          addr_eq(&slot->addr, &result->addr))
1893	        {
1894	          slot->rssi    = result->rssi;
1895	          slot->seen_ms = now;
1896	          if (name[0] != '\0')
1897	            {
1898	              memcpy(slot->name, name, sizeof(slot->name));
1899	            }
1900	
1901	          continue;
1902	        }
1903	
1904	      if (slot->state >= SENSOR_CONNECTING)
1905	        {
1906	          continue;
1907	        }
1908	
1909	      if (addr_empty(&slot->addr) || result->rssi > slot->rssi ||
1910	          addr_eq(&slot->addr, &result->addr))
1911	        {
1912	          if (!addr_eq(&slot->addr, &result->addr))
1913	            {
1914	              slot->csc_have = false;
1915	              slot->state_ms = now;
1916	            }
1917	
1918	          slot->addr      = result->addr;
1919	          slot->addr_type = result->addr_type;
1920	          slot->rssi      = result->rssi;
1921	          slot->seen_ms   = now;
1922	          if (name[0] != '\0')
1923	            {
1924	              memcpy(slot->name, name, sizeof(slot->name));
1925	            }
1926	        }
1927	    }
1928	}
