2009	/**
2010	 * @brief 启动框架观察者。搜表用 LOW_LATENCY；重连用 BALANCED / LOW_POWER。
2011	 * @param duty @c SCAN_DUTY_DISCOVERY 或 @c SCAN_DUTY_RECONNECT。
2012	 * @return 成功返回 0。
2013	 */
2014	static int sensor_start_scan(uint8_t duty)
2015	{
2016	  ble_scan_settings_t settings;
2017	  uint8_t mode;
2018	
2019	  if (duty == SCAN_DUTY_RECONNECT && sensor_hci_connecting())
2020	    {
2021	      return 0;
2022	    }
2023	
2024	  if (g_scanner != NULL && g_scan_duty == duty)
2025	    {
2026	      return 0;
2027	    }
2028	
2029	  if (g_scanner != NULL)
2030	    {
2031	      sensor_observer_halt();
2032	    }
2033	
2034	  if (g_sensor_ins == NULL)
2035	    {
2036	      LOGE("[scan] no bt instance");
2037	      return -1;
2038	    }
2039	
2040	  if (duty == SCAN_DUTY_DISCOVERY)
2041	    {
2042	      mode = BT_SCAN_MODE_LOW_LATENCY;
2043	    }
2044	  else if (sensor_ready_count() >= 1)
2045	    {
2046	      mode = BT_SCAN_MODE_LOW_POWER;
2047	    }
2048	  else
2049	    {
2050	      mode = BT_SCAN_MODE_BALANCED;
2051	    }
2052	
2053	  memset(&settings, 0, sizeof(settings));
2054	  settings.scan_mode     = mode;
2055	  settings.legacy        = 1;
2056	  settings.scan_type     = BT_LE_SCAN_TYPE_PASSIVE;
2057	  settings.scan_phy      = BT_LE_1M_PHY;
2058	  settings.policy.policy = BT_LE_SCAN_POLICY_ACCEPT_ALL;
2059	
2060	  g_scanner = bt_le_start_scan_settings(g_sensor_ins, &settings, &g_scan_cbs);
2061	  if (g_scanner == NULL)
2062	    {
2063	      LOGE("[scan] bt_le_start_scan_settings failed");
2064	      ble_supervisor_report(BLE_SUPERVISOR_FAULT_SCAN, sensor_now_ms());
2065	      return -1;
2066	    }
2067	
2068	  g_scan_duty = duty;
2069	  LOGD("[scan] observer on (mode=%u, %s)", (unsigned)mode,
2070	       duty == SCAN_DUTY_RECONNECT ? "reconnect" : "discovery");
2071	  return 0;
2072	}
