2084	static bool sensor_pending_connect(void)
2085	{
2086	  uint8_t i;
2087	
2088	  for (i = 0; i < SENSOR_KIND_COUNT; i++)
2089	    {
2090	      /** slot_try_connect() 对 want_link 槽位仍要求先看到该地址的 ADV。
2091	       * skip_dwell 只跳过驻留时间，不能表示“已经可以建链”。断链回到
2092	       * IDLE 时它会被置 true；若在这里据此 hold，手机断开后的每个
2093	       * ADV_WINDOW 都会被永久压住。
2094	       */
2095	      if (g_slots[i].want_link && !addr_empty(&g_slots[i].addr) &&
2096	          g_slots[i].state == SENSOR_IDLE && g_slots[i].adv_seen)
2097	        {
2098	          return true;
2099	        }
2100	    }
2101	
2102	  return false;
2103	}
