2105	/**
2106	 * @brief 只在限时搜表、即将建链或 HCI 建链时停手机广播。
2107	 *
2108	 * 否则踏频停车后的 reconnect observer 会一直 hold，手机扫不到码表。
2109	 */
2110	static void sensor_adv_hold_update(void)
2111	{
2112	  bool discovery = g_want_scan && g_scan_duty == SCAN_DUTY_DISCOVERY;
2113	  bool slot_scan = g_radio_phase == SENSOR_RADIO_ADV_STOP_WAIT ||
2114	                   g_radio_phase == SENSOR_RADIO_SCAN_WINDOW;
2115	  bool want = ((!g_phone_connected && discovery) || slot_scan ||
2116	               sensor_hci_connecting() || sensor_pending_connect());
2117	
2118	  if (want == g_adv_hold_want)
2119	    {
2120	      return;
2121	    }
2122	
2123	  g_adv_hold_want = want;
2124	  if (want)
2125	    {
2126	      g_hold_request_pend = true;
2127	      g_hold_release_pend = false;
2128	      LOGD("hold phone adv (discovery or connecting)");
2129	    }
2130	  else
2131	    {
2132	      g_hold_release_pend = true;
2133	      g_hold_request_pend = false;
2134	      LOGD("resume phone adv");
2135	    }
2136	}
