2153	/**
2154	 * @brief 手机未连接时，给可发现广播和 sensor 重连扫描轮流分配射频。
2155	 *
2156	 * 停广播请求先由 companion 消费，下一拍确认 g_phone_adv_held 后才排队
2157	 * start scan；停 scan 后再释放 hold。板级 SAL 的跨角色 ticket 队列再
2158	 * 保证实际 HCI worker 按 stop-before-start 顺序执行。
2159	 *
2160	 * @return true 表示本拍的重连 observer 已由时间片状态机处理。
2161	 */
2162	static bool sensor_reconnect_radio_pump(uint32_t now_ms)
2163	{
2164	  bool reconnect = sensor_want_reconnect_observer(now_ms);
2165	
2166	  if (!reconnect ||
2167	      (g_want_scan && g_scan_duty == SCAN_DUTY_DISCOVERY))
2168	    {
2169	      if (g_radio_phase != SENSOR_RADIO_IDLE)
2170	        {
2171	          g_radio_phase = SENSOR_RADIO_IDLE;
2172	          g_radio_deadline_ms = 0;
2173	        }
2174	
2175	      return false;
2176	    }
2177	
2178	  /** 手机已连时没有手机 ADV，observer 可连续运行。 */
2179	
2180	  if (g_phone_connected)
2181	    {
2182	      if (g_radio_phase != SENSOR_RADIO_IDLE)
2183	        {
2184	          LOGD("[radio] phone connected, reconnect scan continuous");
2185	          g_radio_phase = SENSOR_RADIO_IDLE;
2186	          g_radio_deadline_ms = 0;
2187	        }
2188	
2189	      return false;
2190	    }
2191	
2192	  g_want_scan = true;
2193	  g_scan_duty = SCAN_DUTY_RECONNECT;
2194	
2195	  switch (g_radio_phase)
2196	    {
2197	      case SENSOR_RADIO_IDLE:
2198	        if (g_scanner != NULL)
2199	          {
2200	            sensor_observer_halt();
2201	          }
2202	
2203	        g_radio_phase = SENSOR_RADIO_ADV_WINDOW;
2204	        g_radio_deadline_ms = now_ms + SENSOR_PHONE_ADV_WINDOW_MS;
2205	        LOGD("[radio] phone ADV window %u ms",
2206	             (unsigned)SENSOR_PHONE_ADV_WINDOW_MS);
2207	        break;
2208	
2209	      case SENSOR_RADIO_ADV_WINDOW:
2210	        if (g_scanner != NULL)
2211	          {
2212	            sensor_observer_halt();
2213	          }
2214	
2215	        if (now_ms >= g_radio_deadline_ms)
2216	          {
2217	            g_radio_phase = SENSOR_RADIO_ADV_STOP_WAIT;
2218	            g_radio_deadline_ms = 0;
2219	            LOGD("[radio] stop phone ADV for reconnect scan");
2220	          }
2221	        break;
2222	
2223	      case SENSOR_RADIO_ADV_STOP_WAIT:
2224	        if (g_phone_adv_held)
2225	          {
2226	            (void)sensor_start_scan(SCAN_DUTY_RECONNECT);
2227	            g_radio_phase = SENSOR_RADIO_SCAN_WINDOW;
2228	            g_radio_deadline_ms = now_ms + SENSOR_RECONNECT_SCAN_MS;
2229	            LOGD("[radio] reconnect scan window %u ms",
2230	                 (unsigned)SENSOR_RECONNECT_SCAN_MS);
2231	          }
2232	        break;
2233	
2234	      case SENSOR_RADIO_SCAN_WINDOW:
2235	        if (now_ms >= g_radio_deadline_ms)
2236	          {
2237	            if (g_scanner != NULL)
2238	              {
2239	                sensor_observer_halt();
2240	              }
2241	
2242	            g_radio_phase = SENSOR_RADIO_ADV_WINDOW;
2243	            g_radio_deadline_ms = now_ms + SENSOR_PHONE_ADV_WINDOW_MS;
2244	            LOGD("[radio] resume phone ADV window %u ms",
2245	                 (unsigned)SENSOR_PHONE_ADV_WINDOW_MS);
2246	          }
2247	        break;
2248	
2249	      default:
2250	        g_radio_phase = SENSOR_RADIO_IDLE;
2251	        g_radio_deadline_ms = 0;
2252	        break;
2253	    }
2254	
2255	  return true;
2256	}
