2259	 * @brief 缓存 UUID 发现得到的特征句柄。
2260	 */
2261	static void slot_store_handle(struct sensor_slot *slot, uint16_t uuid,
2262	                              uint16_t handle)
2263	{
2264	  if (uuid == UUID_HR_MEAS)
2265	    {
2266	      slot->hr_h = handle;
2267	    }
2268	  else if (uuid == UUID_CSC_MEAS)
2269	    {
2270	      slot->csc_h = handle;
2271	    }
2272	  else if (uuid == UUID_CP_MEAS)
2273	    {
2274	      slot->cps_h = handle;
2275	    }
2276	  else if (uuid == UUID_BAT_LEVEL)
2277	    {
2278	      slot->bat_h = handle;
2279	    }
