2282	/**
2283	 * @brief 句柄存在则对一个 UUID 做 CCC 订阅。
2284	 * @return 已发出订阅（等回调）则为 true。
2285	 */
2286	static bool slot_subscribe_uuid(struct sensor_slot *slot, uint16_t u)
2287	{
2288	  bt_uuid_t        uuid;
2289	  gatt_attr_desc_t desc;
2290	  bt_status_t      ret;
2291	
2292	  uuid = BT_UUID_DECLARE_16(u);
2293	  memset(&desc, 0, sizeof(desc));
2294	  ret = bt_gattc_get_attribute_by_uuid(slot->gatt, 0x0001, 0xffff,
2295	                                       &uuid, &desc);
2296	  if (ret != BT_STATUS_SUCCESS)
2297	    {
2298	      return false;
2299	    }
2300	
2301	  slot_store_handle(slot, u, desc.handle);
2302	
2303	  ret = bt_gattc_subscribe(slot->gatt, desc.handle, GATT_CCC_NOTIFY);
2304	  if (ret != BT_STATUS_SUCCESS)
2305	    {
2306	      LOGE("%s subscribe 0x%04x failed: %d", kind_name(slot->kind),
2307	           (unsigned)u, (int)ret);
2308	      return false;
2309	    }
2310	
2311	  slot->op_sent  = true;
2312	  slot->state_ms = sensor_now_ms();
2313	  return true;
2314	}
