2316	/**
2317	 * @brief 若 0x2A19 带 Notify 则订 CCC；否则留下 handle 做周期 Read。
2318	 * @return 已发出订阅则为 true。
2319	 */
2320	static bool slot_try_subscribe_bat(struct sensor_slot *slot)
2321	{
2322	  bt_uuid_t        uuid;
2323	  gatt_attr_desc_t desc;
2324	  bt_status_t      ret;
2325	
2326	  uuid = BT_UUID_DECLARE_16(UUID_BAT_LEVEL);
2327	  memset(&desc, 0, sizeof(desc));
2328	  ret = bt_gattc_get_attribute_by_uuid(slot->gatt, 0x0001, 0xffff,
2329	                                       &uuid, &desc);
2330	  if (ret != BT_STATUS_SUCCESS)
2331	    {
2332	      slot->bat_h      = 0;
2333	      slot->bat_notify = false;
2334	      slot->feat      &= (uint16_t)~SENSOR_FEAT_BAT;
2335	      return false;
2336	    }
2337	
2338	  slot->bat_h  = desc.handle;
2339	  slot->feat  |= SENSOR_FEAT_BAT;
2340	
2341	  if ((desc.properties & GATT_PROP_NOTIFY) == 0)
2342	    {
2343	      slot->bat_notify = false;
2344	      LOGI("%s bat handle 0x%04x (read, no notify)", kind_name(slot->kind),
2345	           (unsigned)slot->bat_h);
2346	      return false;
2347	    }
2348	
2349	  ret = bt_gattc_subscribe(slot->gatt, desc.handle, GATT_CCC_NOTIFY);
2350	  if (ret != BT_STATUS_SUCCESS)
2351	    {
2352	      slot->bat_notify = false;
2353	      LOGI("%s bat notify failed, fallback read 0x%04x",
2354	           kind_name(slot->kind), (unsigned)slot->bat_h);
2355	      return false;
2356	    }
2357	
2358	  slot->bat_notify = true;
2359	  slot->op_sent    = true;
2360	  slot->state_ms   = sensor_now_ms();
2361	  return true;
2362	}
