2364	/**
2365	 * @brief 订阅后可选读取体感位置（没有则 loc=NA）。
2366	 */
2367	static void slot_read_loc(struct sensor_slot *slot)
2368	{
2369	  bt_uuid_t        uuid;
2370	  gatt_attr_desc_t desc;
2371	
2372	  uuid = BT_UUID_DECLARE_16(UUID_BODY_SENSOR_LOC);
2373	  memset(&desc, 0, sizeof(desc));
2374	  if (bt_gattc_get_attribute_by_uuid(slot->gatt, 0x0001, 0xffff,
2375	                                     &uuid, &desc) == BT_STATUS_SUCCESS)
2376	    {
2377	      slot->loc_h = desc.handle;
