2382	/**
2383	 * @brief 订阅测量 CCC，再订电量 Notify（没有则周期 Read），然后读位置。
2384	 *
2385	 * 测量 CCC 失败不得跳过，也不得标 READY（否则 UI 假显示已连接）。
2386	 */
2387	static void slot_subscribe_next(struct sensor_slot *slot)
2388	{
2389	  if (slot->sub_step == 0)
2390	    {
2391	      if (slot_subscribe_uuid(slot, kind_meas_uuid(slot->kind)))
2392	        {
2393	          return;
2394	        }
2395	
2396	      LOGE("%s meas CCC missing", kind_name(slot->kind));
2397	      slot->drop_link = true;
2398	      return;
2399	    }
2400	
2401	  if (slot->sub_step == 1)
2402	    {
2403	      if (slot_try_subscribe_bat(slot))
2404	        {
2405	          return;
2406	        }
2407	
2408	      slot->sub_step = 2;
2409	    }
2410	
2411	  if (!slot->meas_sub_ok)
2412	    {
2413	      LOGE("%s meas CCC not armed", kind_name(slot->kind));
2414	      slot->drop_link = true;
2415	      return;
2416	    }
2417	
2418	  slot_read_loc(slot);
2419	  if (slot->bat_h != 0)
2420	    {
2421	      (void)bt_gattc_read(slot->gatt, slot->bat_h);
2422	    }
2423	
2424	  slot_finish_ready(slot);
2425	}
