2427	/**
2428	 * @brief 停车探活：ATT 失败或超时则拆僵死 ACL。
2429	 *
2430	 * 可连接 ADV 由扫描回调置 drop_link，健康监控统一拆链。
2431	 */
2432	static void slot_idle_link_check(struct sensor_slot *slot, uint32_t now_ms)
2433	{
2434	  uint16_t h;
2435	  bt_status_t ret;
2436	
2437	  if (slot->state != SENSOR_READY || !slot_keep_link(slot))
2438	    {
2439	      return;
2440	    }
2441	
2442	  if (!slot->meas_idle)
2443	    {
2444	      return;
2445	    }
2446	
2447	  if (slot->probe_sent)
2448	    {
2449	      if (sensor_age_ms(now_ms, slot->probe_ms) > SENSOR_PROBE_TIMEOUT_MS)
2450	        {
2451	          slot->probe_sent = false;
2452	          LOGI("%s idle ATT timeout, reconnect", kind_name(slot->kind));
2453	          slot->drop_link = true;
2454	        }
2455	
2456	      return;
2457	    }
2458	
2459	  if (slot->bat_ms != 0 &&
2460	      sensor_age_ms(now_ms, slot->bat_ms) < SENSOR_NOTIFY_STALE_MS)
2461	    {
2462	      return;
2463	    }
2464	
2465	  if (slot->probe_ms != 0 &&
2466	      sensor_age_ms(now_ms, slot->probe_ms) < SENSOR_PROBE_MS)
2467	    {
2468	      return;
2469	    }
2470	
2471	  h = slot->bat_h != 0 ? slot->bat_h :
2472	      (slot->csc_h != 0 ? slot->csc_h :
2473	       (slot->cps_h != 0 ? slot->cps_h : slot->hr_h));
2474	  if (h == 0)
2475	    {
2476	      return;
2477	    }
2478	
2479	  ret = bt_gattc_read(slot->gatt, h);
2480	  slot->probe_ms = now_ms;
2481	  if (ret == BT_STATUS_SUCCESS)
2482	    {
2483	      slot->probe_sent = true;
2484	    }
2485	  else
2486	    {
2487	      LOGI("%s idle ATT probe fail %d, reconnect",
2488	           kind_name(slot->kind), (int)ret);
2489	      slot->drop_link = true;
2490	    }
2491	}
