2493	/**
2494	 * @brief 驻留 / 重连冷却之后，按已保存地址连接该槽位。
2495	 *
2496	 * Central 角色使用 BT_LE_CONN_PARAM_DEFAULT。同时只飞一条 HCI 建链
2497	 *（满载时再建易 0x3e）。冷却 800 ms；已有其它 READY 链路时 1500 ms。
2498	 */
2499	static void slot_try_connect(struct sensor_slot *slot, uint32_t now_ms)
2500	{
2501	  bt_status_t ret;
2502	
2503	  if (!g_allow_connect && !slot->want_link)
2504	    {
2505	      return;
2506	    }
2507	
2508	  if (g_scan_until_ms != 0)
2509	    {
2510	      return;
2511	    }
2512	
2513	  if (addr_empty(&slot->addr) || slot->gatt == NULL)
2514	    {
2515	      return;
2516	    }
2517	
2518	  if (slot->want_link && !slot->adv_seen)
2519	    {
2520	      return;
2521	    }
2522	
2523	  if (slot->retry_ms != 0 && now_ms < slot->retry_ms)
2524	    {
2525	      return;
2526	    }
2527	
2528	  if (sensor_hci_connecting())
2529	    {
2530	      return;
2531	    }
2532	
2533	  if (slot->skip_dwell || slot->want_link)
2534	    {
2535	      slot->skip_dwell = false;
2536	    }
2537	  else
2538	    {
2539	      if (sensor_age_ms(now_ms, slot->seen_ms) > SENSOR_DWELL_MS * 4u)
2540	        {
2541	          return;
2542	        }
2543	
2544	      if (sensor_age_ms(now_ms, slot->seen_ms) < SENSOR_DWELL_MS &&
2545	          slot->state_ms == 0)
2546	        {
2547	          slot->state_ms = slot->seen_ms;
2548	          return;
2549	        }
2550	
2551	      if (slot->state_ms != 0 &&
2552	          sensor_age_ms(now_ms, slot->state_ms) < SENSOR_DWELL_MS)
2553	        {
2554	          return;
2555	        }
2556	    }
2557	
2558	  if (g_allow_connect)
2559	    {
2560	      slot->want_link = true;
2561	    }
2562	
2563	  ret = bt_gattc_connect(slot->gatt, &slot->addr, slot->addr_type);
2564	  if (ret != BT_STATUS_SUCCESS)
2565	    {
2566	      slot->adv_seen = false;
2567	      slot->retry_ms = now_ms + SENSOR_RECONNECT_MS;
2568	      LOGE("%s connect failed: %d, scan again",
2569	           kind_name(slot->kind), (int)ret);
2570	      return;
2571	    }
2572	
2573	  slot->retry_ms = 0;
2574	  slot->state    = SENSOR_CONNECTING;
2575	  slot->state_ms = now_ms;
2576	  {
2577	    char addr[BT_ADDR_STR_LENGTH];
2578	
2579	    bt_addr_ba2str(&slot->addr, addr);
2580	    LOGI("connecting %s %s rssi=%d", kind_name(slot->kind), addr,
2581	         (int)slot->rssi);
2582	  }
2583	}
