2813	static void sensor_health_log(uint32_t now_ms)
2814	{
2815	  uint8_t i;
2816	  bool any = false;
2817	
2818	  if (!g_adv_debug)
2819	    {
2820	      return;
2821	    }
2822	
2823	  if (g_health_log_ms != 0 &&
2824	      sensor_age_ms(now_ms, g_health_log_ms) < SENSOR_HEALTH_LOG_MS)
2825	    {
2826	      return;
2827	    }
2828	
2829	  for (i = 0; i < SENSOR_KIND_COUNT; i++)
2830	    {
2831	      if (g_slots[i].want_link || g_slots[i].state != SENSOR_IDLE)
2832	        {
2833	          any = true;
2834	          break;
2835	        }
2836	    }
2837	
2838	  if (!any)
2839	    {
2840	      return;
2841	    }
2842	
2843	  g_health_log_ms = now_ms;
2844	  for (i = 0; i < SENSOR_KIND_COUNT; i++)
2845	    {
2846	      const struct sensor_slot *s = &g_slots[i];
2847	      uint32_t ntf = 0;
2848	
2849	      if (!s->want_link && s->state == SENSOR_IDLE)
2850	        {
2851	          continue;
2852	        }
2853	
2854	      if (s->notify_ms != 0)
2855	        {
2856	          ntf = sensor_age_ms(now_ms, s->notify_ms);
2857	        }
2858	
2859	      LOGI("health %s %s ntf=%ums bat=%ums idle=%d alive=%d adv=%u want=%d",
2860	           kind_name(i), state_name(s->state), (unsigned)ntf,
2861	           (unsigned)(s->bat_ms != 0 ? sensor_age_ms(now_ms, s->bat_ms) : 0),
2862	           (int)s->meas_idle, (int)slot_link_alive(s, now_ms),
2863	           (unsigned)s->adv_live, (int)s->want_link);
2864	    }
2865	
2866	  LOGI("health stats zombie=%u hci=%u disc_to=%u gattc=%u obs=%d",
2867	       (unsigned)g_health_zombie_n, (unsigned)g_health_hci_n,
2868	       (unsigned)g_health_disc_to_n, (unsigned)g_health_recreate_n,
2869	       (int)(g_scanner != NULL));
2870	}
