2872	/**
2873	 * @brief 健康监控：HCI 备份、僵死 ACL、断链看门狗。
2874	 *
2875	 * 不再对「测量 idle 但电量仍在」的 READY 链路做脉冲扫描：那会让
2876	 * `[scan] observer on` 在心率已连时刷屏，并和建链抢射频（0x3e）。
2877	 */
2878	static void sensor_health_pump(uint32_t now_ms)
2879	{
2880	  uint8_t i;
2881	  struct sensor_slot *slot;
2882	
2883	  for (i = 0; i < SENSOR_KIND_COUNT; i++)
2884	    {
2885	      slot = &g_slots[i];
2886	
2887	      if (slot->hci_gone)
2888	        {
2889	          slot->hci_gone = false;
2890	          if (slot->state != SENSOR_IDLE)
2891	            {
2892	              LOGI("%s HCI disc reason=0x%02x", kind_name(i),
2893	                   (unsigned)slot->hci_reason);
2894	              g_health_hci_n++;
2895	              slot_handle_disconnected(slot);
2896	            }
2897	        }
2898	
2899	      if (slot->drop_link &&
2900	          slot->state > SENSOR_IDLE &&
2901	          slot->state != SENSOR_DISCONNECTING)
2902	        {
2903	          slot_begin_disconnect(slot, now_ms);
2904	        }
2905	
2906	      if (slot->state == SENSOR_DISCONNECTING &&
2907	          sensor_age_ms(now_ms, slot->state_ms) > SENSOR_HEALTH_DISC_MS)
2908	        {
2909	          LOGI("%s disconnect timeout, recreate GATTC", kind_name(i));
2910	          g_health_disc_to_n++;
2911	          (void)slot_gattc_recreate(slot);
2912	          slot_handle_disconnected(slot);
2913	        }
2914	    }
2915	
2916	  sensor_health_log(now_ms);
2917	}
