2919	/**
2920	 * @brief companion 线程泵：超时、UUID 发现、订阅、notify 过期。
2921	 * @param now_ms CLOCK_MONOTONIC 毫秒。
2922	 *
2923	 * 连接后延迟 500 ms 再发现（LE features / 自动 PHY）。HR 测量 Notify
2924	 * 过期 8 s 视为关机并重连。CSC/CPS 停车常停 Notify，只标 idle，保持 GATT。
2925	 * 重连冷却 800 ms（已有其它链路时 1500 ms）。重连扫描用 BALANCED/LOW_POWER。
2926	 * 健康监控先回收 HCI 丢事件 / 僵死 ACL，再跑观察者与状态机。
2927	 */
2928	void ble_sensor_pump(uint32_t now_ms)
2929	{
2930	  uint8_t i;
2931	  struct sensor_slot *slot;
2932	  bool radio_handled;
2933	
2934	  if (!g_started)
2935	    {
2936	      return;
2937	    }
2938	
2939	  if (g_want_scan && g_scan_until_ms != 0 && now_ms >= g_scan_until_ms)
2940	    {
2941	      ble_sensor_scan_stop();
2942	    }
2943	  else if (g_want_scan && g_scan_until_ms != 0 &&
2944	           (g_adv_debug_ms == 0 ||
2945	            sensor_age_ms(now_ms, g_adv_debug_ms) >= ADV_DEBUG_HEARTBEAT_MS))
2946	    {
2947	      uint32_t left = 0;
2948	
2949	      g_adv_debug_ms = now_ms;
2950	      left = (now_ms < g_scan_until_ms) ?
2951	             (g_scan_until_ms - now_ms) / 1000u : 0;
2952	      scan_progress(left, false);
2953	    }
2954	
2955	  sensor_health_pump(now_ms);
2956	  radio_handled = sensor_reconnect_radio_pump(now_ms);
2957	
2958	  if (sensor_hci_connecting())
2959	    {
2960	      if (g_scanner != NULL)
2961	        {
2962	          sensor_observer_halt();
2963	        }
2964	    }
2965	  else if (g_want_scan && g_scan_duty == SCAN_DUTY_DISCOVERY)
2966	    {
2967	      if ((g_phone_connected || g_phone_adv_held) && g_scanner == NULL)
2968	        {
2969	          (void)sensor_start_scan(SCAN_DUTY_DISCOVERY);
2970	        }
2971	    }
2972	  else if (radio_handled)
2973	    {
2974	      /** ADV / reconnect observer 已由 radio-slot 状态机处理。 */
2975	    }
2976	  else if (g_scan_until_ms == 0 && sensor_want_reconnect_observer(now_ms))
2977	    {
2978	      sensor_reconnect_scan();
2979	    }
2980	  else if (g_scan_until_ms == 0 && g_want_scan &&
2981	           g_scan_duty == SCAN_DUTY_RECONNECT &&
2982	           !sensor_want_reconnect_observer(now_ms))
2983	    {
2984	      sensor_observer_stop();
2985	    }
2986	  else if (g_want_scan && g_scanner == NULL)
2987	    {
2988	      (void)sensor_start_scan(g_scan_duty);
2989	    }
2990	
2991	  for (i = 0; i < SENSOR_KIND_COUNT; i++)
2992	    {
2993	      slot = &g_slots[i];
2994	      if (!slot->gatt_ok)
2995	        {
2996	          continue;
2997	        }
2998	
2999	      switch (slot->state)
3000	        {
3001	          case SENSOR_IDLE:
3002	            if (slot_keep_link(slot) && slot->adv_seen &&
3003	                !sensor_hci_connecting() &&
3004	                (g_scanner != NULL || g_want_scan))
3005	              {
3006	                sensor_observer_stop();
3007	                LOGI("%s saw advertiser, connecting",
3008	                     kind_name(slot->kind));
3009	              }
3010	
3011	            slot_try_connect(slot, now_ms);
3012	            break;
3013	
3014	          case SENSOR_CONNECTING:
3015	            if (sensor_age_ms(now_ms, slot->state_ms) > SENSOR_CONNECT_MS)
3016	              {
3017	                LOGE("%s connect timeout", kind_name(slot->kind));
3018	                slot_begin_disconnect(slot, now_ms);
3019	              }
3020	            break;
3021	
3022	          case SENSOR_DISCOVERING:
3023	            if (!slot->op_sent)
3024	              {
3025	                bt_uuid_t uuid;
3026	                uint16_t su;
3027	
3028	                /** 等待，避免 ATT 和 LE Read Remote Features 打架。
3029	                 *  先 0x180F 缓存电量，再槽位 UUID（SAL keep_db 追加表）。
3030	                 */
3031	
3032	                if (slot->disc_step == 0 &&
3033	                    sensor_age_ms(now_ms, slot->state_ms) <
3034	                    SENSOR_DISCOVER_DELAY_MS)
3035	                  {
3036	                    break;
3037	                  }
3038	
3039	                su = (slot->disc_step == 0) ?
3040	                     UUID_BAS : kind_svc_uuid(slot->kind);
3041	                uuid = BT_UUID_DECLARE_16(su);
3042	                if (bt_gattc_discover_service(slot->gatt, &uuid) !=
3043	                    BT_STATUS_SUCCESS)
3044	                  {
3045	                    if (slot->disc_step == 0)
3046	                      {
3047	                        LOGI("%s battery discover start failed",
3048	                             kind_name(slot->kind));
3049	                        slot->disc_step = 1;
3050	                        slot->op_sent   = false;
3051	                        slot->state_ms  = now_ms;
3052	                        break;
3053	                      }
3054	
3055	                    LOGE("%s discover start failed", kind_name(slot->kind));
3056	                    slot_begin_disconnect(slot, now_ms);
3057	                  }
3058	                else
3059	                  {
3060	                    slot->op_sent  = true;
3061	                    slot->state_ms = now_ms;
3062	                  }
3063	              }
3064	            else if (sensor_age_ms(now_ms, slot->state_ms) >
3065	                     SENSOR_CONNECT_MS)
3066	              {
3067	                if (slot->disc_step == 0)
3068	                  {
3069	                    LOGI("%s battery discover timeout",
3070	                         kind_name(slot->kind));
3071	                    slot->disc_step = 1;
3072	                    slot->op_sent   = false;
3073	                    slot->state_ms  = now_ms;
3074	                    break;
3075	                  }
3076	
3077	                LOGE("%s discover timeout", kind_name(slot->kind));
3078	                slot_begin_disconnect(slot, now_ms);
3079	              }
3080	            break;
3081	
3082	          case SENSOR_SUBSCRIBING:
3083	            if (!slot->op_sent)
3084	              {
3085	                slot_subscribe_next(slot);
3086	              }
3087	            else if (sensor_age_ms(now_ms, slot->state_ms) >
3088	                     SENSOR_CONNECT_MS)
3089	              {
3090	                LOGE("%s subscribe timeout", kind_name(slot->kind));
3091	                slot_begin_disconnect(slot, now_ms);
3092	              }
3093	            break;
3094	
3095	          case SENSOR_READY:
3096	            if (slot->poll_ms == 0 ||
3097	                sensor_age_ms(now_ms, slot->poll_ms) >= SENSOR_POLL_MS)
3098	              {
3099	                slot->poll_ms = now_ms;
3100	                if (slot->bat_h != 0 && !slot->bat_notify)
3101	                  {
3102	                    (void)bt_gattc_read(slot->gatt, slot->bat_h);
3103	                  }
3104	              }
3105	
3106	            {
3107	              uint32_t ntf_ref = slot->notify_ms != 0 ?
3108	                                 slot->notify_ms : slot->poll_ms;
3109	
3110	              if (slot_keep_link(slot) && ntf_ref != 0 &&
3111	                  sensor_age_ms(now_ms, ntf_ref) > SENSOR_NOTIFY_STALE_MS)
3112	                {
3113	                  if (slot->kind == SENSOR_KIND_HR)
3114	                    {
3115	                      uint16_t h;
3116	
3117	                      h = slot->bat_h != 0 ? slot->bat_h : slot->hr_h;
3118	                      if (slot->probe_sent)
3119	                        {
3120	                          if (sensor_age_ms(now_ms, slot->probe_ms) >
3121	                              SENSOR_PROBE_TIMEOUT_MS)
3122	                            {
3123	                              LOGI("%s notify stale, reconnect",
3124	                                   kind_name(slot->kind));
3125	                              slot_begin_disconnect(slot, now_ms);
3126	                            }
3127	                        }
3128	                      else if (h != 0 &&
3129	                               bt_gattc_read(slot->gatt, h) ==
3130	                               BT_STATUS_SUCCESS)
3131	                        {
3132	                          slot->probe_sent = true;
3133	                          slot->probe_ms   = now_ms;
3134	                          LOGI("%s notify stale, ATT probe",
3135	                               kind_name(slot->kind));
3136	                        }
3137	                      else
3138	                        {
3139	                          LOGI("%s notify stale, reconnect",
3140	                               kind_name(slot->kind));
3141	                          slot_begin_disconnect(slot, now_ms);
3142	                        }
3143	                    }
3144	                  else
3145	                    {
3146	                      slot->meas_idle = true;
3147	                    }
3148	                }
3149	            }
3150	
3151	            slot_idle_link_check(slot, now_ms);
3152	            break;
3153	
3154	          case SENSOR_DISCONNECTING:
3155	            break;
3156	
3157	          default:
3158	            break;
3159	        }
3160	
3161	      if (slot->drop_link &&
3162	          slot->state > SENSOR_IDLE &&
3163	          slot->state != SENSOR_DISCONNECTING)
3164	        {
3165	          slot_begin_disconnect(slot, now_ms);
3166	        }
3167	    }
3168	
3169	  {
3170	    bool any = false;
3171	
3172	    for (i = 0; i < SENSOR_KIND_COUNT; i++)
3173	      {
3174	        if (slot_linked(&g_slots[i]))
3175	          {
3176	            any = true;
3177	            break;
3178	          }
3179	      }
3180	
3181	    if (g_adv_debug && any &&
3182	        (g_linked_print_ms == 0 ||
3183	         sensor_age_ms(now_ms, g_linked_print_ms) >= SENSOR_POLL_MS))
3184	      {
3185	        g_linked_print_ms = now_ms;
3186	        print_linked_table();
3187	      }
3188	  }
3189	
3190	  sensor_ui_publish();
3191	  sensor_adv_hold_update();
3192	}
