3208	/**
3209	 * @brief 按 BLE 地址把槽位绑到扫描表第 @p idx 行（绝不按名）。
3210	 * @param idx 表格 1-based 下标。
3211	 * @return 成功返回 0；下标越界返回 -1。
3212	 */
3213	int ble_sensor_connect_index(uint8_t idx)
3214	{
3215	  struct sensor_found *found;
3216	  struct sensor_slot *slot;
3217	  uint8_t kind;
3218	  uint32_t now;
3219	  char addr[BT_ADDR_STR_LENGTH];
3220	  char kinds[16];
3221	  bool bound = false;
3222	
3223	  if (idx == 0 || idx > g_found_n)
3224	    {
3225	      LOGE("connect idx=%u invalid (table has %u, run test sensor scan)",
3226	           (unsigned)idx, (unsigned)g_found_n);
3227	      return -1;
3228	    }
3229	
3230	  found = &g_found[idx - 1];
3231	  now = sensor_now_ms();
3232	
3233	  g_want_scan          = false;
3234	  g_scan_until_ms      = 0;
3235	  if (g_scanner != NULL)
3236	    {
3237	      sensor_observer_halt();
3238	    }
3239	
3240	  /** 只清未绑定的扫描候选，避免按 idx 连接时把其它类型最强设备也连上。
3241	   *  已 want_link 的槽位（含 IDLE 等重连）一律保留。
3242	   */
3243	
3244	  for (kind = 0; kind < SENSOR_KIND_COUNT; kind++)
3245	    {
3246	      if (g_slots[kind].state < SENSOR_CONNECTING &&
3247	          !g_slots[kind].want_link)
3248	        {
3249	          g_slots[kind].skip_dwell = false;
3250	          g_slots[kind].retry_ms   = 0;
3251	          memset(&g_slots[kind].addr, 0, sizeof(g_slots[kind].addr));
3252	        }
3253	    }
3254	
3255	  g_allow_connect = true;
3256	  sensor_ensure_gattc();
3257	
3258	  mask_str(found->svc_mask, kinds, sizeof(kinds));
3259	  bt_addr_ba2str(&found->addr, addr);
3260	  LOGI("connect idx=%u %s %s rssi=%d",
3261	       (unsigned)idx, kinds, addr, (int)found->rssi);
3262	
3263	  /** 一个地址一个 GATTC：按 HR → CSC → CPS 取第一种匹配。 */
3264	
3265	  for (kind = 0; kind < SENSOR_KIND_COUNT; kind++)
3266	    {
3267	      if ((found->svc_mask & (1u << kind)) == 0)
3268	        {
3269	          continue;
3270	        }
3271	
3272	      slot = &g_slots[kind];
3273	      if (slot->state >= SENSOR_CONNECTING)
3274	        {
3275	          if (addr_eq(&slot->addr, &found->addr))
3276	            {
3277	              slot->want_link  = true;
3278	              slot->skip_dwell = true;
3279	              slot->retry_ms   = 0;
3280	              bound = true;
3281	              if (slot->state == SENSOR_READY)
3282	                {
3283	                  LOGI("%s already linked", kind_name(kind));
3284	                }
3285	              else
3286	                {
3287	                  LOGI("%s already linking, keep", kind_name(kind));
3288	                }
3289	
3290	              break;
3291	            }
3292	
3293	          LOGE("%s already linking another device", kind_name(kind));
3294	          continue;
3295	        }
3296	
3297	      slot->addr       = found->addr;
3298	      slot->addr_type  = found->addr_type;
3299	      slot->rssi       = found->rssi;
3300	      slot->seen_ms    = now;
3301	      slot->state_ms   = 0;
3302	      slot->retry_ms   = 0;
3303	      slot->skip_dwell = true;
3304	      slot->want_link  = true;
3305	      slot->adv_seen   = true;
3306	      slot->state      = SENSOR_IDLE;
3307	      slot->op_sent    = false;
3308	      memset(slot->name, 0, sizeof(slot->name));
3309	      if (found->name[0] != '\0')
3310	        {
3311	          memcpy(slot->name, found->name, SENSOR_NAME_MAX);
3312	        }
3313	
3314	      bound = true;
3315	      break;
3316	    }
3317	
3318	  if (!bound)
3319	    {
3320	      LOGE("connect idx=%u no free slot", (unsigned)idx);
3321	      return -1;
3322	    }
3323	
3324	  sensor_ui_publish();
3325	  sensor_adv_hold_update();
3326	  return 0;
3327	}
