3329	static void slot_drop_want(uint8_t kind, const bt_address_t *addr)
3330	{
3331	  if (kind >= SENSOR_KIND_COUNT || addr == NULL || addr_empty(addr))
3332	    {
3333	      return;
3334	    }
3335	
3336	  g_pending_bind[kind].valid = false;
3337	  if (addr_eq(&g_slots[kind].addr, addr))
3338	    {
3339	      g_slots[kind].want_link = false;
3340	    }
3341	}
