3368	/**
3369	 * @brief 按已保存地址绑定槽位并回连。
3370	 */
3371	int ble_sensor_connect_addr(const uint8_t *mac, uint8_t addr_type, uint8_t kind,
3372	                            const char *name, const uint8_t *drop_mac,
3373	                            uint8_t drop_kind)
3374	{
3375	  bt_address_t addr;
3376	  bt_address_t drop;
3377	  struct sensor_slot *slot;
3378	  uint8_t i;
3379	  bool seen = false;
3380	  int8_t rssi = 0;
3381	  uint32_t now;
3382	
3383	  if (kind >= SENSOR_KIND_COUNT || mac == NULL)
3384	    {
3385	      return -1;
3386	    }
3387	
3388	  memcpy(addr.addr, mac, BT_ADDR_LENGTH);
3389	  if (addr_empty(&addr))
3390	    {
3391	      return -1;
3392	    }
3393	
3394	  if (!g_started)
3395	    {
3396	      return -1;
3397	    }
3398	
3399	  memset(&drop, 0, sizeof(drop));
3400	  if (drop_mac != NULL)
3401	    {
3402	      memcpy(drop.addr, drop_mac, BT_ADDR_LENGTH);
3403	    }
3404	
3405	  if (!addr_empty(&drop) && (drop_kind != kind || !addr_eq(&drop, &addr)))
3406	    {
3407	      slot_drop_want(drop_kind, &drop);
3408	    }
3409	
3410	  now = sensor_now_ms();
3411	  g_want_scan     = false;
3412	  g_scan_until_ms = 0;
3413	  if (g_scanner != NULL)
3414	    {
3415	      sensor_observer_halt();
3416	    }
3417	
3418	  sensor_ensure_gattc();
3419	  slot = &g_slots[kind];
3420	
3421	  for (i = 0; i < g_found_n; i++)
3422	    {
3423	      if (addr_eq(&g_found[i].addr, &addr))
3424	        {
3425	          seen = true;
3426	          rssi = g_found[i].rssi;
3427	          addr_type = g_found[i].addr_type;
3428	          if ((name == NULL || name[0] == '\0') && g_found[i].name[0] != '\0')
3429	            {
3430	              name = g_found[i].name;
3431	            }
3432	
3433	          break;
3434	        }
3435	    }
3436	
3437	  if (slot->state >= SENSOR_CONNECTING)
3438	    {
3439	      if (addr_eq(&slot->addr, &addr))
3440	        {
3441	          slot->want_link  = true;
3442	          slot->skip_dwell = true;
3443	          g_pending_bind[kind].valid = false;
3444	          LOGI("%s keep %s", kind_name(kind),
3445	               slot->state == SENSOR_READY ? "linked" : "linking");
3446	          sensor_ui_publish();
3447	          sensor_adv_hold_update();
3448	          return 0;
3449	        }
3450	
3451	      memset(&g_pending_bind[kind], 0, sizeof(g_pending_bind[kind]));
3452	      g_pending_bind[kind].valid = true;
3453	      g_pending_bind[kind].addr = addr;
3454	      g_pending_bind[kind].addr_type = addr_type;
3455	      if (name != NULL && name[0] != '\0')
3456	        {
3457	          size_t n = strlen(name);
3458	
3459	          if (n >= SENSOR_NAME_MAX)
3460	            {
3461	              n = SENSOR_NAME_MAX - 1u;
3462	            }
3463	
3464	          memcpy(g_pending_bind[kind].name, name, n);
3465	        }
3466	
3467	      slot->want_link = false;
3468	      slot_begin_disconnect(slot, now);
3469	      LOGI("%s switch to saved addr after disconnect", kind_name(kind));
3470	      sensor_adv_hold_update();
3471	      return 0;
3472	    }
3473	
3474	  g_pending_bind[kind].valid = false;
3475	  slot_bind_addr(slot, &addr, addr_type, rssi, name, seen);
3476	  {
3477	    char a[BT_ADDR_STR_LENGTH];
3478	
3479	    bt_addr_ba2str(&addr, a);
3480	    LOGI("connect saved %s %s", kind_name(kind), a);
3481	  }
3482	
3483	  sensor_ui_publish();
3484	  sensor_adv_hold_update();
3485	  return 0;
3486	}
