/** @brief 目录项是否应对 BLE 隐藏。 */
bool xfer_entry_skipped(const char *name)
{
  size_t n;

  if (name == NULL || name[0] == '\0' || name[0] == '.')
    {
      return true;
    }

  n = strlen(name);
  if (n >= 5 && memcmp(name + n - 5, ".part", 5) == 0)
    {
      return true;
    }

  return false;
}

