214	static int wait_hci_device(int timeout_secs)
215	{
216	  int i;
217	
218	  for (i = 0; i < timeout_secs * 10; i++)
219	    {
220	      if (access(HCI_DEV_PATH, F_OK) == 0)
221	        {
222	          LOGI("HCI device %s OK", HCI_DEV_PATH);
223	          return 0;
224	        }
225	
226	      usleep(100 * 1000);
227	    }
228	
229	  LOGE("%s missing — enable CONFIG_UART_BTH4 and rebuild", HCI_DEV_PATH);
230	  return -ENOENT;
231	}
232	
233	static int wait_adapter_ready(int timeout_secs)
234	{
235	  int i;
236	  bt_adapter_state_t last = BT_ADAPTER_STATE_OFF;
237	
238	  for (i = 0; i < timeout_secs * 10; i++)
239	    {
240	      bt_adapter_state_t state = bt_adapter_get_state(g_ins);
241	
242	      if (state != last)
243	        {
244	          LOGI("adapter state -> %d", (int)state);
245	          last = state;
246	        }
247	
248	      if (state == BT_ADAPTER_STATE_ON)
249	        {
250	          return 0;
251	        }
252	
253	      usleep(100 * 1000);
254	    }
255	
256	  LOGE("adapter not ready, state=%d (expect 4=ON)", (int)bt_adapter_get_state(g_ins));
257	  return -ETIMEDOUT;
258	}
