260	static int ble_start_peripheral(void)
261	{
262	  ble_adv_params_t params;
263	  bt_status_t ret;
264	  char addr_str[BT_ADDR_STR_LENGTH];
265	  bt_address_t le_addr;
266	  ble_addr_type_t le_addr_type;
267	
268	  if (wait_hci_device(10) != 0)
269	    {
270	      return -1;
271	    }
272	
273	  ret = bt_adapter_enable(g_ins);
274	  LOGI("bt_adapter_enable -> %d", (int)ret);
275	  if (ret != BT_STATUS_SUCCESS && ret != BT_STATUS_DONE)
276	    {
277	      LOGE("bt_adapter_enable failed: %d", (int)ret);
278	      return -1;
279	    }
280	
281	  if (wait_adapter_ready(ADAPTER_WAIT_SECS) != 0)
282	    {
283	      return -1;
284	    }
285	
286	  bt_device_set_bondable_le(g_ins, false);
287	
288	  ret = bt_gatts_register_service(g_ins, &g_gatts_handle, (gatts_callbacks_t *)&g_gatts_cbs);
289	  if (ret != BT_STATUS_SUCCESS || g_gatts_handle == NULL)
290	    {
291	      LOGE("bt_gatts_register_service failed: %d", (int)ret);
292	      return -1;
293	    }
294	
295	  ret = bt_gatts_add_attr_table(g_gatts_handle, &g_iot_service_db);
296	  if (ret != BT_STATUS_SUCCESS)
297	    {
298	      LOGE("bt_gatts_add_attr_table failed: %d", (int)ret);
299	      return -1;
300	    }
301	
302	  memset(&params, 0, sizeof(params));
303	  params.adv_type = BT_LE_LEGACY_ADV_IND;
304	  params.peer_addr_type = BT_LE_ADDR_TYPE_PUBLIC;
305	  params.own_addr_type = BT_LE_ADDR_TYPE_PUBLIC;
306	  params.interval = 320;
307	  params.tx_power = 0;
308	  params.channel_map = BT_LE_ADV_CHANNEL_DEFAULT;
309	  params.filter_policy = BT_LE_ADV_FILTER_WHITE_LIST_FOR_NONE;
310	
311	  g_adv_handle = bt_le_start_advertising(g_ins, &params,
312	                                         g_adv_data, sizeof(g_adv_data),
313	                                         g_scan_rsp, sizeof(g_scan_rsp),
314	                                         (advertiser_callback_t *)&g_adv_cbs);
315	  if (g_adv_handle == NULL)
316	    {
317	      LOGE("bt_le_start_advertising failed");
318	      return -1;
319	    }
320	
321	  if (bt_adapter_get_le_address(g_ins, &le_addr, &le_addr_type) == BT_STATUS_SUCCESS)
322	    {
323	      bt_addr_ba2str(&le_addr, addr_str);
324	      LOGI("LE address: %s", addr_str);
325	    }
326	
327	  LOGI("ready — scan for \"Vela-BT\" (nRF Connect)");
328	  LOGI("  service 0xFF00, read 0xFF05, write 0xFF02");
329	  return 0;
330	}
331	
332	static void ble_cleanup(void)
333	{
334	  if (g_adv_handle != NULL && g_ins != NULL)
335	    {
336	      bt_le_stop_advertising(g_ins, g_adv_handle);
337	      g_adv_handle = NULL;
338	    }
339	
340	  if (g_gatts_handle != NULL)
341	    {
342	      bt_gatts_remove_attr_table(g_gatts_handle, IOT_SERVICE_ID);
343	      bt_gatts_unregister_service(g_gatts_handle);
344	      g_gatts_handle = NULL;
345	    }
346	
347	  if (g_ins != NULL)
348	    {
349	      bt_adapter_disable(g_ins);
350	    }
351	
352	  if (g_adapter_cookie != NULL && g_ins != NULL)
353	    {
354	      bt_adapter_unregister_callback(g_ins, g_adapter_cookie);
355	      g_adapter_cookie = NULL;
356	    }
357	
358	  if (g_ins != NULL)
359	    {
360	      bluetooth_delete_instance(g_ins);
361	      g_ins = NULL;
362	    }
363	}
364	
365	static void signal_handler(int signo)
366	{
367	  (void)signo;
368	  g_running = false;
369	}
370	
371	int main(int argc, FAR char *argv[])
372	{
373	  (void)argc;
374	  (void)argv;
375	
376	  signal(SIGINT, signal_handler);
377	  signal(SIGTERM, signal_handler);
378	
379	  memcpy(g_rw_char_value, g_read_char_value, sizeof(g_read_char_value));
380	  g_rw_char_len = sizeof(g_read_char_value);
381	
382	  g_ins = bluetooth_create_instance();
383	  if (g_ins == NULL)
384	    {
385	      LOGE("bluetooth_create_instance failed");
386	      return EXIT_FAILURE;
387	    }
388	
389	  g_adapter_cookie = bt_adapter_register_callback(g_ins, &g_adapter_cbs);
390	  if (g_adapter_cookie == NULL)
391	    {
392	      LOGE("bt_adapter_register_callback failed");
393	      ble_cleanup();
394	      return EXIT_FAILURE;
395	    }
396	
397	  if (ble_start_peripheral() != 0)
398	    {
399	      ble_cleanup();
400	      return EXIT_FAILURE;
401	    }
402	
403	  while (g_running)
404	    {
405	      sleep(MAIN_LOOP_SLEEP_SECS);
406	    }
407	
408	  LOGI("shutting down...");
409	  ble_cleanup();
410	  LOGI("done");
411	  return EXIT_SUCCESS;
412	}
