94	uint32_t myvendor_sal_radio_ticket_issue(void)
95	{
96	    uint32_t ticket;
97	
98	    pthread_mutex_lock(&g_radio_order_lock);
99	    ticket = g_radio_ticket_next++;
100	    pthread_mutex_unlock(&g_radio_order_lock);
101	    return ticket;
102	}
103	
104	void myvendor_sal_radio_ticket_wait(uint32_t ticket)
105	{
106	    pthread_mutex_lock(&g_radio_order_lock);
107	    while (ticket != g_radio_ticket_serving) {
108	        pthread_cond_wait(&g_radio_order_cond, &g_radio_order_lock);
109	    }
110	    pthread_mutex_unlock(&g_radio_order_lock);
111	}
112	
113	void myvendor_sal_radio_ticket_done(void)
114	{
115	    pthread_mutex_lock(&g_radio_order_lock);
116	    g_radio_ticket_serving++;
117	    pthread_cond_broadcast(&g_radio_order_cond);
118	    pthread_mutex_unlock(&g_radio_order_lock);
119	}
