121	static bt_status_t zblue_le_convert_param(ble_adv_params_t* params, struct bt_le_adv_param* param)
122	{
123	    static bt_addr_le_t addr;
124	
125	    switch (params->adv_type) {
126	    case BT_LE_ADV_IND:
127	    case BT_LE_EXT_ADV_IND:
128	    case BT_LE_LEGACY_ADV_IND:
129	        param->options |= BT_LE_ADV_OPT_CONN;
130	        param->options |= BT_LE_ADV_OPT_SCANNABLE;
131	        break;
132	    case BT_LE_ADV_SCAN_IND:
133	    case BT_LE_EXT_ADV_SCAN_IND:
134	    case BT_LE_LEGACY_ADV_SCAN_IND:
135	        param->options |= BT_LE_ADV_OPT_SCANNABLE;
136	        break;
137	    case BT_LE_ADV_DIRECT_IND:
138	    case BT_LE_EXT_ADV_DIRECT_IND:
139	    case BT_LE_LEGACY_ADV_DIRECT_IND:
140	        param->options |= BT_LE_ADV_OPT_CONN;
141	        param->options |= BT_LE_ADV_OPT_DIR_MODE_LOW_DUTY;
142	        break;
143	    case BT_LE_SCAN_RSP:
144	    case BT_LE_EXT_SCAN_RSP:
145	    case BT_LE_ADV_NONCONN_IND:
146	    case BT_LE_EXT_ADV_NONCONN_IND:
147	    case BT_LE_LEGACY_ADV_NONCONN_IND:
148	    case BT_LE_LEGACY_SCAN_RSP:
149	        break;
150	    default:
151	        BT_LOGE("%s, convert fail, invalid adv_type:%d", __func__, params->adv_type);
152	        return BT_STATUS_PARM_INVALID;
153	    }
154	
155	    switch (params->own_addr_type) {
156	    case BT_LE_ADDR_TYPE_PUBLIC:
157	        param->options |= BT_LE_ADV_OPT_USE_IDENTITY;
158	        break;
159	    }
160	
161	    switch (params->channel_map) {
162	    case BT_LE_ADV_CHANNEL_37_ONLY:
163	        param->options |= BT_LE_ADV_OPT_DISABLE_CHAN_38 | BT_LE_ADV_OPT_DISABLE_CHAN_39;
164	        break;
165	    case BT_LE_ADV_CHANNEL_38_ONLY:
166	        param->options |= BT_LE_ADV_OPT_DISABLE_CHAN_37 | BT_LE_ADV_OPT_DISABLE_CHAN_39;
167	        break;
168	    case BT_LE_ADV_CHANNEL_39_ONLY:
169	        param->options |= BT_LE_ADV_OPT_DISABLE_CHAN_37 | BT_LE_ADV_OPT_DISABLE_CHAN_38;
170	        break;
171	    case BT_LE_ADV_CHANNEL_DEFAULT:
172	        break;
173	    default:
174	        BT_LOGE("%s, convert fail, invalid channel_map:%d", __func__, params->channel_map);
175	        return BT_STATUS_PARM_INVALID;
176	    }
177	
178	    param->interval_min = params->interval;
179	    param->interval_max = params->interval;
180	
181	    if (params->adv_type == BT_LE_ADV_DIRECT_IND
182	        || params->adv_type == BT_LE_EXT_ADV_DIRECT_IND
183	        || params->adv_type == BT_LE_LEGACY_ADV_DIRECT_IND) {
184	        addr.type = params->peer_addr_type;
185	        memcpy(&addr.a, &params->peer_addr, sizeof(bt_address_t));
186	        param->peer = &addr;
187	    }
188	
189	    return BT_STATUS_SUCCESS;
190	}
