192	static size_t pack_ad(struct bt_data* out, size_t max, const uint8_t* data, uint16_t len)
193	{
194	    size_t n = 0;
195	    size_t i = 0;
196	
197	    if (out == NULL || data == NULL || len == 0 || max == 0) {
198	        return 0;
199	    }
200	
201	    while (i < len && n < max) {
202	        if (data[i] < 1 || (i + 1u + (uint16_t)(data[i] - 1)) > len) {
203	            break;
204	        }
205	
206	        out[n].data_len = data[i] - 1;
207	        out[n].type = data[i + 1];
208	        out[n].data = &data[i + 2];
209	        i += (size_t)out[n].data_len + 2;
210	        n++;
211	    }
212	
213	    return n;
214	}
