259	static void STACK_CALL(start_adv)(void* args)
260	{
261	    sal_adapter_req_t* req = args;
262	    struct bt_data ad[CONFIG_BT_EXT_ADV_MAX_ADV_SEGMENT];
263	    struct bt_data sd[CONFIG_BT_EXT_ADV_MAX_ADV_SEGMENT];
264	    size_t ad_n;
265	    size_t sd_n;
266	    int ret;
267	
268	    if (sf32lb52_bt_hci_skip_sync()) {
269	        BT_LOGE("%s, skip HCI (recovering)", __func__);
270	        g_legacy_adv_id = 0;
271	        advertising_on_state_changed(req->adv_id, LE_ADVERTISING_STOPPED);
272	        return;
273	    }
274	
275	    ad_n = pack_ad(ad, SAL_ARRAY_SIZE(ad), req->adpt.start_adv.adv_data,
276	        req->adpt.start_adv.adv_len);
277	    sd_n = pack_ad(sd, SAL_ARRAY_SIZE(sd), req->adpt.start_adv.scan_rsp_data,
278	        req->adpt.start_adv.scan_rsp_len);
279	
280	    if (g_legacy_adv_id != 0) {
281	        (void)bt_le_adv_stop();
282	        g_legacy_adv_id = 0;
283	    }
284	
285	    ret = bt_le_adv_start(&req->adpt.start_adv.param,
286	        ad_n ? ad : NULL, ad_n,
287	        sd_n ? sd : NULL, sd_n);
288	    if (ret == -EALREADY) {
289	        (void)bt_le_adv_stop();
290	        ret = bt_le_adv_start(&req->adpt.start_adv.param,
291	            ad_n ? ad : NULL, ad_n,
292	            sd_n ? sd : NULL, sd_n);
293	    }
294	
295	    if (ret) {
296	        BT_LOGE("%s, bt_le_adv_start fail, err:%d", __func__, ret);
297	        goto done;
298	    }
299	
300	    g_legacy_adv_id = req->adv_id;
301	    advertising_on_state_changed(req->adv_id, LE_ADVERTISING_STARTED);
302	
303	done:
304	    if (req->adpt.start_adv.adv_data)
305	        free(req->adpt.start_adv.adv_data);
306	    if (req->adpt.start_adv.scan_rsp_data)
307	        free(req->adpt.start_adv.scan_rsp_data);
308	}
