310	bt_status_t bt_sal_le_start_adv(bt_controller_id_t id, uint8_t adv_id, ble_adv_params_t* params, uint8_t* adv_data, uint16_t adv_len, uint8_t* scan_rsp_data, uint16_t scan_rsp_len)
311	{
312	    sal_adapter_req_t* req;
313	    int ret;
314	
315	    req = sal_adapter_req(id, adv_id, STACK_CALL(start_adv));
316	    if (!req) {
317	        BT_LOGE("%s, req null", __func__);
318	        return BT_STATUS_NOMEM;
319	    }
320	
321	    ret = zblue_le_convert_param(params, &req->adpt.start_adv.param);
322	    if (ret) {
323	        BT_LOGE("%s, convert fail, err:%d", __func__, ret);
324	        ret = BT_STATUS_PARM_INVALID;
325	        goto error;
326	    }
327	
328	    req->adpt.start_adv.param.options &= ~(BT_LE_ADV_OPT_EXT_ADV | BT_LE_ADV_OPT_NO_2M);
329	
330	    if (adv_len && adv_data) {
331	        req->adpt.start_adv.adv_data = malloc(adv_len);
332	        if (!req->adpt.start_adv.adv_data) {
333	            BT_LOGE("%s, malloc fail", __func__);
334	            ret = BT_STATUS_NOMEM;
335	            goto error;
336	        }
337	
338	        memcpy(req->adpt.start_adv.adv_data, adv_data, adv_len);
339	        req->adpt.start_adv.adv_len = adv_len;
340	    }
341	
342	    if (scan_rsp_len && scan_rsp_data) {
343	        req->adpt.start_adv.scan_rsp_data = malloc(scan_rsp_len);
344	        if (!req->adpt.start_adv.scan_rsp_data) {
345	            BT_LOGE("%s, malloc fail", __func__);
346	            ret = BT_STATUS_NOMEM;
347	            goto error;
348	        }
349	
350	        memcpy(req->adpt.start_adv.scan_rsp_data, scan_rsp_data, scan_rsp_len);
351	        req->adpt.start_adv.scan_rsp_len = scan_rsp_len;
352	    }
353	
354	    return sal_send_req(req);
355	
356	error:
357	    if (req->adpt.start_adv.adv_data)
358	        free(req->adpt.start_adv.adv_data);
359	    if (req->adpt.start_adv.scan_rsp_data)
360	        free(req->adpt.start_adv.scan_rsp_data);
361	    free(req);
362	    return ret;
363	}
